function getVersion() {
  return (
    state.bootstrap.version ??
    state.bootstrap.system?.version ??
    state.bootstrap.runtime?.version ??
    "514cc runtime"
  );
}

function getProductVersionLabel() {
  const version = String(getVersion()).trim();
  return version.toLowerCase().startsWith("514 bot") ? version : `514 Bot · ${version}`;
}

// request() 和 ApiError 已迁移至 api.js（通过 import 导入）

async function initializeAccessToken() {
  const url = new URL(window.location.href);
  const fragment = new URLSearchParams(url.hash.startsWith("#") ? url.hash.slice(1) : url.hash);
  const fragmentToken = fragment.get("token")?.trim() ?? "";
  const conversationDeepLink = conversationDeepLinkFromHash(url.hash);
  if (conversationDeepLink?.conversationId) state.deepLinkConversationId = conversationDeepLink.conversationId;
  if (conversationDeepLink?.runId) state.deepLinkRunId = conversationDeepLink.runId;
  if (conversationDeepLink?.session) state.deepLinkSession = conversationDeepLink.session;
  if (conversationDeepLink?.projectId) state.deepLinkProjectId = conversationDeepLink.projectId;
  const bootstrapNonce = fragment.get("bootstrap")?.trim() ?? "";
  if (bootstrapNonce) {
    let response;
    try {
      response = await fetch("/auth/bootstrap", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ nonce: bootstrapNonce }),
      });
      const payload = await response.json().catch(() => null);
      const issuedToken = typeof payload?.token === "string" ? payload.token.trim() : "";
      if (!response.ok || !issuedToken) {
        const detail = payload?.error?.message ?? payload?.error ?? payload?.message ?? `HTTP ${response.status}`;
        throw new ApiError(`启动登录凭据兑换失败：${detail}`, response.status, payload);
      }
      sessionStorage.setItem(TOKEN_KEY, issuedToken);
      setAccessToken(issuedToken);
    } finally {
      history.replaceState(null, "", `${url.pathname}${url.search}`);
    }
    return;
  }
  if (fragmentToken) {
    sessionStorage.setItem(TOKEN_KEY, fragmentToken);
    setAccessToken(fragmentToken);
    history.replaceState(null, "", `${url.pathname}${url.search}`);
    return;
  }
  setAccessToken(sessionStorage.getItem(TOKEN_KEY) ?? "");
}

// ===== 主题：亮色暖纸 / 暗色暖墨 =====
// data-theme 首帧由 theme.js（<head> 同步脚本）落好；这里负责开关、持久化与系统偏好跟随
const THEME_KEY = "514cc-control-theme";
const UI_FONT_KEY = "514cc-ui-font-size";
const CODE_FONT_KEY = "514cc-code-font-size";
const CODE_WRAP_KEY = "514cc-code-wrap";
const CODE_LINES_KEY = "514cc-code-lines";
const MOTION_KEY = "514cc-motion";
const UI_FACE_KEY = "514cc-ui-font-face";
const CODE_FACE_KEY = "514cc-code-font-face";
const ACCENT_KEY = "514cc-accent";
const DENSITY_KEY = "514cc-density";
const GLASS_ALPHA_KEY = "514cc-glass-alpha";
const GLASS_BLUR_KEY = "514cc-glass-blur";
const GLASS_TINT_KEY = "514cc-glass-tint";
// 背景视频失焦暂停档（默认关）：与外观域其他键同一持久化通道（本地 + 服务端双写）
const BG_PAUSE_BLUR_KEY = "514cc-bg-pause-blur";
// 全局壁纸（对标 dsh-wallpaper-engine 的全局设置面）：JSON 快照，值域收敛见 readGlobalWallpaper。
// 自定义媒体字节不进这里（localStorage 装不下），走 /api/wallpapers/global 字节管线。
const GLOBAL_WALLPAPER_KEY = "514cc-global-wallpaper";
// 壁纸态玻璃不透明度（2026-08-29 自定义程度波）：「auto」= 按壁纸×墨色亮度智能分档；
// "20"–"95" = 手动接管（壁纸激活态的 --forge-glass-alpha 直接用该值，不再套档位偏移）。
// LO 反馈档位自动值仍有雾感且自定义程度不够——自动是起点，不是终点。
const WALLPAPER_GLASS_ALPHA_KEY = "514cc-wallpaper-glass-alpha";
const WALLPAPER_GLASS_ALPHA_AUTO = "auto";
// 壁纸态磨砂强度（2026-08-29 v6）：「auto」= 基线 +2px 档位偏移；"0"–"30" = 手动接管。
// LO 实测：透明度拖到最低后「还是不够清晰」——清晰度的主导因素是 backdrop blur 而非
// alpha；0 = 壁纸完全清晰（无磨砂），可读性由不透明度与内容卡承担。
const WALLPAPER_GLASS_BLUR_KEY = "514cc-wallpaper-glass-blur";
const WALLPAPER_GLASS_BLUR_AUTO = "auto";
// 内容卡玻璃度（2026-08-29 v7）：恢复条/用户气泡/输入台/成员卡这些「浮在壁纸上的内容
// 卡」的实体感——「auto」= 随透出档位（bold 62 / soft 72 / solid 82）；"40"–"95" = 手动。
// LO 反馈内容卡仍是写死的实底感、不可调——玻璃三滑杆之外的第 4 轴。
const CARD_GLASS_ALPHA_KEY = "514cc-card-glass-alpha";
const CARD_GLASS_ALPHA_AUTO = "auto";
// 字体白名单权威定义：新增/删除 face 一律先改这里。
// 首帧脚本 theme.js（防白闪）持有同一白名单的最小副本，修改此处须同步 theme.js 的对应校验，
// 否则刷新首帧会回落 system，等 app.js 接管后才恢复，出现一闪而过的字体跳变。
const UI_FACE_SET = new Set(["system", "yahei", "song"]);
const CODE_FACE_SET = new Set(["system", "cascadia", "jetbrains"]);
const ACCENT_SET = new Set(["copper", "rose", "teal", "indigo"]);
const DENSITY_SET = new Set(["compact", "default", "comfortable"]);
// 玻璃三件套默认值 = 控件中位档；默认时不内联令牌，各玻璃面回落自身艺术基线（零回归）
const GLASS_ALPHA_DEFAULT = 86;
const GLASS_BLUR_DEFAULT = 14;
const GLASS_TINT_DEFAULT = "auto";
// 玻璃底色预设白名单：与暖纸玻璃体系协调的低饱和暖调色；
// "auto" = 不内联 --glass-tint，各玻璃面回退自身底色（--card/--muted）随主题走；
// 非法值一律回退 auto（readGlassTint 收敛）。
const GLASS_TINT_SET = new Set(["auto", "gold", "rose", "teal", "indigo", "ink"]);
const GLASS_TINT_COLORS = {
  gold: "#e8c98d",   // 暖金：纸面暖调的蜜色罩光
  rose: "#dcaab2",   // 玫瑰：低饱和玫瑰灰，与 rose 强调色同族不同性
  teal: "#a8cdc6",   // 青碧：石灰青，冷而不寒
  indigo: "#9fb2d6", // 黛蓝：灰调蓝，暗色下也不突兀
  ink: "#b9b4ac",    // 墨灰：中性暖灰，最接近纸面原色
};
const APPEARANCE_PREVIEW = "```js\nconst themePreview = {\n  paper: \"warm\",\n  ink: \"copper\",\n};\n```";
const themeMedia = window.matchMedia("(prefers-color-scheme: dark)");

function readStoredTheme() {
  try {
    const stored = localStorage.getItem(THEME_KEY);
    return stored === "light" || stored === "dark" ? stored : null;
  } catch {
    return null;
  }
}

function readThemePreference() {
  try {
    const stored = localStorage.getItem(THEME_KEY);
    if (stored === "light" || stored === "dark" || stored === "system") return stored;
  } catch {}
  return "system";
}

function applyTheme(theme, { persist = true } = {}) {
  const next = theme === "dark" ? "dark" : "light";
  document.documentElement.dataset.theme = next;
  if (persist) {
    try {
      localStorage.setItem(THEME_KEY, next);
      schedulePreferenceSync();
    } catch {}
  }
  document.querySelector('meta[name="theme-color"]')?.setAttribute("content", next === "dark" ? "#15171a" : "#f5f6f8");
  // 主题切换重算壁纸调和色（--wall-tint 明度随主题）与玻璃有效令牌
  syncWallpaperGlassEnvironment();
  const toggle = elements["theme-toggle"];
  if (toggle) {
    toggle.querySelector("use")?.setAttribute("href", next === "dark" ? "#lucide-sun" : "#lucide-moon");
    toggle.title = next === "dark" ? "切换为浅色" : "切换为深色";
    toggle.setAttribute("aria-label", toggle.title);
  }
  syncAppearanceControls();
}

function applyThemePreference(pref, { persist = true } = {}) {
  const next = pref === "dark" || pref === "light" || pref === "system" ? pref : "system";
  if (persist) {
    try {
      localStorage.setItem(THEME_KEY, next);
      schedulePreferenceSync();
    } catch {}
  }
  const resolved = next === "system" ? (themeMedia.matches ? "dark" : "light") : next;
  applyTheme(resolved, { persist: false });
}

function readUiFontSize() {
  try {
    const size = Number.parseInt(localStorage.getItem(UI_FONT_KEY), 10);
    if (size >= 12 && size <= 18) return size;
  } catch {}
  return 14;
}

function clearLegacyTextTokens() {
  const root = document.documentElement.style;
  root.removeProperty("--text-base");
  root.removeProperty("--text-sm");
  root.removeProperty("--text-xs");
  root.removeProperty("--text-lg");
}

function applyUiFontSize(px, { persist = true } = {}) {
  const size = Math.min(18, Math.max(12, Number(px) || 14));
  clearLegacyTextTokens();
  document.documentElement.style.setProperty("--ui-font-size", `${size}px`);
  if (persist) {
    try {
      localStorage.setItem(UI_FONT_KEY, String(size));
      schedulePreferenceSync();
    } catch {}
  }
  syncAppearanceControls();
}

function readChoice(key, allowed, fallback) {
  try {
    const value = localStorage.getItem(key);
    if (allowed.has(value)) return value;
  } catch {}
  return fallback;
}

function applyUiFace(face, { persist = true } = {}) {
  const next = UI_FACE_SET.has(face) ? face : "system";
  document.documentElement.dataset.uiFace = next;
  if (persist) {
    try { localStorage.setItem(UI_FACE_KEY, next); } catch {}
    schedulePreferenceSync();
  }
  syncAppearanceControls();
}

function applyCodeFace(face, { persist = true } = {}) {
  const next = CODE_FACE_SET.has(face) ? face : "system";
  document.documentElement.dataset.codeFace = next;
  if (persist) {
    try { localStorage.setItem(CODE_FACE_KEY, next); } catch {}
    schedulePreferenceSync();
  }
  syncAppearanceControls();
}

function applyAccent(accent, { persist = true } = {}) {
  const next = ACCENT_SET.has(accent) ? accent : "copper";
  document.documentElement.dataset.accent = next;
  if (persist) {
    try { localStorage.setItem(ACCENT_KEY, next); } catch {}
    schedulePreferenceSync();
  }
  syncAppearanceControls();
}

function applyDensity(density, { persist = true } = {}) {
  const next = DENSITY_SET.has(density) ? density : "default";
  document.documentElement.dataset.density = next;
  if (persist) {
    try { localStorage.setItem(DENSITY_KEY, next); } catch {}
    schedulePreferenceSync();
  }
  syncAppearanceControls();
}

// ===== 背景与玻璃：透明度 / 模糊 / 底色（对标 dsh 液态玻璃设置页） =====
// 存储格式与令牌格式对齐：alpha 存百分比字符串（"86%"），blur 存像素数字字符串（"14"），
// tint 存预设 ID（含 "auto"）；读取时各自收敛到合法值域，非法回退默认。
function readGlassAlpha() {
  try {
    const size = Number.parseInt(localStorage.getItem(GLASS_ALPHA_KEY), 10);
    if (size >= 40 && size <= 100) return size;
  } catch {}
  return GLASS_ALPHA_DEFAULT;
}

function readGlassBlur() {
  try {
    const size = Number.parseInt(localStorage.getItem(GLASS_BLUR_KEY), 10);
    if (size >= 0 && size <= 30) return size;
  } catch {}
  return GLASS_BLUR_DEFAULT;
}

function applyGlassAlpha(alpha, { persist = true } = {}) {
  const size = Number.parseInt(alpha, 10);
  const next = Number.isFinite(size) && size >= 40 && size <= 100 ? size : GLASS_ALPHA_DEFAULT;
  if (persist) {
    try { localStorage.setItem(GLASS_ALPHA_KEY, `${next}%`); } catch {}
    schedulePreferenceSync();
  }
  // 令牌写入统一走环境同步：壁纸激活态写「壁纸有效值」，无壁纸态维持艺术基线约定
  syncGlassEnvironmentTokens(Boolean(document.body?.classList.contains("team-bg-active")), { alpha: next });
  syncAppearanceControls();
}

function applyGlassBlur(blur, { persist = true } = {}) {
  const size = Number.parseInt(blur, 10);
  const next = Number.isFinite(size) && size >= 0 && size <= 30 ? size : GLASS_BLUR_DEFAULT;
  // 默认档语义 = 「恢复设计基线」：移除整串滤镜令牌 → 顶栏/侧栏严格回到 backdrop-filter: none
  // （不产生层叠上下文，默认零回归），玻璃族回落自身 14px 基线；拖离默认档才写入完整滤镜串，
  // 全部磨砂面同一串连续响应。saturate 与 team.css 基线（150%）对齐，壁纸态另有 165% 有效档。
  if (persist) {
    try { localStorage.setItem(GLASS_BLUR_KEY, String(next)); } catch {}
    schedulePreferenceSync();
  }
  syncGlassEnvironmentTokens(Boolean(document.body?.classList.contains("team-bg-active")), { blur: next });
  syncAppearanceControls();
}

function applyGlassTint(tint, { persist = true } = {}) {
  const next = GLASS_TINT_SET.has(tint) ? tint : GLASS_TINT_DEFAULT;
  const root = document.documentElement.style;
  if (next === "auto") {
    // 移除内联覆盖，让 :root 的 initial 生效 → 各玻璃面回退自身底色随主题走
    root.removeProperty("--glass-tint");
  } else {
    root.setProperty("--glass-tint", GLASS_TINT_COLORS[next]);
  }
  if (persist) {
    try { localStorage.setItem(GLASS_TINT_KEY, next); } catch {}
    schedulePreferenceSync();
  }
  syncAppearanceControls();
}

function readGlassTint() {
  try {
    const value = localStorage.getItem(GLASS_TINT_KEY);
    if (GLASS_TINT_SET.has(value)) return value;
  } catch {}
  return GLASS_TINT_DEFAULT;
}

// ─── 壁纸环境玻璃 v4（2026-08-29 玻璃质感/颜色调和波·卡片浮层版）───
// LO 反馈三轮校准：v2「看不到壁纸」→ v3 档位化后「还是有雾」。雾感根因 =
// 大面积白 tint（玻璃板）+ 大 blur（壁纸抹成色块）+ stage 网格/铜晕盖在照片上。
// v4 规则：**壁纸是主角，玻璃是浮在它上面的卡片**——
//   1. --wall-tint：从壁纸采样 OKLCH、饱和钳到「只沾色相不成色块」的低饱和带、明度按
//      主题收敛——玻璃底色与壁纸同族，暖纸底不再和冷壁纸打架；
//   2. body[data-wall-glass] 三档透出：bold（亮度差大，壁纸垫得起文字，alpha -40、
//      blur 仅 +2——壁纸形状清晰可见）/ soft / solid（亮度贴脸，保可读为主）；
//   3. bold 档下 stage 网格/铜晕/纸幕整体让位（team.css），壁纸不再被设计语言盖住；
//      文字可读性交给「亮壁纸×深墨字」的天然对比 + 内容卡。
// 用户偏好仍优先：alpha/blur 滑杆值是计算基准；色板选了玻璃底色时内联 --glass-tint，
// 经 CSS 回退链 var(--glass-tint, var(--wall-tint, …)) 天然压过采样值。无壁纸态全不生效。
const WALLPAPER_GLASS = Object.freeze({
  // 正文墨色亮度（--forge-ink，art-direction.css 亮 #211d18 / 暗 #f2eadf）：透出额度按
  // 「壁纸亮度 vs 墨色亮度」的距离分级——距离越大壁纸越垫得起文字，越敢透
  // （LO 2026-08-29 反馈「看不到自定义壁纸了」：v2 单级 -8 + 三层叠加只剩 ~8% 透出，
  // 壁纸被闷死；v3 让亮壁纸×深字大胆透到 60%，亮度贴脸时才保实底）。
  inkLum: { light: 0.17, dark: 0.92 },
  tiers: [
    { minGap: 0.5, mode: "bold", alphaDelta: -56, cardAlpha: 62 },
    { minGap: 0.32, mode: "soft", alphaDelta: -26, cardAlpha: 72 },
    { minGap: 0, mode: "solid", alphaDelta: -2, cardAlpha: 82 },
  ],
  alphaFloor: 24,
  blurBoost: 2,
  blurFloor: 4,
  blurCeiling: 30,
  saturate: 165,
  chromaMax: 0.035,
  lightL: 0.965,
  darkL: 0.26,
});
// 预设渐变没有可采样像素：用各预设主锚点色（与 team.css 色板同源）推导同一套调和参数。
const WALLPAPER_PRESET_ANCHORS = Object.freeze({
  aurora: [127, 156, 245],
  ember: [246, 173, 123],
  tide: [99, 179, 237],
  moss: [154, 230, 180],
  noir: [12, 15, 22],
});
let wallpaperSample = null; // { l, c, h }：当前壁纸的 OKLCH 采样；无壁纸/未采样时为 null

function srgbToOklch(r, g, b) {
  const toLinear = (value) => {
    const x = value / 255;
    return x <= 0.04045 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4);
  };
  const R = toLinear(r);
  const G = toLinear(g);
  const B = toLinear(b);
  const l = Math.cbrt(0.4122214708 * R + 0.5363325363 * G + 0.0514459929 * B);
  const m = Math.cbrt(0.2119034982 * R + 0.6806995451 * G + 0.1073969566 * B);
  const s = Math.cbrt(0.0883024619 * R + 0.2817188376 * G + 0.6299787005 * B);
  const okA = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const okB = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  let hue = (Math.atan2(okB, okA) * 180) / Math.PI;
  if (hue < 0) hue += 360;
  return {
    lum: 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
    c: Math.hypot(okA, okB),
    h: hue,
  };
}

function presetWallpaperSample(preset) {
  const anchor = WALLPAPER_PRESET_ANCHORS[preset];
  return anchor ? srgbToOklch(anchor[0], anchor[1], anchor[2]) : null;
}

/** 壁纸均值采样：24×24 下采样读像素（blob 同源不污染画布）；任何失败返回 null 走过渡桥。 */
function sampleWallpaperAverage(media) {
  try {
    const width = media instanceof HTMLVideoElement ? media.videoWidth : media.naturalWidth;
    const height = media instanceof HTMLVideoElement ? media.videoHeight : media.naturalHeight;
    if (!width || !height) return null;
    const size = 24;
    const canvas = document.createElement("canvas");
    canvas.width = size;
    canvas.height = size;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context) return null;
    context.drawImage(media, 0, 0, size, size);
    const { data } = context.getImageData(0, 0, size, size);
    let r = 0;
    let g = 0;
    let b = 0;
    let count = 0;
    for (let index = 0; index < data.length; index += 4) {
      if (data[index + 3] < 128) continue;
      r += data[index];
      g += data[index + 1];
      b += data[index + 2];
      count += 1;
    }
    if (!count) return null;
    return srgbToOklch(r / count, g / count, b / count);
  } catch {
    return null;
  }
}

/** 媒体挂载后采样：图片等 load（已缓存则立即），视频等首帧 loadeddata；
    另挂 decode() 兜底（缓存图偶发丢 load 事件）——resample 幂等，双路只赚不亏。 */
function observeWallpaperMedia(node) {
  if (!node) return;
  const resample = () => {
    const sample = sampleWallpaperAverage(node);
    if (!sample) return;
    wallpaperSample = sample;
    syncWallpaperGlassEnvironment();
  };
  if (node instanceof HTMLVideoElement) node.addEventListener("loadeddata", resample, { once: true });
  else {
    node.addEventListener("load", resample, { once: true });
    if (typeof node.decode === "function") node.decode().then(resample).catch(() => {});
  }
}

/** 当前壁纸的透出档位：|壁纸亮度 - 正文墨色亮度| 距离越大越 bold。
    采样未到/失败（大图解码慢、媒体异常）时按 bold 放行——「看不到壁纸」比「对比
    略降」更伤（LO 实测），可读性由 24px 磨砂兜底；采样到位后按真实距离收敛。 */
function wallpaperGlassTier() {
  if (!wallpaperSample) return WALLPAPER_GLASS.tiers[0];
  const dark = document.documentElement.dataset.theme === "dark";
  const gap = Math.abs(wallpaperSample.lum - (dark ? WALLPAPER_GLASS.inkLum.dark : WALLPAPER_GLASS.inkLum.light));
  return WALLPAPER_GLASS.tiers.find((tier) => gap >= tier.minGap) ?? WALLPAPER_GLASS.tiers[WALLPAPER_GLASS.tiers.length - 1];
}

/** 壁纸态玻璃不透明度偏好：auto 返回 {mode:"auto"}；手动返回 {mode:"manual", value}。
    非法值一律回退 auto（与玻璃三件套同一收敛纪律）。 */
function readWallpaperGlassAlphaPref() {
  try {
    const raw = localStorage.getItem(WALLPAPER_GLASS_ALPHA_KEY);
    if (raw && raw !== WALLPAPER_GLASS_ALPHA_AUTO) {
      const value = Number.parseInt(raw, 10);
      if (Number.isFinite(value) && value >= 20 && value <= 95) return { mode: "manual", value };
    }
  } catch {}
  return { mode: "auto", value: null };
}

/** 壁纸态玻璃不透明度：auto（档位接管）或手动百分比（20–95，滑杆直控）。 */
function applyWallpaperGlassAlpha(pref, { persist = true } = {}) {
  const raw = String(pref ?? WALLPAPER_GLASS_ALPHA_AUTO);
  let next = WALLPAPER_GLASS_ALPHA_AUTO;
  if (raw !== WALLPAPER_GLASS_ALPHA_AUTO) {
    const value = Number.parseInt(raw, 10);
    next = Number.isFinite(value) && value >= 20 && value <= 95 ? String(value) : WALLPAPER_GLASS_ALPHA_AUTO;
  }
  if (persist) {
    try { localStorage.setItem(WALLPAPER_GLASS_ALPHA_KEY, next); } catch {}
    schedulePreferenceSync();
  }
  syncWallpaperGlassEnvironment({ wallAlphaPref: next });
  syncAppearanceControls();
}

/** 壁纸态磨砂强度偏好：auto 返回 {mode:"auto"}；手动返回 {mode:"manual", value}（0–30px）。 */
function readWallpaperGlassBlurPref() {
  try {
    const raw = localStorage.getItem(WALLPAPER_GLASS_BLUR_KEY);
    if (raw && raw !== WALLPAPER_GLASS_BLUR_AUTO) {
      const value = Number.parseInt(raw, 10);
      if (Number.isFinite(value) && value >= 0 && value <= 30) return { mode: "manual", value };
    }
  } catch {}
  return { mode: "auto", value: null };
}

/** 壁纸态磨砂强度：auto（基线 +2 档位偏移）或手动 0–30px（0 = 壁纸完全清晰）。 */
function applyWallpaperGlassBlur(pref, { persist = true } = {}) {
  const raw = String(pref ?? WALLPAPER_GLASS_BLUR_AUTO);
  let next = WALLPAPER_GLASS_BLUR_AUTO;
  if (raw !== WALLPAPER_GLASS_BLUR_AUTO) {
    const value = Number.parseInt(raw, 10);
    next = Number.isFinite(value) && value >= 0 && value <= 30 ? String(value) : WALLPAPER_GLASS_BLUR_AUTO;
  }
  if (persist) {
    try { localStorage.setItem(WALLPAPER_GLASS_BLUR_KEY, next); } catch {}
    schedulePreferenceSync();
  }
  syncWallpaperGlassEnvironment({ wallBlurPref: next });
  syncAppearanceControls();
}

/** 内容卡玻璃度偏好：auto 返回 {mode:"auto"}；手动返回 {mode:"manual", value}（40–95）。 */
function readCardGlassAlphaPref() {
  try {
    const raw = localStorage.getItem(CARD_GLASS_ALPHA_KEY);
    if (raw && raw !== CARD_GLASS_ALPHA_AUTO) {
      const value = Number.parseInt(raw, 10);
      if (Number.isFinite(value) && value >= 40 && value <= 95) return { mode: "manual", value };
    }
  } catch {}
  return { mode: "auto", value: null };
}

/** 内容卡玻璃度：auto（随透出档位 bold 62 / soft 72 / solid 82）或手动 40–95。 */
function applyCardGlassAlpha(pref, { persist = true } = {}) {
  const raw = String(pref ?? CARD_GLASS_ALPHA_AUTO);
  let next = CARD_GLASS_ALPHA_AUTO;
  if (raw !== CARD_GLASS_ALPHA_AUTO) {
    const value = Number.parseInt(raw, 10);
    next = Number.isFinite(value) && value >= 40 && value <= 95 ? String(value) : CARD_GLASS_ALPHA_AUTO;
  }
  if (persist) {
    try { localStorage.setItem(CARD_GLASS_ALPHA_KEY, next); } catch {}
    schedulePreferenceSync();
  }
  syncWallpaperGlassEnvironment({ cardAlphaPref: next });
  syncAppearanceControls();
}

/** 壁纸态玻璃有效令牌：alpha/blur 以用户滑杆值为基准按透出档位偏移；
    手动壁纸不透明度/磨砂（wallAlphaPref 20–95 / wallBlurPref 0–30）直接接管对应维度；
    内容卡玻璃度（cardAlphaPref 40–95 / auto 随档位）写 --forge-card-alpha 供内容卡消费；
    无壁纸态维持「默认不内联、非默认写用户值」的艺术基线约定（零回归）。 */
function syncGlassEnvironmentTokens(active, { alpha = readGlassAlpha(), blur = readGlassBlur(), wallAlphaPref, wallBlurPref, cardAlphaPref } = {}) {
  const root = document.documentElement.style;
  // 两个维度独立解析：本轮传入值优先（滑杆实时预览），否则读持久化——拖 alpha 不丢 blur 手动档，反之亦然
  const resolveRaw = (passed, key, auto) => {
    if (passed !== undefined) return passed;
    try { return localStorage.getItem(key) ?? auto; } catch { return auto; }
  };
  const rawAlpha = resolveRaw(wallAlphaPref, WALLPAPER_GLASS_ALPHA_KEY, WALLPAPER_GLASS_ALPHA_AUTO);
  const rawBlur = resolveRaw(wallBlurPref, WALLPAPER_GLASS_BLUR_KEY, WALLPAPER_GLASS_BLUR_AUTO);
  const rawCard = resolveRaw(cardAlphaPref, CARD_GLASS_ALPHA_KEY, CARD_GLASS_ALPHA_AUTO);
  const manualAlpha = rawAlpha && rawAlpha !== WALLPAPER_GLASS_ALPHA_AUTO ? Number.parseInt(rawAlpha, 10) : null;
  const manualBlur = rawBlur && rawBlur !== WALLPAPER_GLASS_BLUR_AUTO ? Number.parseInt(rawBlur, 10) : null;
  const manualCard = rawCard && rawCard !== CARD_GLASS_ALPHA_AUTO ? Number.parseInt(rawCard, 10) : null;
  const tier = active ? wallpaperGlassTier() : null;
  if (!active) {
    if (alpha === GLASS_ALPHA_DEFAULT) root.removeProperty("--forge-glass-alpha");
    else root.setProperty("--forge-glass-alpha", `${alpha}%`);
  } else if (Number.isFinite(manualAlpha) && manualAlpha >= 20 && manualAlpha <= 95) {
    root.setProperty("--forge-glass-alpha", `${manualAlpha}%`);
  } else {
    const effective = Math.max(WALLPAPER_GLASS.alphaFloor, alpha + (tier ? tier.alphaDelta : 0));
    root.setProperty("--forge-glass-alpha", `${effective}%`);
  }
  if (!active) {
    if (blur === GLASS_BLUR_DEFAULT) root.removeProperty("--forge-glass-filter");
    else root.setProperty("--forge-glass-filter", `blur(${blur}px) saturate(150%)`);
  } else if (Number.isFinite(manualBlur) && manualBlur >= 0 && manualBlur <= 30) {
    root.setProperty("--forge-glass-filter", `blur(${manualBlur}px) saturate(${WALLPAPER_GLASS.saturate}%)`);
  } else {
    const effectiveBlur = Math.min(WALLPAPER_GLASS.blurCeiling, Math.max(blur, WALLPAPER_GLASS.blurFloor) + WALLPAPER_GLASS.blurBoost);
    root.setProperty("--forge-glass-filter", `blur(${effectiveBlur}px) saturate(${WALLPAPER_GLASS.saturate}%)`);
  }
  // 内容卡玻璃度：manual 直控；auto 随档位（写实际计算值，供外观面板滑杆回填显示）
  let cardOut = 72;
  if (!active) {
    root.removeProperty("--forge-card-alpha");
  } else if (Number.isFinite(manualCard) && manualCard >= 40 && manualCard <= 95) {
    cardOut = manualCard;
    root.setProperty("--forge-card-alpha", `${cardOut}%`);
  } else {
    cardOut = tier ? tier.cardAlpha : 72;
    root.setProperty("--forge-card-alpha", `${cardOut}%`);
  }
  // 派生档（预计算成独立令牌）：color-mix 百分位里嵌 calc 在部分渲染引擎会被整条
  // 声明丢弃（真机探针实锤 conv-tabs 回落实底）——CSS 只消费纯 var()，算术全在 JS。
  if (!active) {
    root.removeProperty("--forge-card-alpha-hi");
    root.removeProperty("--forge-card-alpha-lo");
    root.removeProperty("--forge-glass-alpha-hi");
    root.removeProperty("--forge-glass-alpha-mid");
  } else {
    const glassOut = Number.parseFloat(root.getPropertyValue("--forge-glass-alpha")) || alpha;
    root.setProperty("--forge-card-alpha-hi", `${Math.min(cardOut + 12, 97)}%`);
    root.setProperty("--forge-card-alpha-lo", `${Math.max(cardOut - 30, 8)}%`);
    root.setProperty("--forge-glass-alpha-hi", `${Math.min(glassOut + 14, 96)}%`);
    root.setProperty("--forge-glass-alpha-mid", `${Math.min(glassOut + 6, 96)}%`);
  }
}

/** 壁纸环境玻璃统一换装：调和染色 + 有效 alpha/filter。壁纸路径收尾、媒体采样完成、
    主题或玻璃偏好变化都要走这里；无壁纸态只回滚令牌与采样。 */
function syncWallpaperGlassEnvironment({ alpha, blur, wallAlphaPref, wallBlurPref, cardAlphaPref } = {}) {
  const root = document.documentElement.style;
  const active = Boolean(document.body && document.body.classList.contains("team-bg-active"));
  // html 让位：让位链（body/app-shell/stage）之下是 html 的暖纸实底（--bg），壁纸媒体
  // 挂载的几秒窗口期（blob 下载+解码）里整个界面透出的就是它——暖米色 + stage 网格
  // 纹理（LO 截图中央的「暖纸大板」）。html 挂同类把底色换成调和色，窗口期是干净的
  // 「蒙玻璃纯色面」，媒体到位后壁纸照常盖上来；摘除时类同步撤、回暖纸基线零回归。
  document.documentElement.classList.toggle("team-bg-active", active);
  if (active) {
    const dark = document.documentElement.dataset.theme === "dark";
    if (wallpaperSample) {
      const lightness = (dark ? WALLPAPER_GLASS.darkL : WALLPAPER_GLASS.lightL).toFixed(3);
      const chroma = Math.min(wallpaperSample.c, WALLPAPER_GLASS.chromaMax).toFixed(4);
      root.setProperty("--wall-tint", `oklch(${lightness} ${chroma} ${wallpaperSample.h.toFixed(1)})`);
      root.setProperty("--wall-lum", wallpaperSample.lum.toFixed(3));
    } else {
      // 字节在途的过渡桥：冷中性而非暖纸，媒体到位后被采样值替换
      root.setProperty("--wall-tint", dark ? "oklch(0.26 0.008 260)" : "oklch(0.97 0.006 260)");
      root.removeProperty("--wall-lum");
    }
    // 透出档位（bold/soft/solid）：CSS 据此调会话流叠加与卡片减薄
    const tier = wallpaperGlassTier();
    if (tier) document.body.dataset.wallGlass = tier.mode;
    else delete document.body.dataset.wallGlass;
  } else {
    root.removeProperty("--wall-tint");
    root.removeProperty("--wall-lum");
    wallpaperSample = null;
    delete document.body?.dataset.wallGlass;
  }
  syncGlassEnvironmentTokens(active, { alpha, blur, wallAlphaPref, wallBlurPref, cardAlphaPref });
}

function readCodeFontSize() {
  try {
    const size = Number.parseFloat(localStorage.getItem(CODE_FONT_KEY));
    if (size >= 11 && size <= 16) return size;
  } catch {}
  return 12.5;
}

function applyCodeFontSize(px, { persist = true } = {}) {
  const size = Math.min(16, Math.max(11, Number(px) || 12.5));
  document.documentElement.style.setProperty("--code-font-size", `${size}px`);
  if (persist) {
    try {
      localStorage.setItem(CODE_FONT_KEY, String(size));
      schedulePreferenceSync();
    } catch {}
  }
  syncAppearanceControls();
}

function readStoredFlag(key) {
  try {
    return localStorage.getItem(key) === "on";
  } catch {
    return false;
  }
}

function applyCodeWrap(on, { persist = true } = {}) {
  document.documentElement.dataset.codeWrap = on ? "on" : "off";
  if (persist) {
    try {
      localStorage.setItem(CODE_WRAP_KEY, on ? "on" : "off");
      schedulePreferenceSync();
    } catch {}
  }
  syncCodeGutters();
  syncAppearanceControls();
}

function applyCodeLines(on, { persist = true } = {}) {
  document.documentElement.dataset.codeLines = on ? "on" : "off";
  if (persist) {
    try {
      localStorage.setItem(CODE_LINES_KEY, on ? "on" : "off");
      schedulePreferenceSync();
    } catch {}
  }
  syncCodeGutters();
  syncAppearanceControls();
}

function readMotionPreference() {
  try {
    return localStorage.getItem(MOTION_KEY) === "reduce" ? "reduce" : "system";
  } catch {
    return "system";
  }
}

function applyMotionPreference(pref, { persist = true } = {}) {
  const next = pref === "reduce" ? "reduce" : "system";
  document.documentElement.dataset.motion = next;
  if (persist) {
    try {
      localStorage.setItem(MOTION_KEY, next);
      schedulePreferenceSync();
    } catch {}
  }
  syncAppearanceControls();
}

// 背景视频窗口失焦暂停开关（遮挡暂停第二档）：默认关闭——键缺失/"off" 即关；
// "on" 时窗口 blur 冻结背景视频解码与氛围动画，focus 恢复（见 installTeamBgSuspensionOnce）。
function readBgPauseBlurPreference() {
  try {
    return localStorage.getItem(BG_PAUSE_BLUR_KEY) === "on";
  } catch {
    return false;
  }
}

function applyBgPauseBlurPreference(on, { persist = true } = {}) {
  if (persist) {
    try {
      localStorage.setItem(BG_PAUSE_BLUR_KEY, on ? "on" : "off");
      schedulePreferenceSync();
    } catch {}
  }
  setSwitchState("appearance-bg-pause-blur", on);
}

function syncCodeGutters(root = document) {
  const show = document.documentElement.dataset.codeLines === "on"
    && document.documentElement.dataset.codeWrap !== "on";
  root.querySelectorAll?.(".code-wrap")?.forEach((wrap) => {
    const pre = wrap.querySelector("pre.md-code, pre");
    if (!pre) return;
    let gutter = wrap.querySelector(".md-code-gutter");
    if (!show) {
      gutter?.remove();
      wrap.classList.remove("has-gutter");
      return;
    }
    const code = pre.querySelector("code") || pre;
    const lines = (code.textContent || "").replace(/\n$/, "").split("\n").length;
    if (!gutter) {
      gutter = document.createElement("span");
      gutter.className = "md-code-gutter";
      gutter.setAttribute("aria-hidden", "true");
      pre.parentNode.insertBefore(gutter, pre);
    }
    gutter.textContent = Array.from({ length: Math.max(1, lines) }, (_, index) => String(index + 1)).join("\n");
    wrap.classList.add("has-gutter");
  });
}

function setSwitchState(id, on) {
  const button = byId(id);
  if (!button) return;
  button.classList.toggle("is-on", on);
  button.setAttribute("aria-checked", String(on));
}

function mountAppearancePreviews() {
  for (const id of ["appearance-preview-light", "appearance-preview-dark"]) {
    const node = byId(id);
    if (!node || node.dataset.previewReady === "1") continue;
    node.innerHTML = renderMarkdown(APPEARANCE_PREVIEW);
    renderRichContent(node);
    node.dataset.previewReady = "1";
  }
  syncCodeGutters(byId("view-appearance") || document);
}

function syncAppearanceControls() {
  const pref = readThemePreference();
  const resolved = document.documentElement.dataset.theme === "dark" ? "dark" : "light";
  document.querySelectorAll("[data-appearance-theme]").forEach((button) => {
    const on = button.dataset.appearanceTheme === pref;
    button.setAttribute("aria-checked", String(on));
    button.classList.toggle("is-active", on);
  });
  document.querySelectorAll("[data-appearance-active]").forEach((badge) => {
    badge.hidden = badge.dataset.appearanceActive !== resolved;
  });
  const uiSize = readUiFontSize();
  const font = byId("appearance-font-size");
  const fontRange = byId("appearance-font-range");
  if (font && Number(font.value) !== uiSize) font.value = String(uiSize);
  if (fontRange && Number(fontRange.value) !== uiSize) fontRange.value = String(uiSize);
  const codeSize = readCodeFontSize();
  const code = byId("appearance-code-size");
  const codeRange = byId("appearance-code-range");
  if (code && Number(code.value) !== codeSize) code.value = String(codeSize);
  if (codeRange && Number(codeRange.value) !== codeSize) codeRange.value = String(codeSize);
  setSwitchState("appearance-code-wrap", document.documentElement.dataset.codeWrap === "on");
  setSwitchState("appearance-code-lines", document.documentElement.dataset.codeLines === "on");
  setSwitchState("appearance-motion", readMotionPreference() === "reduce");
  setSwitchState("appearance-bg-pause-blur", readBgPauseBlurPreference());
  const uiFace = document.documentElement.dataset.uiFace || "system";
  const codeFace = document.documentElement.dataset.codeFace || "system";
  const accent = document.documentElement.dataset.accent || "copper";
  const density = document.documentElement.dataset.density || "default";
  // 字体 WYSIWYG 按钮组：按当前 dataset 值刷新选中态（aria-pressed + is-active 复用卡片选中视觉）
  document.querySelectorAll("[data-appearance-ui-face]").forEach((button) => {
    const on = button.dataset.appearanceUiFace === uiFace;
    button.setAttribute("aria-pressed", String(on));
    button.classList.toggle("is-active", on);
  });
  document.querySelectorAll("[data-appearance-code-face]").forEach((button) => {
    const on = button.dataset.appearanceCodeFace === codeFace;
    button.setAttribute("aria-pressed", String(on));
    button.classList.toggle("is-active", on);
  });
  document.querySelectorAll("[data-appearance-accent]").forEach((button) => {
    const on = button.dataset.appearanceAccent === accent;
    button.setAttribute("aria-checked", String(on));
    button.classList.toggle("is-active", on);
  });
  document.querySelectorAll("[data-appearance-density]").forEach((button) => {
    const on = button.dataset.appearanceDensity === density;
    button.setAttribute("aria-checked", String(on));
    button.classList.toggle("is-active", on);
  });
  // 背景与玻璃：滑杆/数字回填 + 色板选中态（读持久化真源，与 apply 收敛后一致）
  const glassAlpha = readGlassAlpha();
  const glassBlur = readGlassBlur();
  const glassTint = readGlassTint();
  const alphaInput = byId("appearance-glass-alpha");
  const alphaRange = byId("appearance-glass-alpha-range");
  const blurInput = byId("appearance-glass-blur");
  const blurRange = byId("appearance-glass-blur-range");
  if (alphaInput && Number(alphaInput.value) !== glassAlpha) alphaInput.value = String(glassAlpha);
  if (alphaRange && Number(alphaRange.value) !== glassAlpha) alphaRange.value = String(glassAlpha);
  if (blurInput && Number(blurInput.value) !== glassBlur) blurInput.value = String(glassBlur);
  if (blurRange && Number(blurRange.value) !== glassBlur) blurRange.value = String(glassBlur);
  document.querySelectorAll("[data-glass-tint]").forEach((button) => {
    const on = button.dataset.glassTint === glassTint;
    button.setAttribute("aria-checked", String(on));
    button.classList.toggle("is-active", on);
  });
  // 壁纸态玻璃不透明度：滑杆永远可拖——auto 时显示档位当前计算值（拖动瞬间即手动
  // 接管并落盘），manual 时显示用户值；「自动」按钮切回档位接管。
  const wallGlassPref = readWallpaperGlassAlphaPref();
  const wallGlassAuto = byId("appearance-wallpaper-glass-auto");
  const wallGlassRange = byId("appearance-wallpaper-glass-alpha");
  const wallGlassValue = byId("appearance-wallpaper-glass-alpha-value");
  if (wallGlassAuto) {
    const isAuto = wallGlassPref.mode === "auto";
    wallGlassAuto.classList.toggle("is-active", isAuto);
    wallGlassAuto.setAttribute("aria-pressed", String(isAuto));
  }
  if (wallGlassRange) {
    wallGlassRange.disabled = false;
    let shown = GLASS_ALPHA_DEFAULT;
    if (wallGlassPref.mode === "manual") {
      shown = wallGlassPref.value;
    } else {
      // auto：档位计算值写在壁纸态 inline 令牌里，读它回填（无壁纸回落基线值）
      const token = document.documentElement.style.getPropertyValue("--forge-glass-alpha");
      const parsed = Number.parseInt(token, 10);
      if (Number.isFinite(parsed)) shown = parsed;
    }
    if (Number(wallGlassRange.value) !== shown) wallGlassRange.value = String(shown);
  }
  if (wallGlassValue) wallGlassValue.textContent = wallGlassPref.mode === "manual" ? `${wallGlassPref.value}%` : `自动 · ${wallGlassRange ? wallGlassRange.value : "?"}%`;
  // 壁纸态磨砂强度：同款交互（永远可拖，auto 显示档位计算值——解析 --forge-glass-filter 的 blur px）
  const wallBlurPref = readWallpaperGlassBlurPref();
  const wallBlurAuto = byId("appearance-wallpaper-glass-blur-auto");
  const wallBlurRange = byId("appearance-wallpaper-glass-blur");
  const wallBlurValue = byId("appearance-wallpaper-glass-blur-value");
  if (wallBlurAuto) {
    const isAuto = wallBlurPref.mode === "auto";
    wallBlurAuto.classList.toggle("is-active", isAuto);
    wallBlurAuto.setAttribute("aria-pressed", String(isAuto));
  }
  if (wallBlurRange) {
    wallBlurRange.disabled = false;
    let shownBlur = 14;
    if (wallBlurPref.mode === "manual") {
      shownBlur = wallBlurPref.value;
    } else {
      const token = document.documentElement.style.getPropertyValue("--forge-glass-filter");
      const parsed = Number.parseInt((token.match(/blur\((\d+(?:\.\d+)?)px\)/) || [])[1], 10);
      if (Number.isFinite(parsed)) shownBlur = parsed;
    }
    if (Number(wallBlurRange.value) !== shownBlur) wallBlurRange.value = String(shownBlur);
  }
  if (wallBlurValue) wallBlurValue.textContent = wallBlurPref.mode === "manual" ? `${wallBlurPref.value}px` : `自动 · ${wallBlurRange ? wallBlurRange.value : "?"}px`;
  // 内容卡玻璃度：恢复条/气泡/输入台/成员卡的实体感——auto 显示档位计算值（--forge-card-alpha）
  const cardGlassPref = readCardGlassAlphaPref();
  const cardGlassAuto = byId("appearance-card-glass-auto");
  const cardGlassRange = byId("appearance-card-glass-alpha");
  const cardGlassValue = byId("appearance-card-glass-alpha-value");
  if (cardGlassAuto) {
    const isAuto = cardGlassPref.mode === "auto";
    cardGlassAuto.classList.toggle("is-active", isAuto);
    cardGlassAuto.setAttribute("aria-pressed", String(isAuto));
  }
  if (cardGlassRange) {
    cardGlassRange.disabled = false;
    let shownCard = 72;
    if (cardGlassPref.mode === "manual") {
      shownCard = cardGlassPref.value;
    } else {
      const token = document.documentElement.style.getPropertyValue("--forge-card-alpha");
      const parsed = Number.parseInt(token, 10);
      if (Number.isFinite(parsed)) shownCard = parsed;
    }
    if (Number(cardGlassRange.value) !== shownCard) cardGlassRange.value = String(shownCard);
  }
  if (cardGlassValue) cardGlassValue.textContent = cardGlassPref.mode === "manual" ? `${cardGlassPref.value}%` : `自动 · ${cardGlassRange ? cardGlassRange.value : "?"}%`;
  // 全局壁纸卡片：读持久化真源回填（色板/开关/下拉/适配/上传按钮态）
  renderGlobalWallpaperCard();
}

function resetAppearance() {
  for (const key of [THEME_KEY, UI_FONT_KEY, CODE_FONT_KEY, CODE_WRAP_KEY, CODE_LINES_KEY, MOTION_KEY, BG_PAUSE_BLUR_KEY, UI_FACE_KEY, CODE_FACE_KEY, ACCENT_KEY, DENSITY_KEY, GLASS_ALPHA_KEY, GLASS_BLUR_KEY, GLASS_TINT_KEY, GLOBAL_WALLPAPER_KEY]) {
    try { localStorage.removeItem(key); } catch {}
  }
  applyThemePreference("system");
  applyUiFontSize(14);
  applyCodeFontSize(12.5);
  applyCodeWrap(false);
  applyCodeLines(false);
  applyMotionPreference("system");
  applyUiFace("system");
  applyCodeFace("system");
  applyAccent("copper");
  applyDensity("default");
  applyGlassAlpha(GLASS_ALPHA_DEFAULT);
  applyGlassBlur(GLASS_BLUR_DEFAULT);
  applyGlassTint(GLASS_TINT_DEFAULT);
  // 全局壁纸整体回落默认（不删服务端媒体字节：重置只清偏好，字节由「移除」按钮显式清理）
  persistGlobalWallpaper(normalizeGlobalWallpaper(null));
}

// ===== 外观偏好服务端同步（双写 + 启动补齐） =====
// 桌面壳按地址+端口隔离 localStorage，而内核每次启动随机挑端口（pick_free_kernel_port），
// 本地偏好等同一换壳就丢一份；所以每次持久化外观键时同步一份到服务端，
// 新壳启动时从服务端补齐缺失键。键清单单一定义在这里，与服务端白名单一致。
const APPEARANCE_PREF_KEYS = [
  THEME_KEY,
  UI_FONT_KEY,
  CODE_FONT_KEY,
  UI_FACE_KEY,
  CODE_FACE_KEY,
  ACCENT_KEY,
  DENSITY_KEY,
  CODE_WRAP_KEY,
  CODE_LINES_KEY,
  MOTION_KEY,
  BG_PAUSE_BLUR_KEY,
  GLASS_ALPHA_KEY,
  GLASS_BLUR_KEY,
  GLASS_TINT_KEY,
  GLOBAL_WALLPAPER_KEY,
  WALLPAPER_GLASS_ALPHA_KEY,
  WALLPAPER_GLASS_BLUR_KEY,
  CARD_GLASS_ALPHA_KEY,
];
let preferencesSyncTimer = null;

/** 采集当前 localStorage 里的全部外观键，供双写/补齐共用。 */
function collectAppearancePreferences() {
  const prefs = {};
  for (const key of APPEARANCE_PREF_KEYS) {
    try {
      const value = localStorage.getItem(key);
      if (value !== null) prefs[key] = value;
    } catch {}
  }
  return prefs;
}

/** 防抖把外观偏好推到服务端：多次连续改动只发一次请求；失败静默——
    本地 localStorage 仍是第一真源，服务端只是跨端口备份，不许阻塞/打扰用户。 */
function schedulePreferenceSync() {
  clearTimeout(preferencesSyncTimer);
  preferencesSyncTimer = setTimeout(() => {
    preferencesSyncTimer = null;
    void syncPreferencesToServer();
  }, 300);
}

async function syncPreferencesToServer() {
  try {
    await apiRequest(API.preferences, { method: "PUT", body: collectAppearancePreferences() });
  } catch {
    /* 静默：服务端不可达/未就绪时退化为纯 localStorage，不弹错 */
  }
}

/** 启动补齐：只回填 localStorage 中缺失的键（用户刚改过的本地值优先，绝不覆盖），
    补齐后重放对应 apply 函数生效；网络失败静默回退纯 localStorage。 */
async function hydratePreferencesFromServer() {
  let remote = null;
  try {
    const payload = await apiRequest(API.preferences);
    remote = payload && typeof payload === "object" && payload.preferences && typeof payload.preferences === "object"
      ? payload.preferences
      : null;
  } catch {
    return; // 服务端不可达：保持纯 localStorage 路径，首帧已由 theme.js 兜底
  }
  if (!remote) return;
  const missing = {};
  for (const key of APPEARANCE_PREF_KEYS) {
    const value = remote[key];
    if (typeof value !== "string" || !value) continue;
    let local = null;
    try { local = localStorage.getItem(key); } catch {}
    if (local === null) missing[key] = value;
  }
  if (!Object.keys(missing).length) return;
  for (const [key, value] of Object.entries(missing)) {
    try { localStorage.setItem(key, value); } catch {}
  }
  // 本地键全部补完后按新值重放外观域（纯重放，不重绑事件）；
  // apply* 内部自带合法值域收敛，非法远端值落回默认。
  replayAppearanceFromStorage();
  // v8.3 回退修复：replayAppearanceFromStorage 不含壁纸重放——「换壳/换端口（本地空）
  // + 水合晚于首屏 applyActiveTeamBackground」的竞态下壁纸偏好补齐了却没人重挂，
  // 界面停在无壁纸基线（LO「有时候会回退」的主因）。补齐命中壁纸键时显式重挂一次。
  if (missing[GLOBAL_WALLPAPER_KEY] !== undefined) {
    applyActiveTeamBackground();
  }
}

// 控制台形态第七轮：桌面壳窗口控制条。仅在 Tauri 壳内激活——壳由构建期
// .decorations(false) 去掉原生标题栏，这里接管拖拽与最小化/最大化/关闭；
// 浏览器模式没有 __TAURI_INTERNALS__，直接跳过（窗口钮保持 hidden）。
// 控制台形态第九轮：应用菜单列（Codex 式 ≡ ‹ › + 文件/编辑/视图/帮助）。
// frameless 去掉原生标题栏后原生菜单栏随之消失，常用入口在 web 层补回；
// 浏览器与桌面壳都需要它，所以独立于 initializeWindowChrome 调用。
// 视图历史：setView 全程 history.replaceState（浏览器栈不涨），这里自养双栈供 ‹ ›。
// 栈里是完整路由快照（视图 + 设置焦点 + config 面 + Skill/MCP 工位），不是裸 view id——
// 否则「模型设置 → 钩子」同属 config，后退会丢面。
let viewHistoryBack = [];
let viewHistoryForward = [];
let viewHistoryMute = false;

function captureViewRoute() {
  return {
    view: state.view,
    settingsFocus: state.settingsFocus ?? null,
    configSurface: state.configSurface ?? null,
    capabilityWorkspace: state.capabilityWorkspace === "mcp" ? "mcp" : "skills",
  };
}

function titleForRoute(route) {
  if (!route?.view) return "";
  if (route.view === "observability" && route.settingsFocus === "memory") return "记忆";
  if (route.view === "config") {
    if (route.configSurface === "providers") return "连接";
    if (route.configSurface === "hooks") return "钩子";
    if (route.configSurface === "local-runtime") return "本机运行时";
    if (route.configSurface === "sources") return "运行席位";
    if (route.configSurface === "capabilities") return route.capabilityWorkspace === "mcp" ? "MCP 服务器" : "技能";
  }
  if (route.view === "market") return "插件";
  return FORGE_VIEW_TITLES[route.view] ?? "";
}

function syncChromeNavButtons() {
  const back = byId("chrome-nav-back");
  const forward = byId("chrome-nav-forward");
  const backTo = viewHistoryBack.at(-1);
  const forwardTo = viewHistoryForward.at(-1);
  if (back) {
    back.disabled = !backTo;
    const label = backTo ? `后退到「${titleForRoute(backTo)}」` : "后退";
    back.title = label;
    back.setAttribute("aria-label", label);
  }
  if (forward) {
    forward.disabled = !forwardTo;
    const label = forwardTo ? `前进到「${titleForRoute(forwardTo)}」` : "前进";
    forward.title = label;
    forward.setAttribute("aria-label", label);
  }
}

function rememberRouteChange(previous) {
  if (!previous?.view || !FORGE_VIEW_TITLES[previous.view]) {
    syncChromeNavButtons();
    return;
  }
  const next = recordRouteChange(previous, captureViewRoute(), {
    back: viewHistoryBack,
    mute: viewHistoryMute,
  });
  viewHistoryBack = next.back;
  if (next.recorded) viewHistoryForward = [];
  syncChromeNavButtons();
}

function applyViewRoute(route) {
  if (!route?.view) return;
  setView(route.view, {
    settingsFocus: route.settingsFocus,
    configSurface: route.configSurface,
    capabilityWorkspace: route.capabilityWorkspace,
  });
}

function pulseChromeButton(id) {
  const button = byId(id);
  if (!button || button.disabled) return;
  button.classList.remove("is-fired");
  void button.offsetWidth;
  button.classList.add("is-fired");
  window.setTimeout(() => button.classList.remove("is-fired"), 280);
}

function chromeNavigate(direction) {
  const stepped = stepHistory(direction, {
    back: viewHistoryBack,
    forward: viewHistoryForward,
    current: captureViewRoute(),
  });
  if (!stepped.target) {
    viewHistoryBack = stepped.back;
    viewHistoryForward = stepped.forward;
    syncChromeNavButtons();
    return;
  }
  viewHistoryBack = stepped.back;
  viewHistoryForward = stepped.forward;
  pulseChromeButton(direction === "back" ? "chrome-nav-back" : "chrome-nav-forward");
  viewHistoryMute = true;
  try { applyViewRoute(stepped.target); } finally { viewHistoryMute = false; }
  syncChromeNavButtons();
}

const RAIL_COLLAPSED_KEY = "514cc:workbench-rail-collapsed";

function applyRailCollapsed(collapsed, { persist = true } = {}) {
  document.querySelectorAll(".workbench-shell").forEach((shell) => shell.classList.toggle("rail-collapsed", collapsed));
  const toggle = byId("chrome-rail-toggle");
  if (toggle) {
    toggle.setAttribute("aria-pressed", String(collapsed));
    const label = collapsed ? "展开左栏" : "收起左栏";
    toggle.title = label;
    toggle.setAttribute("aria-label", label);
    toggle.querySelector("use")?.setAttribute("href", collapsed ? "#lucide-panel-right" : "#lucide-panel-left");
  }
  if (persist) { try { localStorage.setItem(RAIL_COLLAPSED_KEY, collapsed ? "1" : "0"); } catch {} }
}

function railCollapsed() {
  return document.querySelector(".workbench-shell")?.classList.contains("rail-collapsed") ?? false;
}

// 焦点捕获：HTML 菜单会抢走输入框焦点（原生菜单不会）——编辑命令先归还焦点再执行
let lastEditableField = null;
window.addEventListener("focusin", (event) => {
  if (event.target?.closest?.("input, textarea, [contenteditable]")) lastEditableField = event.target;
});

function editMenuAction(command) {
  if (lastEditableField?.isConnected) lastEditableField.focus();
  // execCommand 作用于当前焦点可编辑元素；paste 被 Chromium 安全策略拦时给诚实回落
  const ok = document.execCommand(command);
  if (!ok && command === "paste") toast("浏览器安全策略拦了菜单粘贴，请用 Ctrl+V", "warning", 2600);
}

function initializeChromeMenus() {
  const invoke = window.__TAURI_INTERNALS__?.invoke;
  byId("chrome-rail-toggle")?.addEventListener("click", () => {
    applyRailCollapsed(!railCollapsed());
    pulseChromeButton("chrome-rail-toggle");
  });
  byId("chrome-nav-back")?.addEventListener("click", () => chromeNavigate("back"));
  byId("chrome-nav-forward")?.addEventListener("click", () => chromeNavigate("forward"));
  document.addEventListener("keydown", (event) => {
    if (!event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
    if (historyShortcutBlocked(event)) return;
    event.preventDefault();
    chromeNavigate(event.key === "ArrowLeft" ? "back" : "forward");
  });
  window.addEventListener("mouseup", (event) => {
    if (event.button !== 3 && event.button !== 4) return;
    if (document.querySelector("dialog[open], .cmd-palette-overlay.is-open")) return;
    event.preventDefault();
    chromeNavigate(event.button === 3 ? "back" : "forward");
  });
  syncChromeNavButtons();
  const bindMenu = (id, buildItems) => {
    byId(id)?.addEventListener("click", (event) => {
      showContextMenuFromTrigger(event.currentTarget, buildItems());
    });
  };
  bindMenu("chrome-menu-file", () => [
    { icon: "plus", label: "新建任务（Ctrl+N）", action: () => byId("new-task-row")?.click() },
    { icon: "refresh", label: "重新加载界面（Ctrl+R）", action: () => location.reload() },
    "---",
    { icon: "remove", label: "关闭窗口（最小化到托盘）", disabled: typeof invoke !== "function", action: () => invoke("plugin:window|close").catch(() => {}) },
  ]);
  bindMenu("chrome-menu-edit", () => [
    { icon: "undo", label: "撤销（Ctrl+Z）", action: () => editMenuAction("undo") },
    { icon: "redo", label: "重做（Ctrl+Y）", action: () => editMenuAction("redo") },
    "---",
    { icon: "cut", label: "剪切（Ctrl+X）", action: () => editMenuAction("cut") },
    { icon: "copy", label: "复制（Ctrl+C）", action: () => editMenuAction("copy") },
    { icon: "paste", label: "粘贴（Ctrl+V）", action: () => editMenuAction("paste") },
    "---",
    { icon: "selectAll", label: "全选（Ctrl+A）", action: () => editMenuAction("selectAll") },
  ]);
  bindMenu("chrome-menu-view", () => [
    // 视图导航（PM 走查修复：桌面端此前唯一的全局视图入口只有 Ctrl+K 面板；
    // 名为「视图」的菜单里却没有视图，14 视图大半不可发现）。单一真源 nav-config，
    // 与抽屉/命令面板同源，新视图自动进菜单。当前视图标 check，其余用 plus 占位
    // （菜单图标集是固定小集合，见 MENU_ICONS）。
    ...NAV_GROUPS.flatMap((group, index) => [
      ...(index > 0 ? ["---"] : []),
      ...group.views.map((view) => ({
        icon: state.view === view ? "check" : "plus",
        label: `${NAV_ITEMS[view]?.label ?? view}（${group.label}）`,
        action: () => setView(view),
      })),
    ]),
    "---",
    { icon: "panelLeft", label: railCollapsed() ? "展开左栏" : "收起左栏", action: () => applyRailCollapsed(!railCollapsed()) },
    "---",
    { icon: "moon", label: "切换主题（亮/暗）", action: () => elements["theme-toggle"]?.click() },
    { icon: "zoomIn", label: "放大界面字号", action: () => applyUiFontSize(readUiFontSize() + 1) },
    { icon: "zoomOut", label: "缩小界面字号", action: () => applyUiFontSize(readUiFontSize() - 1) },
    { icon: "history", label: "重置界面字号", action: () => applyUiFontSize(14) },
    "---",
    { icon: "terminal", label: "打开/收起底部终端（Ctrl+`）", action: () => byId("global-terminal-toggle")?.click() },
    { icon: "panelRight", label: "打开/关闭环境信息", action: () => byId("global-mc-toggle")?.click() },
  ]);
  bindMenu("chrome-menu-help", () => [
    { icon: "eye", label: "体系观测", action: () => setView("observability") },
    { icon: "info", label: "关于 514 Bot", action: () => void confirmAction({
      eyebrow: "关于",
      title: "514 Bot · Control Center",
      rows: [["版本", String(getVersion())], ["形态", "Tauri 2 桌面壳 + 本地内核"], ["内核", "apps/control-center"]],
      confirmLabel: "好",
    }) },
  ]);
  applyRailCollapsed(readStoredFlag(RAIL_COLLAPSED_KEY), { persist: false });
  syncChromeNavButtons();
}

function initializeWindowChrome() {
  const invoke = window.__TAURI_INTERNALS__?.invoke;
  const controls = byId("window-controls");
  const botControls = byId("bot-window-controls");
  if (typeof invoke !== "function" || (!controls && !botControls)) return;
  document.documentElement.classList.add("is-desktop-shell");
  if (controls) controls.hidden = false;
  if (botControls) botControls.hidden = false;
  const windowCommand = (command) => () => invoke(command).catch(() => {});
  byId("window-minimize")?.addEventListener("click", windowCommand("plugin:window|minimize"));
  byId("window-maximize")?.addEventListener("click", windowCommand("plugin:window|toggle_maximize"));
  byId("window-close")?.addEventListener("click", windowCommand("plugin:window|close"));
  byId("bot-window-minimize")?.addEventListener("click", windowCommand("plugin:window|minimize"));
  byId("bot-window-maximize")?.addEventListener("click", windowCommand("plugin:window|toggle_maximize"));
  byId("bot-window-close")?.addEventListener("click", windowCommand("plugin:window|close"));
  // 手动拖拽区：旧控制台使用 topbar，Bot 默认表面隐藏了 topbar，改用各视图标题栏。
  // 不用 data-tauri-drag-region：壳内注入脚本对子元素的命中判定随版本漂移，手动语义可测。
  const interactiveSelector = "button, a, input, select, textarea, .topbar-nav, .topbar-actions, [contenteditable=\"true\"]";
  const dragSurfaceSelector = [
    ".topbar",
    ".bot-roster-header",
    ".bot-conversation-header",
    ".bot-panel-header",
    ".bot-computer-view-header",
    ".bot-settings-header",
  ].join(", ");
  document.querySelectorAll(dragSurfaceSelector).forEach((surface) => {
    surface.addEventListener("pointerdown", (event) => {
      if (event.button !== 0) return;
      if (event.target.closest(interactiveSelector)) return;
      event.preventDefault();
      invoke(event.detail === 2 ? "plugin:window|toggle_maximize" : "plugin:window|start_dragging").catch(() => {});
    });
  });
  // 壳内没有地址栏与原生刷新键：补 Ctrl+R 整页重载。登录态在 sessionStorage（兑换后的
  // 令牌），reload 安全；一次性 bootstrap nonce 已在首次兑换完毕，不参与重载。
  window.addEventListener("keydown", (event) => {
    if (!event.ctrlKey || event.key.toLowerCase() !== "r") return;
    event.preventDefault();
    location.reload();
  });
  // W1.2 审批快捷裁决：bot 视图下 Y=批准 / N=拒绝最新一条 pending 审批。
  // 守卫：焦点在可编辑元素/打开的对话框/命令面板时不触发；广域授权禁批（与卡片 disabled 同口径）。
  document.addEventListener("keydown", (event) => {
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    const key = String(event.key || "").toLowerCase();
    if (key !== "y" && key !== "n") return;
    if (state.view !== "bot") return;
    const active = document.activeElement;
    if (active && (active.isContentEditable
      || ["input", "textarea", "select"].includes(String(active.tagName || "").toLowerCase()))) return;
    if (document.querySelector("dialog[open], .cmd-palette-overlay.is-open")) return;
    const run = botConversationActiveRun(botActiveConversation());
    if (!run?.id) return;
    const pending = state.approvals.filter((item) => String(item.runId || "") === String(run.id) && (item.status ?? "pending") === "pending");
    if (!pending.length) return;
    const latest = pending[pending.length - 1];
    if (botState.approvalInFlight.has(String(latest.id))) return;
    const broad = String(latest?.method || "") === "item/permissions/requestApproval";
    const decision = key === "y" ? "approve" : "deny";
    if (decision === "approve" && broad) {
      toast("广域权限授权暂不支持快捷批准，请使用安全诊断页", "warning");
      return;
    }
    event.preventDefault();
    void resolveInlineApproval(latest.id, decision);
  });
}

/** 按当前 localStorage 值重放全部外观 apply（不绑事件）：
    启动初始化与远端补齐共用这一份，补齐命中时不能把外观面板监听器再绑一遍。 */
function replayAppearanceFromStorage() {
  applyThemePreference(readThemePreference(), { persist: false });
  applyUiFontSize(readUiFontSize(), { persist: false });
  applyCodeFontSize(readCodeFontSize(), { persist: false });
  applyCodeWrap(readStoredFlag(CODE_WRAP_KEY), { persist: false });
  applyCodeLines(readStoredFlag(CODE_LINES_KEY), { persist: false });
  applyMotionPreference(readMotionPreference(), { persist: false });
  applyBgPauseBlurPreference(readBgPauseBlurPreference(), { persist: false });
  applyUiFace(readChoice(UI_FACE_KEY, UI_FACE_SET, "system"), { persist: false });
  applyCodeFace(readChoice(CODE_FACE_KEY, CODE_FACE_SET, "system"), { persist: false });
  applyAccent(readChoice(ACCENT_KEY, ACCENT_SET, "copper"), { persist: false });
  applyDensity(readChoice(DENSITY_KEY, DENSITY_SET, "default"), { persist: false });
  applyGlassAlpha(readGlassAlpha(), { persist: false });
  applyGlassBlur(readGlassBlur(), { persist: false });
  applyGlassTint(readGlassTint(), { persist: false });
  // 全局壁纸卡片回填 + 轮播计时器对齐（签名不变不重建）；氛围层由团队渲染路径统一重挂
  renderGlobalWallpaperCard();
  restartGlobalWallpaperRotation();
  // 启动对账不在这里发：replay 会被 initializeTheme 与水合各跑一次，而 HEAD 对账若早于
  // 水合完成，会在空 localStorage 上写出 {preset:"none",hasCustom:true} 的默认快照，
  // 把服务端 preset:"custom" 的回填挡在门外（「换壳后壁纸丢失」主因）。改由启动链路在
  // hydratePreferencesFromServer 结算后串行调用，见 boot 处。
}

async function reconcileGlobalWallpaperMedia() {
  // 只对「已有本地偏好但 hasCustom=false」做存在性修复（旧内核自愈误伤/换端残留）。
  // 本地没有壁纸键 = 水合尚未发生或服务端没有偏好：此时写快照必然是默认值，
  // 既挡回填又会被偏好双写 PUT 回服务端降级真源——直接等待水合路径处理。
  let local = null;
  try { local = localStorage.getItem(GLOBAL_WALLPAPER_KEY); } catch {}
  if (!local || readGlobalWallpaper().hasCustom) return;
  try {
    await requestBlob(API.globalWallpaper, { method: "HEAD" });
    // 服务端确实存着字节：恢复开关位（不动 preset——用户是否启用全局层仍由色板选择决定）
    persistGlobalWallpaper({ hasCustom: true });
  } catch { /* 404/网络失败：维持现状，无自定义媒体 */ }
}

function initializeTheme() {
  replayAppearanceFromStorage();
  mountAppearancePreviews();
  elements["theme-toggle"]?.addEventListener("click", () => {
    applyThemePreference(document.documentElement.dataset.theme === "dark" ? "light" : "dark");
  });
  themeMedia.addEventListener("change", (event) => {
    if (!readStoredTheme()) applyTheme(event.matches ? "dark" : "light", { persist: false });
  });
  byId("appearance-theme-grid")?.addEventListener("click", (event) => {
    const card = event.target.closest("[data-appearance-theme]");
    if (card) applyThemePreference(card.dataset.appearanceTheme);
  });
  const bindFont = (inputId, rangeId, apply) => {
    const input = byId(inputId);
    const range = byId(rangeId);
    input?.addEventListener("change", (event) => apply(event.target.value));
    range?.addEventListener("input", (event) => apply(event.target.value));
  };
  bindFont("appearance-font-size", "appearance-font-range", applyUiFontSize);
  bindFont("appearance-code-size", "appearance-code-range", applyCodeFontSize);
  byId("appearance-code-wrap")?.addEventListener("click", () => {
    applyCodeWrap(document.documentElement.dataset.codeWrap !== "on");
  });
  byId("appearance-code-lines")?.addEventListener("click", () => {
    applyCodeLines(document.documentElement.dataset.codeLines !== "on");
  });
  byId("appearance-motion")?.addEventListener("click", () => {
    applyMotionPreference(readMotionPreference() === "reduce" ? "system" : "reduce");
  });
  // 背景视频失焦暂停档：默认关，开启后窗口失焦冻结背景视频（参考项目同款档位）
  byId("appearance-bg-pause-blur")?.addEventListener("click", () => {
    applyBgPauseBlurPreference(!readBgPauseBlurPreference());
  });
  byId("appearance-reset")?.addEventListener("click", resetAppearance);
  // 字体 WYSIWYG 按钮组：点击卡片直接套用既有 apply*（含持久化 + schedulePreferenceSync），选中态由 syncAppearanceControls 收敛
  byId("appearance-ui-face")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-appearance-ui-face]");
    if (button) applyUiFace(button.dataset.appearanceUiFace);
  });
  byId("appearance-code-face")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-appearance-code-face]");
    if (button) applyCodeFace(button.dataset.appearanceCodeFace);
  });
  byId("appearance-accent-grid")?.addEventListener("click", (event) => {
    const card = event.target.closest("[data-appearance-accent]");
    if (card) applyAccent(card.dataset.appearanceAccent);
  });
  byId("appearance-density")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-appearance-density]");
    if (button) applyDensity(button.dataset.appearanceDensity);
  });
  // 背景与玻璃：滑杆拖动即时生效（input），数字框 change 提交；复用既有防抖同步通道。
  // 注：replayAppearanceFromStorage 在本函数前已跑过，滑杆重读持久化真源回填，
  // 这里不重复读控件初值，避免 HTML 默认值覆盖服务端补齐值。
  const bindGlassRange = (rangeId, apply) => {
    byId(rangeId)?.addEventListener("input", (event) => apply(event.target.value));
  };
  const bindGlassNumber = (inputId, apply) => {
    byId(inputId)?.addEventListener("change", (event) => apply(event.target.value));
  };
  bindGlassRange("appearance-glass-alpha-range", applyGlassAlpha);
  bindGlassNumber("appearance-glass-alpha", applyGlassAlpha);
  // 壁纸态玻璃不透明度：input 实时预览（不落盘）+ change 落盘（与融合调节双路同构）；
  // 「自动」按钮切回档位接管。
  const wallGlassAutoBtn = byId("appearance-wallpaper-glass-auto");
  const wallGlassRangeInput = byId("appearance-wallpaper-glass-alpha");
  if (wallGlassAutoBtn) {
    wallGlassAutoBtn.addEventListener("click", () => applyWallpaperGlassAlpha(WALLPAPER_GLASS_ALPHA_AUTO));
  }
  if (wallGlassRangeInput) {
    // input 即接管并落盘：拖动瞬间进入手动模式（否则 auto 回填会把滑杆拉回档位值，永远拖不动）
    wallGlassRangeInput.addEventListener("input", () => applyWallpaperGlassAlpha(wallGlassRangeInput.value));
    wallGlassRangeInput.addEventListener("change", () => applyWallpaperGlassAlpha(wallGlassRangeInput.value));
  }
  const wallBlurAutoBtn = byId("appearance-wallpaper-glass-blur-auto");
  const wallBlurRangeInput = byId("appearance-wallpaper-glass-blur");
  if (wallBlurAutoBtn) {
    wallBlurAutoBtn.addEventListener("click", () => applyWallpaperGlassBlur(WALLPAPER_GLASS_BLUR_AUTO));
  }
  if (wallBlurRangeInput) {
    wallBlurRangeInput.addEventListener("input", () => applyWallpaperGlassBlur(wallBlurRangeInput.value));
    wallBlurRangeInput.addEventListener("change", () => applyWallpaperGlassBlur(wallBlurRangeInput.value));
  }
  const cardGlassAutoBtn = byId("appearance-card-glass-auto");
  const cardGlassRangeInput = byId("appearance-card-glass-alpha");
  if (cardGlassAutoBtn) {
    cardGlassAutoBtn.addEventListener("click", () => applyCardGlassAlpha(CARD_GLASS_ALPHA_AUTO));
  }
  if (cardGlassRangeInput) {
    cardGlassRangeInput.addEventListener("input", () => applyCardGlassAlpha(cardGlassRangeInput.value));
    cardGlassRangeInput.addEventListener("change", () => applyCardGlassAlpha(cardGlassRangeInput.value));
  }
  bindGlassRange("appearance-glass-blur-range", applyGlassBlur);
  bindGlassNumber("appearance-glass-blur", applyGlassBlur);
  byId("appearance-glass-tint-grid")?.addEventListener("click", (event) => {
    const card = event.target.closest("[data-glass-tint]");
    if (card) applyGlassTint(card.dataset.glassTint);
  });
  // 全局壁纸（外观面板）：色板/上传/移除/适配/覆盖/轮播，全部即时生效并落盘。
  // file input 选完即清 value，允许连续两次选择同一文件。
  elements["appearance-wallpaper-presets"]?.addEventListener("click", (event) => {
    const swatch = event.target.closest("[data-global-wallpaper-preset]");
    if (swatch && !swatch.disabled) persistGlobalWallpaper({ preset: swatch.dataset.globalWallpaperPreset });
  });
  elements["appearance-wallpaper-file"]?.addEventListener("change", (event) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (file) void uploadGlobalWallpaper(file);
  });
  elements["appearance-wallpaper-clear"]?.addEventListener("click", () => void removeGlobalWallpaperMedia());
  document.querySelectorAll("[data-wallpaper-fit]").forEach((button) => {
    button.addEventListener("click", () => persistGlobalWallpaper({ fit: button.dataset.wallpaperFit }));
  });
  elements["appearance-wallpaper-override"]?.addEventListener("click", () => {
    persistGlobalWallpaper({ overrideTeam: !readGlobalWallpaper().overrideTeam });
  });
  elements["appearance-wallpaper-rotate"]?.addEventListener("click", () => {
    const rotate = readGlobalWallpaper().rotate;
    persistGlobalWallpaper({ rotate: { ...rotate, enabled: !rotate.enabled } });
  });
  elements["appearance-wallpaper-interval"]?.addEventListener("change", (event) => {
    persistGlobalWallpaper({ rotate: { ...readGlobalWallpaper().rotate, intervalMin: Number(event.target.value) || 5 } });
  });
  elements["appearance-wallpaper-order"]?.addEventListener("change", (event) => {
    persistGlobalWallpaper({ rotate: { ...readGlobalWallpaper().rotate, order: event.target.value } });
  });
  // 全局壁纸 3 轴滤镜：还原默认走 schema 真源（保持与默认值同对象引用便于 JSON.stringify 比较）
  elements["appearance-wallpaper-tune-reset"]?.addEventListener("click", () => {
    persistGlobalWallpaper({ filter: { ...GLOBAL_WALLPAPER_DEFAULT.filter } });
  });
  // 全局壁纸拖拽上传：dragover 高亮态 → drop 直接走上传管线（与点击 file input 同一路径）。
  // dragenter/dragleave 计数：子元素进出也会触发，靠 counter 避免父容器闪烁。
  const wallpaperLabel = elements["appearance-wallpaper-file"]?.closest("label.team-bg-upload");
  if (wallpaperLabel) {
    let depth = 0;
    const onEnter = (event) => {
      if (!hasFiles(event)) return;
      event.preventDefault();
      depth += 1;
      wallpaperLabel.classList.add("is-dragover");
    };
    const onLeave = (event) => {
      if (!hasFiles(event)) return;
      event.preventDefault();
      depth = Math.max(0, depth - 1);
      if (depth === 0) wallpaperLabel.classList.remove("is-dragover");
    };
    const onOver = (event) => {
      if (!hasFiles(event)) return;
      event.preventDefault();
      event.dataTransfer.dropEffect = "copy";
    };
    const onDrop = (event) => {
      if (!hasFiles(event)) return;
      event.preventDefault();
      depth = 0;
      wallpaperLabel.classList.remove("is-dragover");
      const file = event.dataTransfer?.files?.[0];
      if (file) void uploadGlobalWallpaper(file);
    };
    wallpaperLabel.addEventListener("dragenter", onEnter);
    wallpaperLabel.addEventListener("dragleave", onLeave);
    wallpaperLabel.addEventListener("dragover", onOver);
    wallpaperLabel.addEventListener("drop", onDrop);
  }
  document.querySelectorAll("[data-appearance-apply]").forEach((button) => {
    button.addEventListener("click", () => applyThemePreference(button.dataset.appearanceApply));
  });
  byId("settings-open-browser")?.addEventListener("click", () => {
    setView("workbench");
    handleWorkbenchEnvironmentAction("browser");
  });
}

function setApiState(next, detail = "") {
  state.apiState = next;
  const badge = elements["api-connection-badge"];
  const dot = badge.querySelector(".status-dot");
  const label = badge.querySelector("span:last-child");
  const normalized = normalizeStatus(next);
  badge.className = `connection-badge is-${normalized}`;
  dot.className = `status-dot is-${normalized}`;
  label.textContent = normalized === "ok" ? "API 已连接" : normalized === "error" ? "API 未连接" : "API 连接中";
  badge.title = detail || label.textContent;
  if (elements["global-status-version"]) elements["global-status-version"].textContent = getProductVersionLabel();
}

function setEventState(next) {
  state.eventState = next;
  const normalized = normalizeStatus(next);
  const connected = normalized === "ok";
  elements["metric-events"].textContent = connected ? "已连接" : normalized === "error" ? "已断开" : "连接中";
  elements["metric-events-detail"].textContent = connected ? `${state.events.length} 条会话事件` : "SSE /api/events";
  elements["event-live-state"].textContent = connected ? "实时" : normalized === "error" ? "重连中" : "连接中";
  elements["event-live-state"].className = `event-live-state is-${normalized}`;
}

function compactToastRegion() {
  const region = elements["toast-region"];
  if (!region) return;
  const seen = new Set();
  for (const item of [...region.children].reverse()) {
    const key = `${item.dataset.toastType || "info"}\u0000${item.textContent || ""}`;
    if (seen.has(key)) item.remove();
    else seen.add(key);
  }
  const limit = window.matchMedia?.("(max-width: 1024px)").matches ? 2 : 3;
  while (region.childElementCount > limit) region.firstElementChild?.remove();
}

function toast(message, type = "info", duration = 3600) {
  const item = document.createElement("div");
  item.className = `toast is-${type}`;
  item.dataset.toastType = type;
  item.textContent = redact(message);
  elements["toast-region"].append(item);
  compactToastRegion();
  window.setTimeout(() => item.remove(), duration);
}

window.addEventListener("resize", compactToastRegion, { passive: true });

function appendDiagnostic(message, level = "info", { render = true } = {}) {
  const now = new Date().toISOString();
  state.diagnosticLog.unshift(`[${now}] [${level.toUpperCase()}] ${redact(message)}`);
  state.diagnosticLog = state.diagnosticLog.slice(0, 120);
  if (render) renderDiagnosticLog();
}

function normalizeSource(item, index) {
  const path = item.path ?? item.file ?? item.source_path ?? item.source ?? "";
  const id = String(item.id ?? item.key ?? item.source_id ?? path ?? `source-${index}`);
  const format = String(item.format ?? item.kind ?? item.type ?? path.split(".").pop() ?? "text").toLowerCase();
  const scope = String(item.scope ?? item.layer ?? item.zone ?? "source").toLowerCase();
  const secret = Boolean(item.secret ?? item.is_secret ?? (scope === "secret" || format === "secret"));
  const runtime = Boolean(item.runtime ?? item.is_runtime ?? (scope === "runtime" || scope === "generated"));
  const explicitReadOnly = item.read_only ?? item.readOnly ?? (item.writable === false ? true : null);
  const transactionBlocked = Boolean(item.transactionBlocked ?? item.transaction_blocked);
  return {
    ...item,
    id,
    name: String(item.name ?? item.label ?? path.split(/[\\/]/).pop() ?? id),
    path: String(path || id),
    format,
    scope,
    secret,
    runtime,
    transactionBlocked,
    readOnly: Boolean(explicitReadOnly ?? false) || secret || runtime || transactionBlocked,
    status: String(item.status ?? item.sync_status ?? item.state ?? "unknown").toLowerCase(),
    sha256: String(item.sha256 ?? item.sha ?? item.etag ?? ""),
  };
}

function normalizeRun(item, index) {
  const id = String(item.id ?? item.run_id ?? item.runId ?? `run-${index}`);
  const prompt = item.prompt ?? item.task ?? item.message ?? item.input ?? "";
  const route = item.route ?? item.routing ?? item.decision ?? null;
  const coordinatorId = String(item.coordinatorId ?? item.coordinator_id ?? "");
  const startAgentId = String(item.startAgentId ?? item.start_agent_id ?? "");
  const executionOwnerId = String(item.executionOwnerId ?? item.execution_owner_id ?? startAgentId);
  const rawSessions = item.sessions ?? item.agents ?? [];
  const sessions = normalizeRunSessions(rawSessions, coordinatorId);
  return {
    ...item,
    id,
    title: String(item.title ?? item.name ?? String(prompt).slice(0, 60) ?? `任务 ${index + 1}`),
    prompt: String(prompt),
    status: String(item.status ?? item.state ?? "planning").toLowerCase().replaceAll("-", "_"),
    risk: String(item.risk_level ?? item.risk ?? "unknown"),
    createdAt: item.created_at ?? item.createdAt ?? item.started_at ?? item.startedAt ?? null,
    updatedAt: item.updated_at ?? item.updatedAt ?? item.finished_at ?? item.finishedAt ?? null,
    route,
    coordinatorId: coordinatorId || null,
    startAgentId: startAgentId || null,
    executionOwnerId: executionOwnerId || null,
    sessions,
    messages: unwrapList(item.messages ?? item.turns ?? [], ["messages", "turns"]),
  };
}

function normalizeComponent(item, index) {
  const rawStatus = item.status ?? item.state ?? item.ok;
  return {
    ...item,
    id: String(item.id ?? item.key ?? item.name ?? `component-${index}`),
    name: String(item.name ?? item.label ?? item.id ?? `组件 ${index + 1}`),
    // detail 兜底链补 reason：dormant/missing 等状态的解释在 reason 字段（version 只有在线组件有）
    detail: String(item.detail ?? item.description ?? item.message ?? item.version ?? item.reason ?? ""),
    status: normalizeStatus(rawStatus),
    rawStatus, // 原始态供 statusText 出专属文案（待命/未安装/未配置——normalize 会压扁语义）
    latency: item.latency_ms ?? item.latency ?? item.duration_ms ?? null,
  };
}

function normalizeModel(item, index) {
  const capabilities = item.strengths ?? item.capabilities ?? item.roles ?? [];
  return {
    ...item,
    id: String(item.id ?? item.model_id ?? item.key ?? `model-${index}`),
    role: String(item.role ?? item.assignment ?? item.category ?? "候选"),
    adapter: String(item.adapter ?? item.provider ?? item.cli ?? "adapter"),
    model: String(item.model ?? item.model_id ?? item.name ?? item.label ?? item.id ?? "运行时选择"),
    strengths: Array.isArray(capabilities) ? capabilities.map(String) : [String(capabilities)],
    status: normalizeStatus(item.status ?? item.availability ?? item.available ?? item.enabled),
    verifiedAt:
      item.last_verified_at ??
      item.verified_at ??
      item.checked_at ??
      (Array.isArray(item.evidence) ? item.evidence.map((entry) => entry.verifiedAt ?? entry.verified_at).filter(Boolean).sort().at(-1) : null),
  };
}

function normalizeHealth(payload) {
  const components = objectList(payload, ["components", "services", "checks"]);
  if (components.length) return components.map(normalizeComponent);
  const status = normalizeStatus(payload?.status ?? payload?.state ?? payload?.ok);
  return DEFAULT_COMPONENTS.map((item) =>
    item.id === "control-api" ? { ...item, status: status === "unknown" ? "ok" : status } : { ...item },
  );
}

function normalizeRoute(payload) {
  const data = payload?.route ?? payload?.decision ?? payload ?? {};
  const primaryRaw = data.primary ?? data.selected ?? data.chosen ?? data.model ?? data.agent ?? {};
  const primary =
    typeof primaryRaw === "string"
      ? { name: primaryRaw, adapter: primaryRaw }
      : {
          ...primaryRaw,
          name: String(primaryRaw.label ?? primaryRaw.name ?? primaryRaw.model ?? primaryRaw.id ?? primaryRaw.agent ?? "未选择"),
          adapter: String(primaryRaw.adapter ?? primaryRaw.provider ?? primaryRaw.cli ?? primaryRaw.role ?? ""),
        };
  const reasonsRaw = data.reasons ?? data.reason ?? data.explanation ?? data.rationale ?? [];
  const reasons = Array.isArray(reasonsRaw) ? reasonsRaw.map(String) : reasonsRaw ? [String(reasonsRaw)] : [];
  const candidates = unwrapList(data.candidates ?? [], ["candidates"]);
  const selectedScore = data.selected?.score ?? primaryRaw?.score ?? data.score ?? data.confidence;
  const specialReason = data.specialRoute?.reason ?? data.specialRoute?.ruleId ?? "";
  return {
    ...data,
    primary,
    reasons,
    candidates,
    confidence: selectedScore ?? "--",
    policy: specialReason || data.policy || data.preferredProvider || data.rule || data.route_gate || "--",
    verifier: data.independent ?? data.verifier ?? data.review_by ?? data.required_verifier ?? null,
    createdAt: data.created_at ?? data.timestamp ?? new Date().toISOString(),
  };
}

function describePermissionFlag(label, value) {
  // 缺省字段（schema 未标注 shell/network 等）不进详情行——渲染 "shell undefined"
  // 是把内部缺省漏给用户的真缺陷（2026-08-30 PM 走查）
  if (value === undefined || value === null || value === "") return null;
  if (value === false) return `禁止${label}`;
  if (value === true) return `允许${label}`;
  return `${label} ${value}`;
}

function policiesFromPermissions(permissions) {
  if (!permissions || typeof permissions !== "object" || Array.isArray(permissions)) return [];
  const rows = [];
  if (permissions.defaultMode) {
    rows.push({
      name: "默认模式",
      detail: "新任务未显式指定权限档时使用",
      value: String(permissions.defaultMode),
      status: "ok",
    });
  }
  for (const [id, mode] of Object.entries(permissions.modes || {})) {
    if (!mode || typeof mode !== "object") continue;
    rows.push({
      name: id,
      detail: [
        describePermissionFlag("写入", mode.write),
        describePermissionFlag("shell", mode.shell),
        describePermissionFlag("网络", mode.network),
      ].filter(Boolean).join(" · ") || "未标注",
      value: mode.approvalRequired ? "按动作审批" : "直接执行",
      status: mode.approvalRequired ? "warning" : "ok",
    });
  }
  const approval = permissions.approval && typeof permissions.approval === "object" ? permissions.approval : {};
  if (Object.keys(approval).length) {
    rows.push({
      name: "审批契约",
      detail: `TTL ${Math.max(0, Math.round(Number(approval.ttlMs || 0) / 1000))}s · 绑定动作哈希 ${approval.bindToActionSha256 ? "是" : "否"}`,
      value: approval.defaultDecision === "deny" ? "超时默认拒绝" : String(approval.defaultDecision || "未标注"),
      status: approval.defaultDecision === "deny" ? "ok" : "warning",
    });
  }
  const secrets = permissions.secrets && typeof permissions.secrets === "object" ? permissions.secrets : {};
  if (Object.keys(secrets).length) {
    const leaking = Boolean(secrets.exposeValues || secrets.persistValues);
    rows.push({
      name: "Secret 策略",
      detail: `允许引用 ${(secrets.allowedReferences || []).join(" / ") || "未标注"}`,
      value: leaking ? "明文外发或落盘仍开启" : "不外发明文、不落盘",
      status: leaking ? "error" : "ok",
    });
  }
  const writes = permissions.runtimeWrites && typeof permissions.runtimeWrites === "object" ? permissions.runtimeWrites : {};
  if (Object.keys(writes).length) {
    rows.push({
      name: "运行时写配置",
      detail: [writes.requiresApproval && "需审批", writes.requiresBackup && "需备份", writes.requiresReadback && "需回读"].filter(Boolean).join(" · ") || "无额外护栏",
      value: writes.allowed ? "允许" : "默认禁止",
      status: writes.allowed ? "warning" : "ok",
    });
  }
  return rows;
}

let approvalSnapshotRuntimeGeneration = null;

function approvalSnapshotFromPayload(payload) {
  const candidate = payload?.approvalSnapshot && typeof payload.approvalSnapshot === "object"
    ? payload.approvalSnapshot
    : payload;
  if (!candidate || typeof candidate !== "object") return null;
  const hasRevisionField = Object.hasOwn(candidate, "revision");
  const hasRuntimeGenerationField = Object.hasOwn(candidate, "runtimeGeneration")
    || (payload?.runtime && typeof payload.runtime === "object" && Object.hasOwn(payload.runtime, "generation"));
  const revision = candidate.revision;
  const runtimeGenerationValue = candidate.runtimeGeneration ?? payload?.runtime?.generation;
  const runtimeGeneration = normalizeApprovalRuntimeGeneration(runtimeGenerationValue);
  return {
    approvals: Array.isArray(candidate.approvals) ? candidate.approvals : null,
    epoch: typeof candidate.epoch === "string" && candidate.epoch ? candidate.epoch : null,
    revision,
    hasRevisionField,
    runtimeGeneration,
    runtimeGenerationValid: !hasRuntimeGenerationField || runtimeGeneration !== null,
    versioned: Boolean(candidate.epoch || hasRevisionField || candidate.runtimeGeneration != null),
  };
}

function applyApprovalSnapshot(payload, { source = "审批快照" } = {}) {
  const snapshot = approvalSnapshotFromPayload(payload);
  if (!snapshot || !snapshot.approvals) {
    appendDiagnostic(`${source}缺少 approvals 数组，拒绝覆盖当前授权状态`, "warning");
    return { accepted: false, invalid: true };
  }
  if (!snapshot.versioned) {
    // 只允许最初的旧服务器兼容回退；一旦已有版本快照，裸列表不能清空或回盖它。
    if (approvalSnapshotEpoch || approvalSnapshotRevision > 0) {
      appendDiagnostic(`${source}缺少 epoch/revision，拒绝覆盖当前授权状态`, "warning");
      return { accepted: false, stale: true };
    }
    state.approvals = snapshot.approvals;
    return { accepted: true, legacy: true };
  }
  if (!snapshot.epoch || typeof snapshot.revision !== "number"
    || !Number.isSafeInteger(snapshot.revision) || snapshot.revision < 0) {
    appendDiagnostic(`${source}的 epoch/revision 无效，拒绝覆盖当前授权状态`, "warning");
    return { accepted: false, invalid: true };
  }
  if (snapshot.runtimeGenerationValid === false) {
    appendDiagnostic(`${source}的 runtimeGeneration 无效，拒绝覆盖当前授权状态`, "warning");
    return { accepted: false, invalid: true };
  }
  const version = compareApprovalSnapshotVersions(
    {
      epoch: approvalSnapshotEpoch,
      revision: approvalSnapshotRevision,
      runtimeGeneration: approvalSnapshotRuntimeGeneration,
    },
    snapshot,
  );
  if (!version.accepted) {
    appendDiagnostic(`${source}${version.reason || "版本已过期"}，拒绝覆盖当前授权状态`, "warning");
    return { accepted: false, invalid: version.invalid === true, stale: version.stale === true };
  }
  if (version.resetRevision) approvalSnapshotRevision = 0;
  approvalSnapshotEpoch = version.epoch;
  if (version.runtimeGeneration !== null) approvalSnapshotRuntimeGeneration = version.runtimeGeneration;
  approvalSnapshotRevision = snapshot.revision;
  state.approvals = snapshot.approvals;
  nativeNotifications.syncApprovals(state.approvals); // W2.4：新 pending → 系统通知（幂等 diff）
  return { accepted: true };
}

function extractBootstrapData(payload) {
  if (!payload || typeof payload !== "object") return;
  state.bootstrap = payload;
  state.memberCatalog = Array.isArray(payload.memberCatalog)
    ? payload.memberCatalog
    : Array.isArray(payload.teamCatalog) ? payload.teamCatalog : [];
  if (payload.operatorProfile && typeof payload.operatorProfile === "object") {
    state.operatorProfile = {
      label: String(payload.operatorProfile.label || "AEMEATH"),
      avatar: payload.operatorProfile.avatar === "custom" ? "custom" : "",
      hiddenMemberIds: [...new Set((Array.isArray(payload.operatorProfile.hiddenMemberIds)
        ? payload.operatorProfile.hiddenMemberIds
        : []).map((id) => String(id || "").trim()).filter(Boolean))],
    };
  }
  state.runtimeCatalog = Array.isArray(payload.runtimeCatalog) ? payload.runtimeCatalog : [];
  // Bot 是成员目录与个人通讯录偏好的共同投影；两者都落入 state 后再绘制，
  // 避免 bootstrap 首帧短暂重新显示已经移出的内置成员。
  botRenderRoster?.();
  memberLibrary?.syncBootstrap();
  runtimeSeatManager?.refreshBindings?.(); // bootstrap 慢聚合晚到时，席位绑定区块从「未绑定」旧空态自愈
  syncModelPick(); // providers（含 modelOptions）就绪后立刻联动 /model 目录——renderTeams 可能已先跑过

  const models = objectList(payload, ["providers", "models", "model_registry", "adapters"]);
  if (models.length) state.models = models.map(normalizeModel);

  const derivedPolicies = policiesFromPermissions(payload.permissions);
  if (derivedPolicies.length) {
    state.policies = derivedPolicies;
  } else {
    const policies = objectList(payload.permissions ?? payload.security ?? payload, ["permissions", "policies", "permission_policies", "modes"]);
    if (policies.length) {
      state.policies = policies.map((item, index) => ({
        name: String(item.name ?? item.label ?? item.id ?? `策略 ${index + 1}`),
        detail: String(item.detail ?? item.description ?? item.scope ?? ""),
        value: String(item.value ?? item.decision ?? item.mode ?? item.status ?? "已加载"),
        status: normalizeStatus(item.status ?? item.state ?? "ok"),
      }));
    }
  }

  const secrets = objectList(payload.security ?? payload, ["secrets", "secret_refs", "credentials"]);
  if (secrets.length) {
    state.secrets = secrets.map((item, index) => ({
      name: String(item.name ?? item.label ?? item.id ?? `Secret ${index + 1}`),
      reference: String(item.reference ?? item.ref ?? item.provider ?? "secure reference"),
      configured: item.configured ?? item.available ?? item.present ?? null,
      fingerprint: item.fingerprint ?? item.last4 ?? "",
    }));
  }

  const sources = unwrapList(payload, ["sources", "config_sources"]);
  if (sources.length && !state.sources.length) state.sources = sources.map(normalizeSource);
  const runs = unwrapList(payload, ["runs", "active_runs"]);
  if (runs.length && !state.runs.length) state.runs = runs.map(normalizeRun);
  applyApprovalSnapshot(payload, { source: "bootstrap 审批快照" });
  if (payload.health) {
    state.health = payload.health;
    state.components = normalizeHealth(payload.health);
    applyHealthToModels(payload.health);
  }
  if (payload.routing && (payload.routing.primary || payload.routing.selected || payload.routing.decision)) {
    state.routePreview = normalizeRoute(payload.routing);
  }
}

function applyHealthToModels(healthPayload) {
  const healthItems = objectList(healthPayload, ["items", "components", "services", "checks"]);
  const byProvider = new Map(healthItems.map((item) => [String(item.id ?? item.key ?? item.name), item]));
  state.models = state.models.map((model) => {
    const health = byProvider.get(String(model.id));
    return health
      ? {
          ...model,
          status: normalizeStatus(health.status ?? health.available),
          verifiedAt: health.checked_at ?? health.timestamp ?? model.verifiedAt,
          version: health.version ?? model.version,
        }
      : model;
  });
}

async function loadBootstrap() {
  const previousTeamCatalog = teamCatalogSignature();
  const payload = await request(API.bootstrap);
  extractBootstrapData(payload);
  void ensureAutomationModelCatalogs(); // 自动化模型目录的 CLI 动态补齐，不阻塞启动链
  await hydrateAvatarCatalog(requestBlob, {
    members: state.memberCatalog,
    operatorProfile: state.operatorProfile,
  });
  refreshAvatarSurfaces();
  if (elements["global-status-version"]) elements["global-status-version"].textContent = getProductVersionLabel();
  renderModels();
  renderSecurity();
  reconcileTeamFormCatalog(previousTeamCatalog);
  refreshTeamData();
  return payload;
}

async function loadHealth() {
  const generation = loadHealthRequestGate.begin();
  const started = performance.now();
  try {
    const payload = await request(API.health);
    if (!loadHealthRequestGate.isCurrent(generation)) return payload;
    state.health = payload;
    state.components = normalizeHealth(payload);
    applyHealthToModels(payload);
    botRenderRoster?.();
    botRenderAgent(botState.agentId);
    state.diagnostics = upsertDiagnostic(state.diagnostics, {
      path: API.health,
      method: "GET",
      status: "ok",
      latency: performance.now() - started,
      result: payload?.status ?? "响应正常",
    });
    return payload;
  } catch (error) {
    if (!loadHealthRequestGate.isCurrent(generation)) throw error;
    state.components = DEFAULT_COMPONENTS.map((item) =>
      item.id === "control-api" ? { ...item, status: "error", detail: error.message } : { ...item },
    );
    botRenderRoster?.();
    botRenderAgent(botState.agentId);
    state.diagnostics = upsertDiagnostic(state.diagnostics, {
      path: API.health,
      method: "GET",
      status: "error",
      latency: performance.now() - started,
      result: error.message,
    });
    throw error;
  } finally {
    if (loadHealthRequestGate.isCurrent(generation)) {
      renderOverview();
      renderDiagnostics();
      renderTeamPulse();
      refreshTeamData();
      missionControlDock?.refreshIdle?.();
    }
  }
}

// latest-wins 门闩：快速切换时间窗时，慢窗口的迟到响应不得覆盖新窗口状态
let usageLoadGeneration = 0;
async function loadUsageOverview({ force = false } = {}) {
  const generation = ++usageLoadGeneration;
  const stale = () => generation !== usageLoadGeneration;
  const days = Number(state.usageDays) || 7;
  if (!force && state.usageProxy?.days === days && (state.usageProxy.status === "ok" || state.usageProxy.status === "error")) {
    renderOverviewUsage();
    return state.usageProxy.status === "error"
      ? failedLoadResult(state.usageProxy.error)
      : successfulLoadResult(state.usageProxy.data);
  }
  state.usageProxy = { ...(state.usageProxy || {}), days, status: "loading" };
  renderOverviewUsage();
  try {
    let data;
    try {
      data = await request(`${API.ccswitchProxyUsageOverview}?days=${encodeURIComponent(days)}`);
    } catch (error) {
      if (error?.status !== 404 && error?.payload?.code !== "SOURCE_NOT_FOUND") throw error;
      data = { source: "ccswitch-proxy" };
    }
    if (!Array.isArray(data?.logs) || !Array.isArray(data?.providers) || !data?.summary) {
      const [summaryRes, trendsRes, modelsRes, providersRes, logsRes] = await Promise.allSettled([
        data?.summary ? Promise.resolve({ summary: data.summary }) : request(`${API.ccswitchProxy}/usage/summary?days=${encodeURIComponent(days)}`),
        Array.isArray(data?.trends) ? Promise.resolve({ trends: data.trends }) : request(`${API.ccswitchProxy}/usage/trends?days=${encodeURIComponent(days)}`),
        Array.isArray(data?.models) ? Promise.resolve({ items: data.models }) : request(`${API.ccswitchProxy}/usage/models?days=${encodeURIComponent(days)}`),
        Array.isArray(data?.providers) ? Promise.resolve({ items: data.providers }) : request(`${API.ccswitchProxy}/usage/providers?days=${encodeURIComponent(days)}`),
        Array.isArray(data?.logs) ? Promise.resolve({ items: data.logs }) : request(`${API.ccswitchProxy}/logs?limit=80`),
      ]);
      if (!data?.summary && summaryRes.status !== "fulfilled") throw summaryRes.reason || new Error("proxy usage summary unavailable");
      data = {
        source: data?.source || "ccswitch-proxy",
        summary: data?.summary ?? summaryRes.value?.summary ?? {},
        trends: Array.isArray(data?.trends) ? data.trends : (trendsRes.status === "fulfilled" ? (trendsRes.value?.trends ?? []) : []),
        models: Array.isArray(data?.models) ? data.models : (modelsRes.status === "fulfilled" ? (modelsRes.value?.items ?? []) : []),
        providers: Array.isArray(data?.providers) ? data.providers : (providersRes.status === "fulfilled" ? (providersRes.value?.items ?? []) : []),
        logs: Array.isArray(data?.logs) ? data.logs : (logsRes.status === "fulfilled" ? (logsRes.value?.items ?? []) : []),
      };
    }
    if (stale()) return successfulLoadResult(data);
    state.usageProxy = { days, status: "ok", data, error: null, loadedAt: Date.now() };
    return successfulLoadResult(data);
  } catch (error) {
    if (!stale()) state.usageProxy = { days, status: "error", data: null, error, loadedAt: Date.now() };
    return failedLoadResult(error);
  } finally {
    renderOverviewUsage();
  }
}

function syncUsageControls() {
  const root = elements["overview-usage"];
  if (!root) return;
  root.querySelectorAll("[data-usage-source]").forEach((button) => {
    const active = button.dataset.usageSource === state.usageSource;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  root.querySelectorAll("[data-usage-days]").forEach((button) => {
    const active = Number(button.dataset.usageDays) === Number(state.usageDays);
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", String(active));
  });
  root.querySelectorAll("[data-usage-chart-kind]").forEach((button) => {
    const active = button.dataset.usageChartKind === state.usageChartKind;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", String(active));
  });
  root.querySelectorAll("[data-usage-chart-metric]").forEach((button) => {
    const active = button.dataset.usageChartMetric === state.usageChartMetric;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", String(active));
  });
  root.querySelectorAll("[data-usage-ledger]").forEach((button) => {
    const active = button.dataset.usageLedger === state.usageLedger;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
}

function renderOverviewUsage() {
  if (state.view !== "overview") return;
  const root = elements["overview-usage"];
  if (!root) return;
  syncUsageControls();
  const days = Number(state.usageDays) || 7;
  let model;
  if (state.usageSource === "runs") {
    model = buildViewModel(summarizeRuns(state.runs, { days }), { source: "runs", days });
  } else if (state.usageProxy?.status === "error") {
    model = buildViewModel(null, { source: "proxy", days, error: state.usageProxy.error });
  } else if (state.usageProxy?.status === "loading" && !state.usageProxy?.data) {
    model = buildViewModel(null, { source: "proxy", days });
    model.emptyTitle = "正在读取代理用量";
    model.emptyDetail = "只显示代理真实记账，不会预填演示数字。";
  } else {
    model = buildViewModel(state.usageProxy?.data, { source: "proxy", days });
  }
  paintUsageDeck(root, model, {
    chartKind: state.usageChartKind,
    chartMetric: state.usageChartMetric,
    ledger: state.usageLedger,
    model: state.usageModel,
  });
}

async function loadSources({ preserveSelection = true } = {}) {
  const previousSelection = state.selectedSourceId;
  const payload = await request(API.sources);
  state.sources = unwrapList(payload, ["sources", "config_sources"]).map(normalizeSource);
  const selectedSourceExists = state.sources.some((item) => item.id === previousSelection);
  const preserveDirtyDraft = Boolean(previousSelection) && !selectedSourceExists && configIsDirty();
  if (preserveDirtyDraft) {
    appendDiagnostic(`配置源 ${previousSelection} 已不在索引中；保留未保存草稿与原选择`, "warning");
    toast("当前配置源已从索引移除；未保存草稿仍保留，请确认后再切换", "warning", 7000);
  } else if (!preserveSelection || !selectedSourceExists) {
    state.selectedSourceId = state.sources[0]?.id ?? null;
  }
  if (state.selectedSourceId !== previousSelection) {
    state.config = null;
    state.versions = [];
    state.configVersionPreview = null;
    state.pendingPlan = null;
    renderConfig();
  }
  renderSources();
  renderConfigTopology();
  renderOverview();
  return payload;
}

async function loadRuns() {
  const generation = loadRunsRequestGate.begin();
  const payload = await request(API.runs);
  if (!loadRunsRequestGate.isCurrent(generation)) return payload;
  const previousSelectedRunId = state.selectedRunId;
  const composerWasNewTask = Boolean(state.sessionPreview) || !previousSelectedRunId;
  // 先把响应到达前的 DOM 草稿落到旧语义。不能等 state.runs 替换后再做：
  // 被删除的 run 已无法由 selectedRun() 找回，但它的未发送续聊仍必须保住。
  stashComposerDraftForCurrentContext();
  state.runs = unwrapList(payload, ["runs"]).map(normalizeRun);
  botHydrateRunQueuesFromRuns();
  botReconcileRunQueues();
  let nextSelectedRunId = previousSelectedRunId;
  let nextSelectionClearedByUser = state.selectionClearedByUser;
  // 深度链接一次性消费：#run=<id> 指定的任务优先选中
  if (state.deepLinkRunId) {
    if (state.runs.some((run) => run.id === state.deepLinkRunId)) {
      nextSelectedRunId = state.deepLinkRunId;
      nextSelectionClearedByUser = false;
    }
    else {
      toast("深度链接指向的任务不存在（可能已被清除）", "warning");
      state.deepLinkRunId = null;
    }
  }
  if (nextSelectedRunId && !state.runs.some((run) => run.id === nextSelectedRunId)) {
    nextSelectedRunId = null;
    nextSelectionClearedByUser = false; // 选中失效非用户意图，允许下方自动接力
  }
  const draftContext = state.attachmentContexts.get(attachmentContextKey({ draftId: state.composerDraftId }));
  if (!nextSelectedRunId && !nextSelectionClearedByUser && composerWasNewTask && composerDraftHasActivity({
    text: elements["task-input"]?.value,
    context: draftContext,
  })) {
    // 首屏 runs 仍在加载时，LO 已开始输入或附图，语义已明确属于新任务草稿。
    // 后台自动选中旧 run 会把发送目标偷换成续聊，并让附件 chip 看似消失。
    nextSelectionClearedByUser = true;
  }
  // 自动选择只补「从未选过」的位：用户显式切新任务模式（selectionClearedByUser）时不得回盖——
  // 否则笔按钮/新任务后下一次 loadRuns 轮询把旧 run 重新刷回会话区（LO 2026-08-11）
  if (!nextSelectedRunId && !nextSelectionClearedByUser) {
    nextSelectedRunId = state.runs.find((run) => ACTIVE_RUN_STATES.has(run.status))?.id ?? state.runs[0]?.id ?? null;
  }
  const selectionChanged = nextSelectedRunId !== previousSelectedRunId;
  if (selectionChanged && previousSelectedRunId) {
    cancelSettlementRequest("workbench", previousSelectedRunId);
    if (state.runSettlementView?.runId === previousSelectedRunId) state.runSettlementView = null;
  }
  state.selectedRunId = nextSelectedRunId;
  state.selectionClearedByUser = nextSelectionClearedByUser;
  if (selectionChanged) {
    // 选中目标落定后再恢复；预览态仍归新任务分柜，不把历史预览内容带进 run。
    restoreComposerDraftForCurrentContext();
  }
  renderRuns();
  renderOverview();
  // 状态翻页必须连会话视图一起刷：loadRuns 是 run.completed/failed 等纯状态事件的唯一通道
  // （它们不在 conversationEvent 白名单）——不补这刀，停止键/composer 禁用态/恢复条停在旧快照
  renderSelectedRun();
  syncBotRunState();
  const run = selectedRun();
  missionControlDock?.selectRun(run?.id ?? null, run ? `${run.updatedAt ?? run.createdAt ?? ""}:${run.status}:${run.round ?? 0}` : null, runLocalEnvironmentId(run));
  syncRailToActiveRun();
  refreshTeamData();
  return payload;
}

let approvalsLoadGeneration = 0;
let approvalSnapshotEpoch = null;
let approvalSnapshotRevision = 0;

async function loadApprovals() {
  const generation = ++approvalsLoadGeneration;
  state.approvalsLoading = true;
  renderPermissionOverview();
  const [approvalResult, leaseResult] = await Promise.allSettled([
    request(API.approvals),
    request(API.leases),
  ]);
  const payload = approvalResult.status === "fulfilled" ? approvalResult.value : null;
  // approval.pending/resolved/expired 可能在短时间内连续触发多次刷新。
  // 旧 GET 晚到时不得把较新的 pending 快照覆盖回去，否则 Bot 卡会复活。
  if (generation !== approvalsLoadGeneration) return payload;
  if (approvalResult.status === "fulfilled") {
    const applied = applyApprovalSnapshot(payload, { source: "审批快照" });
    state.approvalSnapshotError = applied.invalid ? "审批快照版本无效" : null;
    if (applied.invalid) state.approvals = [];
  } else {
    // 读取失败时清掉旧 pending，避免把不再确认的新鲜度当成可执行授权。
    state.approvals = [];
    state.approvalSnapshotError = approvalResult.reason?.message || String(approvalResult.reason || "审批快照读取失败");
    appendDiagnostic(`审批快照读取失败：${approvalResult.reason?.message || approvalResult.reason || "unknown"}`, "warning");
  }
  if (leaseResult.status === "fulfilled") {
    state.leases = unwrapList(leaseResult.value, ["leases"]);
    state.leaseSnapshotError = null;
  }
  else {
    state.leases = [];
    state.leaseSnapshotError = leaseResult.reason?.message || String(leaseResult.reason || "租约快照读取失败");
    appendDiagnostic(`租约快照读取失败：${leaseResult.reason?.message || leaseResult.reason || "unknown"}`, "warning");
  }
  state.approvalsLoading = false;
  renderApprovals();
  renderPermissionOverview();
  renderSelectedRun(); // 内联审批卡挂在协作台会话流末尾，与安全诊断列表同一份数据同步刷新
  missionControlDock?.refresh();
  if (state.view === "bot" && botState.agentId) void botSyncConversation(botState.agentId);
  return payload;
}

async function loadInitial() {
  setApiState("pending");
  appendDiagnostic("开始加载控制面 bootstrap、health、配置索引与任务列表");
  let earlySuccess = false;
  const track = (job) =>
    job.then((value) => {
      if (!earlySuccess && !loadResultFailed(value)) {
        earlySuccess = true;
        setApiState("ok");
      }
      return value;
    });
  const sourcesJob = loadSources().then(async (payload) => {
    if (state.selectedSourceId && !state.config) {
      const detailResult = await loadSelectedConfig();
      if (loadResultFailed(detailResult)) return detailResult;
    }
    return payload;
  });
  const jobs = [track(loadBootstrap()), track(loadHealth()), track(sourcesJob), track(loadRuns()), track(loadApprovals()), track(loadAutomations()), track(loadTeams())];
  const settled = await Promise.allSettled(jobs);
  const successes = settled.filter((item) => item.status === "fulfilled" && !loadResultFailed(item.value)).length;
  if (successes > 0) {
    setApiState("ok");
    appendDiagnostic(`控制面初始化完成：${successes}/${settled.length} 个端点成功`);
  } else {
    setApiState("error", "所有初始化端点均不可用");
    appendDiagnostic("控制面初始化失败：所有端点均不可用", "error");
  }

  settled.forEach((item) => {
    if (item.status === "rejected") appendDiagnostic(item.reason?.message ?? item.reason, "warning");
    else if (loadResultFailed(item.value)) appendDiagnostic(item.value.error?.message ?? item.value.error, "warning");
  });
  renderAll();
}

function setConfigSurface(surface, { updateHash = true, focus = false, preserveMemberTarget = false, recordHistory = true } = {}) {
  const previous = recordHistory ? captureViewRoute() : null;
  const remoteTarget = Boolean(state.configHostId || state.configProjectId);
  let next = CONFIG_SURFACE_SET.has(surface) ? surface : (remoteTarget ? "providers" : "sources");
  const requested = next;
  if (!remoteTarget && next === "providers") next = "sources";
  if (remoteTarget && next === "hooks") {
    toast("远端钩子尚未接入，请切回本机后再编辑", "warning", 4000);
    next = "providers";
  }
  if (!preserveMemberTarget) clearMemberConfigTarget();
  state.configSurface = next;
  document.querySelectorAll("[data-config-surface-panel]").forEach((panel) => {
    const active = panel.dataset.configSurfacePanel === next;
    panel.hidden = !active;
    panel.classList.toggle("is-active", active);
  });
  document.querySelectorAll("[data-config-surface]").forEach((button) => {
    const active = button.dataset.configSurface === next;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
    button.tabIndex = active ? 0 : -1;
  });
  if (state.view === "config" && (updateHash || next !== requested)) {
    history.replaceState(null, "", configRouteHash(next, {
      memberId: state.configMemberFocusId,
      runtimeProfileId: state.configRuntimeFocusId,
    }));
  }
  renderConfigTopology();
  // 远程配置目标生效期间，程序化 surface 切换不得把本机三面图谱重新放出来
  if (state.configHostId) syncConfigHostView();
  if ((next === "providers" || next === "sources") && !state.providersData) void loadTeams().then(() => loadProviders());
  reconcileProviderLivePoll(); // 席位连接区进出即开停 live 轮询
  if (next === "local-runtime") {
    const panel = window.__forgeCcSwitchPanel;
    if (typeof panel?.refresh === "function" && !panel.state?.proxy && !panel.state?.domain) void panel.refresh();
  }
  if (next === "hooks") void window.__forgeHooksPanel?.refresh?.();
  if (next === "capabilities" && !state.capabilitiesData) void loadCapabilities();
  if (next === "capabilities" && state.capabilitiesData) renderCapabilities();
  syncWorkbenchRailShortcuts(state.view, next);
  syncSettingsRailActive(state.view, next);
  if (next === "sources") runtimeSeatManager?.setMode(state.runtimeWorkspaceMode, { focus: false });
  if (focus) {
    const heading = byId(`config-surface-${next}`)?.querySelector("h2");
    if (heading) {
      heading.setAttribute("tabindex", "-1");
      requestAnimationFrame(() => heading.focus({ preventScroll: true }));
    }
  }
  if (recordHistory) rememberRouteChange(previous);
}

function revealTeamStarmap() {
  memberLibrary?.setSurface("orchestration", { focus: false });
  requestAnimationFrame(() => {
    const root = byId("team-starmap-root");
    if (!root) return;
    root.classList.add("is-focus-pulse");
    root.scrollIntoView({ block: "start", behavior: "smooth" });
    window.setTimeout(() => root.classList.remove("is-focus-pulse"), 1400);
  });
}

function revealTeamRouting() {
  memberLibrary?.setSurface("orchestration", { focus: false });
  requestAnimationFrame(() => {
    const root = byId("team-router-workbench");
    if (!root) return;
    root.classList.add("is-focus-pulse");
    root.scrollIntoView({ block: "start", behavior: "smooth" });
    window.setTimeout(() => root.classList.remove("is-focus-pulse"), 1400);
    elements["router-prompt"]?.focus?.({ preventScroll: true });
  });
}


const BOT_GLOBAL_DIALOG_IDS = Object.freeze([
  "input-dialog",
  "automation-dialog",
  "session-dialog",
  "provider-dialog",
  "common-config-dialog",
  "provider-deeplink-dialog",
  "workbench-git-dialog",
  "workbench-browser-dialog",
  "action-dialog",
]);

function closeBotGlobalDialogs() {
  for (const id of BOT_GLOBAL_DIALOG_IDS) {
    const dialog = byId(id);
    if (!dialog?.open || typeof dialog.close !== "function") continue;
    const automationWasClean = id === "automation-dialog" && !automationFormDirty;
    const cancelEvent = new Event("cancel", { cancelable: true });
    dialog.dispatchEvent(cancelEvent);
    if (!dialog.open) continue;
    if (cancelEvent.defaultPrevented && !automationWasClean) return false;
    dialog.close("cancel");
  }
  if (document.activeElement?.closest?.("#view-bot")) document.activeElement.blur?.();
  return true;
}

function syncBotSurfaceChrome(view) {
  const bot = view === "bot";
  document.documentElement.classList.toggle("is-bot-surface", bot);
  document.body?.classList.toggle("is-bot-surface", bot);
  for (const id of ["common-config-dialog", "provider-deeplink-dialog"]) {
    const dialog = byId(id);
    dialog?.classList.toggle("action-dialog", bot);
    dialog?.querySelector(".dialog-header")?.classList.toggle("dialog-heading", bot);
  }
  const stage = document.querySelector(".atelier-stage");
  if (stage) {
    stage.hidden = false;
    stage.setAttribute("aria-hidden", "true");
    stage.removeAttribute("inert");
  }
  // Bot 回到 514cc 单界面控制台壳：保留静态纸面场，动态 canvas 在 Bot 中停用，
  // 避免聊天工作面为纯装饰持续占用合成与动画预算。
  const canvas = document.getElementById("atelier-canvas");
  if (canvas) canvas.hidden = bot;
  for (const selector of [".sidebar", ".mobile-nav"]) {
    document.querySelectorAll(selector).forEach((node) => {
      if (bot) {
        node.setAttribute("data-bot-hidden-chrome", "1");
        node.hidden = true;
        node.setAttribute("inert", "");
      } else if (node.getAttribute("data-bot-hidden-chrome") === "1") {
        node.removeAttribute("data-bot-hidden-chrome");
        node.hidden = false;
        node.removeAttribute("inert");
      }
    });
  }
  // 顶部控制栏与桌面状态栏属于恢复后的 514 Bot 产品壳，不能再被旧的
  // data-bot-hidden-chrome 状态留在可见树之外。
  for (const selector of [".topbar", ".global-statusbar"]) {
    document.querySelectorAll(selector).forEach((node) => {
      node.removeAttribute("data-bot-hidden-chrome");
      node.hidden = false;
      node.removeAttribute("inert");
    });
  }
}

let pendingBotWorkspaceRoute = null;
let botWorkspaceRouteGuardActive = false;

function guardDirtyBotWorkspaceRoute(view, options) {
  const panel = byId("bot-workspace-panel");
  if (state.view !== "bot"
    || view === "bot"
    || panel?.hidden !== false
    || botState.workspaceTab !== "seats"
    || !runtimeSeatManager?.isDirty()) return false;
  const requestedHash = options.updateHash === false && String(location.hash || "") !== "#bot"
    ? String(location.hash)
    : null;
  pendingBotWorkspaceRoute = {
    view,
    requestedHash,
    options: { ...options, updateHash: requestedHash ? false : true },
  };
  history.replaceState(null, "", "#bot");
  if (botWorkspaceRouteGuardActive) return true;
  botWorkspaceRouteGuardActive = true;
  void botRequestCloseWorkspace({ restoreFocus: false })
    .then((closed) => {
      const target = pendingBotWorkspaceRoute;
      pendingBotWorkspaceRoute = null;
      if (closed && target) {
        if (target.requestedHash) history.replaceState(null, "", target.requestedHash);
        setView(target.view, target.options);
      }
    })
    .catch((error) => {
      pendingBotWorkspaceRoute = null;
      toast(`运行席位草稿检查失败：${error.message}`, "error", 6000);
    })
    .finally(() => { botWorkspaceRouteGuardActive = false; });
  return true;
}

function setView(view, {
  updateHash = true,
  focus = true,
  configSurface = null,
  preserveMemberTarget = false,
  settingsFocus = undefined,
  capabilityWorkspace = undefined,
} = {}) {
  if (view === "bot" && botWorkspaceRouteGuardActive) pendingBotWorkspaceRoute = null;
  if (view === "memory") {
    view = "observability";
    settingsFocus = settingsFocus ?? "memory";
  }
  if (view === "capabilities") {
    view = "config";
    configSurface = "capabilities";
  }
  if (view === "terminal") {
    openBottomTerminal();
    return;
  }
  if (view === "hero") {
    setView("team", { updateHash: true, focus: false });
    revealTeamStarmap();
    return;
  }
  if (view === "router") {
    setView("team", { updateHash: true, focus: false });
    revealTeamRouting();
    return;
  }
  if (!FORGE_VIEW_TITLES[view]) return;
  if (guardDirtyBotWorkspaceRoute(view, {
    updateHash,
    focus,
    configSurface,
    preserveMemberTarget,
    settingsFocus,
    capabilityWorkspace,
  })) return;
  // Bot 的覆盖层属于该表面；离开 Bot 时必须收拢，避免返回 #bot 后
  // 隐藏视图上的 dialog 继续拦截点击或保留错误焦点。
  if (view !== "bot") {
    if (state.view === "bot") {
      if (!closeBotGlobalDialogs()) {
        history.replaceState(null, "", "#bot");
        return;
      }
      cancelSettlementRequests("bot");
    }
    botCloseWorkspace?.({ restoreFocus: false });
    botCloseGroupDialog?.();
    botCloseAgentSettings?.();
    botSetComputerView?.(false);
    botSetPanel?.(false);
    botCloseSettings?.();
  }
  if (state.view === "workbench" && view !== "workbench") cancelSettlementRequests("workbench");
  const previousRoute = captureViewRoute();
  if (view !== "config") clearMemberConfigTarget();
  if (settingsFocus !== undefined) state.settingsFocus = settingsFocus;
  else if (view !== "observability") state.settingsFocus = null;
  state.view = view;
  syncBotSurfaceChrome(view);
  const panelView = view === "automations" ? "workbench" : view;
  document.querySelectorAll("[data-view-panel]").forEach((panel) => {
    const active = panel.dataset.viewPanel === panelView;
    panel.hidden = !active;
    panel.classList.toggle("is-active", active);
  });
  revealWorkbenchAutomations(view === "automations");
  document.querySelectorAll("[data-view]").forEach((button) => {
    const active = button.dataset.view === view;
    button.classList.toggle("is-active", active);
    if (active) button.setAttribute("aria-current", "page");
    else button.removeAttribute("aria-current");
  });
  syncWorkbenchRailShortcuts(view, configSurface ?? state.configSurface);
  syncSettingsRailActive(view, configSurface ?? state.configSurface);
  if (view === "bot") initBotShell();
  elements["current-view-title"].textContent = forgeViewTitle(view, state.settingsFocus);
  if (elements["current-view-group"]) {
    elements["current-view-group"].textContent = forgeViewGroup(view, configSurface ?? state.configSurface, state.settingsFocus);
  }
  document.title = view === "bot" ? "514 Bot" : `${forgeViewTitle(view, state.settingsFocus)} · 514 Bot`;
  syncSettingsChrome(view);
  // 自举面板（channels/market/office）只在首载 boot 一次；切入视图时按需刷新，
  // 门闸授权/加载失败后切走再切回不再是死屏。
  if (view === "channels") {
    void import("./channels-panel.js").then((m) => m.refreshChannelsPanel?.());
  } else if (view === "market") {
    void import("./market-panel.js").then((m) => m.refreshMarketPanel?.());
  } else if (view === "office") {
    void import("./office-panel.js").then((m) => m.refreshOfficePanel?.());
  }
  if (view === "config") {
    setConfigSurface(configSurface ?? state.configSurface, {
      updateHash: false,
      focus: false,
      preserveMemberTarget,
      recordHistory: false,
    });
    if (capabilityWorkspace === "mcp" || capabilityWorkspace === "skills") {
      setCapabilityWorkspace(capabilityWorkspace, { focus: false, recordHistory: false });
    }
  }
  if (updateHash) {
    history.replaceState(null, "", view === "config"
      ? configRouteHash(state.configSurface, {
          memberId: state.configMemberFocusId,
          runtimeProfileId: state.configRuntimeFocusId,
        })
      : view === "automations" && String(location.hash || "").startsWith("#automations")
        ? location.hash
        : view === "observability" && state.settingsFocus === "memory"
          ? "#memory"
          : `#${view}`);
  }
  if (view === "observability" && state.settingsFocus === "memory") {
    requestAnimationFrame(() => byId("memory-browser-root")?.scrollIntoView({ block: "start", behavior: "smooth" }));
  }
  if (view === "appearance") {
    mountAppearancePreviews();
    syncAppearanceControls();
  }
  if (focus) {
    const heading = (view === "automations" ? byId("automations-workbench") : byId(`view-${view}`))?.querySelector("h1");
    if (heading) {
      heading.setAttribute("tabindex", "-1"); // h1 默认不可聚焦——切页焦点迁移需显式 tabindex（烛建议）
      heading.focus?.({ preventScroll: true });
    }
  }

  if (view === "security") {
    void loadApprovals();
    void loadRemoteGates();
    if (!state.runtimeSeatsData && !state.runtimeSeatsLoading) void runtimeSeatManager?.load();
    if (state.diagnostics.length === 0) void runDiagnostics();
  }
  if (view === "observability" && !state.obsLoaded) void loadObservability();
  if (view === "sessions" && !state.sessionsData) void loadSessions();
  // 统一配置图谱每次进入都回读供应商、能力和真源摘要；三个配置面共用同一份状态。
  if (view === "config") {
    void loadTeams().then(() => loadProviders());
    if (!state.capabilitiesData) void loadCapabilities();
    if (state.configSurface === "sources") void runtimeSeatManager?.load();
    void loadConfigHosts({ force: true }); // 配置目标台账每进刷新（远程主机视图里增删过也能跟上）
    if (state.configHostId) syncConfigHostView(); // 带着远程目标回到本视图时恢复面板显隐
  }
  if (view === "workbench" && !state.projectsData) void loadProjects();
  if (view === "workbench" && !state.teams.length) void loadTeams();
  if (view === "automations") {
    void Promise.all([
      loadAutomations().catch(() => null),
      state.projectsData ? Promise.resolve() : loadProjects().catch(() => null),
    ]).then(() => window.__forgeAutomationsPage?.refresh());
  }
  if (view === "team") {
    if (!state.teams.length) {
      void loadTeams().then((result) => {
        if (shouldHydrateTeamFormAfterLoad(result, {
          initialized: teamFormInitialized,
          dirty: teamFormDirty,
          busy: teamFormBusy,
        })) fillTeamForm(currentTeam());
      });
    } else if (!teamFormInitialized) {
      fillTeamForm(currentTeam());
    }
    refreshTeamData();
    void refreshCollabFlow();
  }
  reconcileProviderLivePoll(); // 离开配置页即停轮询；回到供应商面自动接上
  // 隐藏视图的数据只落 state；切到该视图时再消费，避免 SSE/轮询持续改写屏外 DOM。
  if (view === "overview") {
    renderOverview();
    void loadUsageOverview();
  }
  if (view === "workbench") {
    renderRuns();
    if (state.projectsData) renderProjects();
  }
  rememberRouteChange(previousRoute);
}

function renderConfigTopology() {
  const providers = state.providersData?.providers ?? [];
  const runtimeSeats = state.runtimeSeatsData?.seats ?? [];
  const adapterTemplates = state.adapterTemplatesData?.templates ?? [];
  const runtimeError = state.runtimeSeatsData?.error;
  const providerError = state.providersData?.error;
  const providerBlocked = state.providersData?.storeStatus?.state === "blocked";
  const skills = state.capabilitiesData?.skills;
  const mcp = state.capabilitiesData?.mcp;
  const capabilityStatus = skills?.configurationStatus ?? {};
  const mcpStatus = mcp?.configurationStatus ?? {};
  const localDriftCount = state.sources.filter((source) => ["drift", "warning", "stale"].includes(source.status)).length;
  const remoteTarget = Boolean(state.configHostId);
  const remoteEntry = remoteTarget ? state.configHostGraph.get(configRemoteTargetKey()) : null;
  const remoteGraph = remoteEntry?.status === "ok" ? remoteEntry.data ?? {} : null;
  const remoteProbe = remoteTarget ? state.configHostProbes.get(state.configHostId) : null;
  const remoteDraftCount = remoteTarget ? configRemoteDirtyDraftCount(configRemoteTargetKey()) : 0;
  const remoteRecovery = remoteTarget ? configRemoteRecoveryForTarget() : null;
  const remoteCount = (readyLabel) => remoteEntry?.status === "error" ? "读取失败" : remoteGraph ? readyLabel(remoteGraph) : "读取中";

  if (elements["config-topology-provider-count"]) {
    elements["config-topology-provider-count"].textContent = remoteTarget
      ? remoteCount((graph) => `${(graph.providers ?? []).filter((row) => row.exists).length} live · ${(graph.providers ?? []).length} 配置`)
      : providerError
      ? "读取失败"
      : state.providersData
        ? `${providers.filter((provider) => PROVIDER_APPS.some((app) => provider.apps?.[app])).length} 档案 · ${PROVIDER_APPS.length} 应用`
        : "读取中";
  }
  if (elements["config-topology-workbench-count"]) {
    const title = byId("config-topology-workbench")?.querySelector("strong");
    if (title) title.textContent = remoteTarget ? "远端运行时" : "本机运行时";
    elements["config-topology-workbench-count"].textContent = remoteTarget
      ? remoteCount(() => `${remoteProbe?.data?.clis?.filter((cli) => cli.installed).length ?? 0} CLI · 工作台`)
      : (() => {
          const proxy = window.__forgeCcSwitchPanel?.state?.proxy;
          if (!proxy && !window.__forgeCcSwitchPanel?.state?.domain) return "读取中";
          return proxy?.running ? "代理运行中" : "代理已停止";
        })();
  }
  if (elements["config-topology-capability-count"]) {
    elements["config-topology-capability-count"].textContent = remoteTarget
      ? remoteCount((graph) => `${(graph.capabilities ?? []).filter((cap) => cap.kind === "agent").length} Agent · ${(graph.capabilities ?? []).filter((cap) => cap.kind === "skill").length} Skill · ${(graph.mcp ?? []).length} MCP`)
      : state.capabilitiesError
      ? "扫描失败"
      : skills && mcp
        ? `${skills.agents?.length ?? 0} Agent · ${skills.items?.length ?? 0} Skill · ${mcp.servers?.length ?? 0} MCP`
        : "扫描中";
  }
  if (elements["config-topology-hooks-count"]) {
    elements["config-topology-hooks-count"].textContent = remoteTarget
      ? "仅本机"
      : (() => {
          const panel = window.__forgeHooksPanel?.state;
          if (!panel?.loaded) return "读取中";
          if (panel.loadError) return "读取失败";
          return `${panel.items?.length ?? 0} 条`;
        })();
  }
  const hooksNode = byId("config-topology-hooks");
  if (hooksNode) {
    hooksNode.disabled = remoteTarget;
    hooksNode.setAttribute("aria-disabled", String(remoteTarget));
    hooksNode.title = remoteTarget ? "远端钩子尚未接入，请切回本机后再编辑" : "";
  }
  if (elements["config-topology-source-count"]) {
    elements["config-topology-source-count"].textContent = remoteTarget
      ? remoteCount((graph) => `${remoteProbe?.data?.clis?.filter((cli) => cli.installed).length ?? 0} CLI · ${(graph.sources ?? []).filter((file) => file.exists).length} 真源`)
      : runtimeError
      ? "席位读取失败"
      : state.runtimeSeatsData
        ? `${runtimeSeats.length} 席位 · ${adapterTemplates.length} Adapter`
        : "读取中";
  }

  const providerNode = byId("config-topology-providers");
  if (providerNode) providerNode.hidden = !remoteTarget;
  const capabilityNode = byId("config-topology-capabilities");
  const sourceNode = byId("config-topology-sources");
  providerNode?.classList.toggle("is-error", remoteTarget ? remoteEntry?.status === "error" : Boolean(providerError));
  providerNode?.classList.toggle("is-warning", remoteTarget ? false : !providerError && providerBlocked);
  capabilityNode?.classList.toggle("is-error", remoteTarget ? remoteEntry?.status === "error" : Boolean(state.capabilitiesError || capabilityStatus.failClosed || mcpStatus.failClosed));
  sourceNode?.classList.toggle("is-warning", remoteTarget ? remoteDraftCount > 0 || Boolean(remoteRecovery) : localDriftCount > 0);
  sourceNode?.classList.toggle("is-error", remoteTarget ? remoteEntry?.status === "error" : Boolean(runtimeError));

  const workspaceStatus = elements["config-workspace-status"];
  if (!workspaceStatus) return;
  let tone = "neutral";
  let label = "正在汇总";
  if (remoteTarget) {
    if (remoteRecovery) { tone = "error"; label = "远程提交待核对，写入已阻断"; }
    else if (remoteDraftCount) { tone = "warning"; label = `${remoteDraftCount} 个远程真源草稿未保存`; }
    else if (remoteEntry?.status === "error") { tone = "error"; label = "远程图谱读取失败"; }
    else if (!remoteGraph) label = "正在读取远程图谱";
    else if (state.configSurface === "providers") {
      tone = "ok";
      label = `${remoteGraph.providers?.filter((row) => row.exists).length ?? 0} 个 live 配置`;
    } else if (state.configSurface === "local-runtime") {
      tone = remoteProbe?.status === "error" ? "warning" : "ok";
      label = remoteProbe?.status === "ok" ? "远端运行与配置工作台" : "正在探测远端运行时";
    } else if (state.configSurface === "capabilities") {
      tone = "ok";
      label = `${remoteGraph.capabilities?.length ?? 0} 项能力 · ${remoteGraph.mcp?.length ?? 0} MCP`;
    } else if (state.configSurface === "hooks") {
      tone = "neutral";
      label = "远端钩子尚未接入，当前只编本机";
    } else {
      tone = remoteProbe?.status === "error" ? "warning" : "ok";
      label = `${remoteProbe?.data?.clis?.filter((cli) => cli.installed).length ?? 0} 个 CLI · ${remoteGraph.sources?.filter((file) => file.exists).length ?? 0} 个真源`;
    }
  } else if (state.configSurface === "providers") {
    if (providerError) { tone = "error"; label = "供应商读取失败"; }
    else if (providerBlocked) { tone = "warning"; label = "供应商已冻结"; }
    else if (state.providersData) { tone = "ok"; label = `${providers.length} 个供应商档案`; }
  } else if (state.configSurface === "local-runtime") {
    const proxy = window.__forgeCcSwitchPanel?.state?.proxy;
    if (proxy?.running) { tone = "ok"; label = "本地代理运行中"; }
    else if (proxy) { tone = "neutral"; label = "本地代理已停止"; }
    else { label = "本机运行时"; }
  } else if (state.configSurface === "capabilities") {
    if (state.capabilitiesError) { tone = "error"; label = "能力配置读取失败"; }
    else if (capabilityStatus.failClosed && mcpStatus.failClosed) { tone = "error"; label = "Skill 与 MCP 配置已降级"; }
    else if (capabilityStatus.failClosed) { tone = "error"; label = "Skill 配置已降级"; }
    else if (mcpStatus.failClosed) { tone = "error"; label = "MCP 配置已降级"; }
    else if (skills && mcp) { tone = "ok"; label = `${skills.items?.length ?? 0} Skill · ${mcp.servers?.length ?? 0} MCP`; }
    else { label = "正在扫描能力"; }
  } else if (state.configSurface === "hooks") {
    const panel = window.__forgeHooksPanel?.state;
    if (panel?.loadError) { tone = "error"; label = "钩子读取失败"; }
    else if (panel?.loaded) { tone = "ok"; label = `${panel.items?.length ?? 0} 条本机钩子`; }
    else { label = "正在读取钩子"; }
  } else if (state.configSurface === "sources") {
    if (state.runtimeWorkspaceMode === "seats") {
      if (runtimeError) { tone = "error"; label = "运行席位读取失败"; }
      else if (runtimeSeatManager?.isDirty()) { tone = "warning"; label = "运行席位有未保存变更"; }
      else if (state.runtimeSeatsLoading || !state.runtimeSeatsData) { label = "正在读取运行席位"; }
      else if (state.runtimeSeatsData?.runtime?.activation === "restart-required") {
        tone = "warning";
        label = `${runtimeSeats.length} 个席位 · 待重载`;
      } else { tone = "ok"; label = `${runtimeSeats.length} 个运行席位`; }
    } else if (!state.sources.length) label = "正在读取真源";
    else if (state.config?.transactionBlocked) { tone = "error"; label = "事务写入已阻断"; }
    else if (configIsDirty()) { tone = "warning"; label = "有未保存变更"; }
    else if (localDriftCount) { tone = "warning"; label = `${localDriftCount} 项配置漂移`; }
    else { tone = "ok"; label = `${state.sources.length} 个真源已索引`; }
  }
  workspaceStatus.textContent = label;
  workspaceStatus.className = `status-label is-${tone}`;
}

/* ===== 配置目标切换（v41 波六：本机 / 远程主机 / 远程项目都是三面图谱） =====
 * 远程项目是 {hostId,path} 独立目标：主机级运行席位叠加项目级配置、能力和真源，
 * 同一主机上的多个项目缓存与展开状态严格隔离；本机三面板让位给统一远程面板。
 * 探测/装 CLI/同步本机配置走波一 remote-ops，图谱/真源走波五 remote-graph，与远程主机视图同源。 */

/**
 * 配置目标的加载问题分两类：
 *   - 501 / REMOTE_GATE_BLOCKED = 远程能力尚未授权，是「还没开」而不是「坏了」；
 *   - 其余 = 真故障，需要红字告警。
 * 两者以前都被拼成一条红色技术文案常驻在每个配置面（390px 下占三行），这里按语义分开。
 * 完整原文不丢——收进 detail，由 title 悬浮可见。
 */
function configTargetLoadIssue(reason, fallback) {
  const message = reason?.message ?? fallback;
  const code = reason?.payload?.code ?? reason?.payload?.error?.code ?? "";
  const blocked = reason?.status === 501 || code === "REMOTE_GATE_BLOCKED";
  return {
    kind: blocked ? "gated" : "error",
    message: blocked ? "远程能力尚未授权" : message,
    detail: message,
    nextStep: blocked ? "到远程门闸授权，而不是当故障重试" : null,
  };
}

async function loadConfigHosts({ force = false } = {}) {
  if (state.configHosts && state.configProjectsLoaded && !force) {
    renderConfigHostBar();
    return;
  }
  const [hostsResult, projectsResult] = await Promise.allSettled([
    request("/api/ssh/hosts"),
    request("/api/remote-projects"),
  ]);
  if (hostsResult.status === "fulfilled") {
    state.configHosts = hostsResult.value?.hosts ?? [];
    state.configHostsError = null;
  } else {
    // 门闸未开/台账故障：只留本机 chip 并如实提示，不拖垮配置图谱。
    // 501=能力尚未授权（不是故障），与真故障分开呈现——否则主界面每一面都常驻一条红色技术文案。
    state.configHosts = [];
    state.configHostsError = configTargetLoadIssue(hostsResult.reason, "SSH 主机台账不可用");
  }
  if (projectsResult.status === "fulfilled") {
    state.remoteProjects = projectsResult.value?.projects ?? [];
    state.remoteProjectsError = null;
  } else {
    state.remoteProjects = [];
    state.remoteProjectsError = configTargetLoadIssue(projectsResult.reason, "远程项目台账不可用");
  }
  state.configProjectsLoaded = true;
  const alive = new Set(state.configHosts.map((host) => host.id));
  for (const id of [...state.configHostProbes.keys()]) if (!alive.has(id)) state.configHostProbes.delete(id);
  const aliveProjects = new Set(state.remoteProjects.map((project) => project.id));
  if (state.configProjectId && !aliveProjects.has(state.configProjectId)) {
    state.configProjectId = null;
    state.configHostId = null;
    syncConfigHostView();
  } else if (!state.configProjectId && state.configHostId && !alive.has(state.configHostId)) {
    state.configHostId = null; // 台账里被删掉的主机自动回落本机
    syncConfigHostView();
  }
  renderConfigHostBar();
}

function renderConfigHostBar() {
  const bar = elements["config-host-bar"];
  if (!bar) return;
  const chip = ({ type, id = null, label, dotCls = null, status = "", title, disabled = false, draftCount = 0 }) => {
    const active = type === "local"
      ? !state.configHostId && !state.configProjectId
      : type === "project"
        ? state.configProjectId === id
        : !state.configProjectId && state.configHostId === id;
    const data = type === "project" ? `data-config-project="${escapeHtml(id)}"` : `data-config-host="${escapeHtml(id ?? "")}"`;
    const icon = type === "project" ? `<svg class="icon lucide" aria-hidden="true"><use href="#lucide-folder-git-2"></use></svg>` : "";
    const statusText = status ? `<span class="config-host-chip-status">${escapeHtml(status)}</span>` : "";
    const draft = draftCount ? `<span class="config-host-chip-draft" aria-label="${draftCount} 个未保存草稿">${draftCount}</span>` : "";
    return `<button type="button" class="config-host-chip is-${type}${active ? " is-active" : ""}" ${data} title="${escapeHtml(title)}" aria-pressed="${active}"${disabled ? " disabled" : ""}>
      ${icon}${dotCls == null ? "" : `<i class="remote-dot ${dotCls}"></i>`}<span class="config-host-chip-label">${escapeHtml(label)}</span>${statusText}${draft}</button>`;
  };
  const hosts = (state.configHosts ?? []).map((host) => {
    const disabled = host.enabled === false;
    const probe = state.configHostProbes.get(host.id);
    const dotCls = disabled ? "is-off" : probe?.status === "ok" ? "is-ok" : probe?.status === "error" ? "is-error" : probe?.status === "loading" ? "is-loading" : "";
    const status = disabled ? "停用" : probe?.status === "ok" ? "在线" : probe?.status === "error" ? "离线" : probe?.status === "loading" ? "探测中" : host.trusted ? "未探测" : "待信任";
    return chip({ type: "host", id: host.id, label: host.name ?? host.id, dotCls, status, disabled, draftCount: configRemoteDirtyDraftCount(`host:${host.id}`), title: `${host.user ?? ""}@${host.host ?? ""}:${host.port ?? ""} · ${status}` });
  }).join("");
  const projects = (state.remoteProjects ?? []).map((project) => {
    const disabled = project.hostMissing || project.host?.enabled === false;
    const probe = state.configHostProbes.get(project.hostId);
    const dotCls = disabled ? "is-off" : probe?.status === "ok" ? "is-ok" : probe?.status === "error" ? "is-error" : probe?.status === "loading" ? "is-loading" : "";
    const status = disabled ? project.hostMissing ? "主机缺失" : "停用" : probe?.status === "ok" ? "在线" : probe?.status === "error" ? "离线" : probe?.status === "loading" ? "探测中" : "未探测";
    const hostLabel = project.host?.name ?? project.hostId;
    return chip({ type: "project", id: project.id, label: project.name, dotCls, status, disabled, draftCount: configRemoteDirtyDraftCount(`project:${project.id}`), title: `${hostLabel} · ${project.path} · ${status}` });
  }).join("");
  bar.innerHTML = `<span class="config-host-bar-label">配置目标</span>`
    + chip({ type: "local", label: "本机", title: "本机配置图谱（供应商 / Agent·Skill·MCP / 运行席位与真源）" })
    + (hosts ? `<span class="config-target-divider">主机</span>${hosts}` : "")
    + (projects ? `<span class="config-target-divider">项目</span>${projects}` : "")
    + configTargetIssueMarkup(state.configHostsError, "主机")
    + configTargetIssueMarkup(state.remoteProjectsError, "项目")
    + `<button type="button" class="text-button config-host-manage" data-config-host-manage title="在远程主机视图添加 / 编辑 / 删除连接">管理主机…</button>`;
}

/** 目标栏提示：未授权走中性徽标 + 授权入口，真故障才用告警色；原文进 title，不铺在正文里。 */
function configTargetIssueMarkup(issue, scope) {
  if (!issue) return "";
  const gated = issue.kind === "gated";
  return `<span class="config-host-bar-hint${gated ? " is-gated" : " is-error"}" title="${escapeHtml(issue.detail ?? issue.message)}">
    <svg class="icon lucide" aria-hidden="true"><use href="#lucide-${gated ? "lock" : "triangle-alert"}"></use></svg>
    <span>${escapeHtml(scope)}${gated ? "" : "台账"}${escapeHtml(gated ? "：远程能力尚未授权" : `不可用：${issue.message}`)}</span>
    ${gated ? '<button type="button" class="text-button" data-config-open-gates>去授权</button>' : ""}
  </span>`;
}

function configRemoteDirtyDraftCount(targetKey = null) {
  let count = 0;
  for (const [key, draft] of state.configHostSourceDrafts) {
    if (!draft?.dirty || targetKey && !key.startsWith(`${targetKey}:`)) continue;
    count += 1;
  }
  return count;
}

function hasUnsavedConfigChanges() {
  return configIsDirty()
    || configRemoteDirtyDraftCount() > 0
    || teamFormDirty
    || Boolean(memberLibrary?.isDirty())
    || Boolean(runtimeSeatManager?.isDirty());
}

function selectConfigHost(id) {
  state.configProjectId = null;
  state.configHostId = id || null;
  if (state.configHostResult && state.configHostResult.targetKey !== configRemoteTargetKey()) state.configHostResult = null;
  state.configHostSourceOpen = null; // 真源展开态不跨主机保留
  syncConfigHostView(); // remote 分支内部 renderConfigRemotePanel
  renderConfigHostBar();
  if (state.configHostId) {
    if (!state.configHostProbes.has(state.configHostId)) void probeConfigHost(state.configHostId);
    void loadConfigHostGraph(state.configHostId);
  }
}

function selectConfigProject(id) {
  const project = (state.remoteProjects ?? []).find((entry) => entry.id === id);
  if (!project) return;
  state.configProjectId = project.id;
  state.configHostId = project.hostId;
  if (state.configHostResult && state.configHostResult.targetKey !== configRemoteTargetKey()) state.configHostResult = null;
  state.configHostSourceOpen = null;
  syncConfigHostView();
  renderConfigHostBar();
  if (!state.configHostProbes.has(project.hostId)) void probeConfigHost(project.hostId);
  void loadConfigHostGraph(project.hostId);
}

// 远程目标选中（v41 波五改写）：远程也是三面图谱——拓扑导航保留可切，本机三面板让位给远程面板，
// 远程面板按当前 surface 出「供应商与应用 / Agent·Skill·MCP / 运行席位与真源」的远端实况；回本机按 surface 恢复显隐。
function syncConfigHostView() {
  const remote = Boolean(state.configHostId || state.configProjectId);
  renderConfigTopology();
  const nav = byId("config-topology-nav");
  if (nav) nav.hidden = false; // 远程目标同样三面图谱，导航不再让位
  const panel = byId("config-surface-remote");
  if (remote) {
    document.querySelectorAll("[data-config-surface-panel]").forEach((item) => {
      item.hidden = true;
      item.classList.remove("is-active");
    });
    if (panel) panel.hidden = false;
    renderConfigRemotePanel(); // surface 切换经 setConfigSurface 尾钩走到这里，内容必须跟随重渲
  } else {
    if (panel) panel.hidden = true;
    setConfigSurface(state.configSurface, { updateHash: false });
  }
}

function configRemoteHost() {
  const projectHost = configRemoteProject()?.host;
  if (projectHost) return projectHost;
  return (state.configHosts ?? []).find((entry) => entry.id === state.configHostId) ?? null;
}

function configRemoteProject() {
  return (state.remoteProjects ?? []).find((entry) => entry.id === state.configProjectId) ?? null;
}

function configRemoteTargetKey() {
  if (state.configProjectId) return `project:${state.configProjectId}`;
  return state.configHostId ? `host:${state.configHostId}` : "local";
}

const CONFIG_REMOTE_RECOVERY_STORAGE_KEY = "514cc-config-remote-recovery-v1";

function configRemoteTargetSnapshotForKey(targetKey = configRemoteTargetKey()) {
  if (targetKey.startsWith("project:")) {
    const projectId = targetKey.slice("project:".length);
    const project = (state.remoteProjects ?? []).find((entry) => entry.id === projectId);
    return { key: targetKey, hostId: project?.hostId ?? null, projectId };
  }
  if (targetKey.startsWith("host:")) {
    return { key: targetKey, hostId: targetKey.slice("host:".length) || null, projectId: null };
  }
  return { key: targetKey, hostId: null, projectId: null };
}

function configRemoteRecoveryKey({ hostId, kind, transactionId } = {}) {
  if (!hostId || !kind || !transactionId) return null;
  return `${hostId}:${kind}:${transactionId}`;
}

function configRemoteRecoveryEntriesForTarget(target = configRemoteTargetSnapshotForKey()) {
  const snapshot = typeof target === "string" ? configRemoteTargetSnapshotForKey(target) : target;
  return [...(state.configRemoteRecovery?.entries?.() ?? [])]
    .filter(([, recovery]) => (
      (snapshot?.hostId && recovery?.hostId === snapshot.hostId)
      || (!snapshot?.hostId && recovery?.targetKey === snapshot?.key)
    ))
    .sort((left, right) => Number(left[1]?.recordedAt ?? 0) - Number(right[1]?.recordedAt ?? 0));
}

function configRemoteRecoveryEntryForTarget(target = configRemoteTargetSnapshotForKey()) {
  return configRemoteRecoveryEntriesForTarget(target)[0] ?? null;
}

function configRemoteRecoveryForTarget(target = configRemoteTargetSnapshotForKey()) {
  return configRemoteRecoveryEntryForTarget(target)?.[1] ?? null;
}

function notifyConfigRemoteRecoveryChanged() {
  if (typeof window === "undefined" || typeof window.dispatchEvent !== "function" || typeof CustomEvent !== "function") return;
  const hostIds = [...new Set([...(state.configRemoteRecovery?.values?.() ?? [])].map((entry) => entry?.hostId).filter(Boolean))];
  window.dispatchEvent(new CustomEvent("forge:config-remote-recovery-changed", { detail: { hostIds } }));
}

function clearConfigRemoteRecovery(kind, transactionId, hostId = null) {
  let changed = false;
  for (const [key, recovery] of state.configRemoteRecovery?.entries?.() ?? []) {
    if (recovery?.kind === kind && recovery?.transactionId === transactionId && (!hostId || recovery?.hostId === hostId)) {
      state.configRemoteRecovery.delete(key);
      changed = true;
    }
  }
  if (changed) {
    persistConfigRemoteRecoveries();
    notifyConfigRemoteRecoveryChanged();
  }
  return changed;
}

function persistConfigRemoteRecoveries() {
  try {
    const records = [...(state.configRemoteRecovery?.values?.() ?? [])].map((recovery) => ({
      kind: recovery.kind ?? null,
      transactionId: recovery.transactionId ?? null,
      targetKey: recovery.targetKey ?? null,
      hostId: recovery.hostId ?? null,
      projectId: recovery.projectId ?? null,
      scope: recovery.scope ?? null,
      appliedCount: recovery.appliedCount ?? recovery.applied?.length ?? 0,
      uncertainCount: recovery.uncertainCount ?? recovery.uncertain?.length ?? 0,
      causeCode: recovery.causeCode ?? null,
      serverPersisted: recovery.serverPersisted === true,
      message: recovery.message ?? "远端提交状态需要核对",
      recordedAt: recovery.recordedAt ?? Date.now(),
    }));
    localStorage.setItem(CONFIG_REMOTE_RECOVERY_STORAGE_KEY, JSON.stringify({ schema: 1, records }));
    return true;
  } catch (error) {
    console.warn("remote recovery evidence could not be persisted", error);
    return false;
  }
}

function restoreConfigRemoteRecoveries() {
  try {
    const saved = JSON.parse(localStorage.getItem(CONFIG_REMOTE_RECOVERY_STORAGE_KEY) ?? "null");
    if (saved?.schema !== 1 || !Array.isArray(saved.records)) return;
    for (const record of saved.records) {
      if (!record || !["provider", "graph", "sync"].includes(record.kind)) continue;
      if (typeof record.transactionId !== "string" || !record.transactionId) continue;
      if (typeof record.targetKey !== "string" || !/^(host|project):[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(record.targetKey)) continue;
      if (typeof record.hostId !== "string" || !record.hostId) continue;
      const recovery = {
        ...record,
        applied: [],
        uncertain: [],
        backups: [],
        locks: [],
        rollbackErrors: [],
      };
      const recoveryKey = configRemoteRecoveryKey(recovery);
      if (recoveryKey) state.configRemoteRecovery.set(recoveryKey, recovery);
    }
    notifyConfigRemoteRecoveryChanged();
  } catch (error) {
    console.warn("remote recovery evidence could not be restored", error);
  }
}

async function loadConfigRemoteRecoveries() {
  try {
    const result = await request("/api/ssh/hosts/recoveries");
    const serverKeys = new Set();
    for (const record of result?.recoveries ?? []) {
      if (!record || !["provider", "graph", "sync"].includes(record.kind)) continue;
      const recoveryKey = configRemoteRecoveryKey(record);
      if (!recoveryKey) continue;
      serverKeys.add(recoveryKey);
      const previous = state.configRemoteRecovery.get(recoveryKey) ?? {};
      state.configRemoteRecovery.set(recoveryKey, {
        ...previous,
        ...record,
        applied: Array.isArray(previous.applied) ? previous.applied : [],
        uncertain: Array.isArray(previous.uncertain) ? previous.uncertain : [],
        backups: Array.isArray(previous.backups) ? previous.backups : [],
        locks: Array.isArray(previous.locks) ? previous.locks : [],
        rollbackErrors: Array.isArray(previous.rollbackErrors) ? previous.rollbackErrors : [],
        recordedAt: Number.isFinite(Number(record.recordedAt)) ? Number(record.recordedAt) : Date.parse(record.recordedAt) || Date.now(),
        serverPersisted: true,
      });
    }
    for (const [recoveryKey, recovery] of state.configRemoteRecovery) {
      if (recovery?.serverPersisted === true && !serverKeys.has(recoveryKey)) state.configRemoteRecovery.delete(recoveryKey);
    }
    state.configRemoteRecoveryLoaded = true;
    state.configRemoteRecoveryLoadError = null;
    persistConfigRemoteRecoveries();
    notifyConfigRemoteRecoveryChanged();
  } catch (error) {
    state.configRemoteRecoveryLoaded = false;
    state.configRemoteRecoveryLoadError = error.message || "服务端恢复账本不可读";
    notifyConfigRemoteRecoveryChanged();
    console.warn("remote recovery ledger could not be loaded", error);
  }
}

function configRemoteGraphEndpoint({ sourceFile = null, backupName = null, target = configRemoteProviderTargetSnapshot() } = {}) {
  const base = target.projectId
    ? `/api/remote-projects/${encodeURIComponent(target.projectId)}/graph`
    : `/api/ssh/hosts/${encodeURIComponent(target.hostId)}/graph`;
  if (backupName != null) {
    return `${base}/backup?file=${encodeURIComponent(sourceFile ?? "")}&name=${encodeURIComponent(backupName)}`;
  }
  return sourceFile == null ? base : `${base}/source?file=${encodeURIComponent(sourceFile)}`;
}

// 面板内联结果区（安装/同步回报落这里，不哑弹）；波五：结果进 state，面板重渲后回填不被吞
function configRemoteResult(html, targetKey = configRemoteTargetKey()) {
  state.configHostResult = state.configHostId ? { targetKey, html } : null;
  if (targetKey !== configRemoteTargetKey()) return;
  renderConfigRemotePanel();
}

function renderConfigRemotePanel() {
  const panel = byId("config-surface-remote");
  if (!panel || !state.configHostId) return;
  const host = configRemoteHost();
  const project = configRemoteProject();
  if (!host) {
    renderPlaceholder(panel, emptyState({
      tone: "error",
      title: "该主机已不在 SSH 台账",
      desc: "它可能已被移除或改名。回到远程主机视图重新选择一台，台账里的会话与同步目标不受影响。",
      action: { label: "选择其他主机", view: "hosts", icon: "server" },
    }));
    return;
  }
  const targetKey = configRemoteTargetKey();
  const resultHtml = state.configHostResult?.targetKey === targetKey ? state.configHostResult.html : "";
  const recoveryHtml = configRemoteRecoveryMarkup(targetKey);
  const eyebrow = project ? "Remote Project" : "Remote Host";
  const title = project?.name ?? host.name ?? host.id;
  const location = project
    ? `${host.name ?? host.id} · ${project.path}`
    : `${host.user ?? ""}@${host.host ?? ""}:${host.port ?? ""}`;
  panel.innerHTML = `
    <div class="config-remote-result" aria-live="polite">${recoveryHtml}${resultHtml}</div>
    ${configRemoteSurfaceBody(host, { project, targetKey, eyebrow, title, location })}`;
}

function configRemoteRecoveryMarkup(targetKey) {
  const loadFailure = state.configRemoteRecoveryLoadError
    ? `<section class="config-recovery-banner" role="alert"><div><strong>恢复账本不可用，远端写入已保护性阻断</strong><span>${escapeHtml(state.configRemoteRecoveryLoadError)}</span></div><button class="button secondary" type="button" data-config-recovery-reload><svg aria-hidden="true" class="icon lucide"><use href="#lucide-refresh-cw"></use></svg>重试读取</button></section>`
    : "";
  return loadFailure + configRemoteRecoveryEntriesForTarget(targetKey).map(([recoveryKey, recovery]) => {
    const uncertain = Array.isArray(recovery.uncertain) ? recovery.uncertain : [];
    const applied = Array.isArray(recovery.applied) ? recovery.applied : [];
    const appliedCount = recovery.appliedCount ?? applied.length;
    const uncertainCount = recovery.uncertainCount ?? uncertain.length;
    const canReconcile = ["provider", "graph", "sync"].includes(recovery.kind) && Boolean(recovery.transactionId);
    const busy = state.configRemoteBusy.has(`reconcile:${recoveryKey}`);
    return `<section class="config-recovery-banner" role="alert" data-config-recovery-key="${escapeHtml(recoveryKey)}">
      <div><strong>远端提交状态不确定，写入已阻断</strong><span>${escapeHtml(recovery.message ?? "远端命令超时或回滚未完成")}</span>${recovery.persistenceError ? `<span class="status-label is-error">${escapeHtml(recovery.persistenceError)}</span>` : ""}</div>
      <dl><div><dt>类型</dt><dd>${escapeHtml(recovery.kind ?? "未知")}</dd></div><div><dt>事务</dt><dd class="mono">${escapeHtml(recovery.transactionId ?? "未返回")}</dd></div><div><dt>已提交</dt><dd>${appliedCount}</dd></div><div><dt>待核对</dt><dd>${uncertainCount}</dd></div></dl>
      <button class="button secondary" type="button" data-config-recovery-reconcile="${escapeHtml(recoveryKey)}"${canReconcile && !busy ? "" : " disabled"} title="${canReconcile ? "按远端锁元数据和文件摘要核对事务" : "该旧事务缺少可自动核对的种类或事务标识"}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-scan-search"></use></svg>${busy ? "正在核对" : canReconcile ? "核对远端状态" : "需要人工核对"}</button>
    </section>`;
  }).join("");
}

function configRemoteRecoveryEvidence(value, fallbackMessage = "", fallbackKind = null) {
  const input = value?.payload ?? value ?? {};
  const envelope = input?.error && typeof input.error === "object" ? input.error : {};
  const nested = envelope?.recovery && typeof envelope.recovery === "object"
    ? envelope.recovery
    : input?.recovery && typeof input.recovery === "object"
      ? input.recovery
      : {};
  const pick = (field) => nested[field] ?? envelope[field] ?? input[field] ?? value?.[field];
  const required = pick("recoveryRequired") === true
    || pick("status") === "recovery_required"
    || Object.keys(nested).length > 0;
  if (!required) return null;
  const list = (field) => Array.isArray(pick(field)) ? pick(field) : [];
  return {
    kind: pick("kind") ?? fallbackKind,
    transactionId: pick("transactionId") ?? null,
    applied: list("applied"),
    uncertain: list("uncertain"),
    backups: list("backups"),
    locks: list("locks"),
    rollbackErrors: list("rollbackErrors"),
    causeCode: pick("causeCode") ?? null,
    serverPersisted: pick("recoveryRegistryPersisted") === true,
    message: String(fallbackMessage || pick("message") || "远端提交状态需要核对"),
  };
}

function configRemotePendingRecoveryEvidence(value, fallbackMessage = "") {
  const input = value?.payload ?? value ?? {};
  const envelope = input?.error && typeof input.error === "object" ? input.error : {};
  const pending = Array.isArray(envelope.pending)
    ? envelope.pending
    : Array.isArray(input.pending)
      ? input.pending
      : Array.isArray(value?.pending)
        ? value.pending
        : [];
  return pending.flatMap((item) => {
    if (!item || !["provider", "graph", "sync"].includes(item.kind)) return [];
    if (typeof item.transactionId !== "string" || !item.transactionId) return [];
    const targetKey = typeof item.targetKey === "string" && /^(host|project):[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(item.targetKey)
      ? item.targetKey
      : null;
    return [{
      kind: item.kind,
      transactionId: item.transactionId,
      targetKey,
      applied: [],
      uncertain: [],
      backups: [],
      locks: [],
      rollbackErrors: [],
      appliedCount: Number.isFinite(Number(item.appliedCount)) ? Number(item.appliedCount) : 0,
      uncertainCount: Number.isFinite(Number(item.uncertainCount)) ? Number(item.uncertainCount) : 0,
      causeCode: item.causeCode ?? null,
      serverPersisted: true,
      message: String(fallbackMessage || envelope.message || input.message || "另一窗口已登记未核对的远端事务"),
    }];
  });
}

function rememberConfigRemoteRecovery(targetOrKey, value, fallbackMessage = "", fallbackKind = null) {
  const evidence = configRemoteRecoveryEvidence(value, fallbackMessage, fallbackKind);
  const pendingEvidence = configRemotePendingRecoveryEvidence(value, fallbackMessage);
  const evidenceItems = evidence ? [evidence, ...pendingEvidence] : pendingEvidence;
  if (!evidenceItems.length) return null;
  const inputTarget = typeof targetOrKey === "string"
    ? configRemoteTargetSnapshotForKey(targetOrKey)
    : targetOrKey;
  if (!inputTarget?.hostId || !inputTarget?.key) return null;
  const remembered = [];
  for (const item of evidenceItems) {
    const hostScoped = item.kind === "sync";
    const itemTargetKey = hostScoped ? `host:${inputTarget.hostId}` : item.targetKey ?? inputTarget.key;
    const itemProjectId = !hostScoped && itemTargetKey.startsWith("project:")
      ? itemTargetKey.slice("project:".length)
      : !hostScoped ? inputTarget.projectId ?? null : null;
    const recoveryKey = configRemoteRecoveryKey({ hostId: inputTarget.hostId, ...item });
    if (!recoveryKey) continue;
    const previous = state.configRemoteRecovery?.get(recoveryKey) ?? {};
    const recovery = {
      ...previous,
      ...item,
      targetKey: itemTargetKey,
      hostId: inputTarget.hostId,
      projectId: itemProjectId,
      scope: hostScoped || !itemProjectId ? "host" : "project",
      applied: item.applied.length ? item.applied : previous.applied ?? [],
      uncertain: item.uncertain.length ? item.uncertain : previous.uncertain ?? [],
      backups: item.backups.length ? item.backups : previous.backups ?? [],
      locks: item.locks.length ? item.locks : previous.locks ?? [],
      rollbackErrors: item.rollbackErrors.length ? item.rollbackErrors : previous.rollbackErrors ?? [],
      appliedCount: item.appliedCount ?? item.applied.length ?? previous.appliedCount ?? 0,
      uncertainCount: item.uncertainCount ?? item.uncertain.length ?? previous.uncertainCount ?? 0,
      recordedAt: previous.recordedAt ?? Date.now(),
    };
    state.configRemoteRecovery?.set(recoveryKey, recovery);
    remembered.push(recovery);
  }
  if (!remembered.length) return null;
  if (!persistConfigRemoteRecoveries()) {
    for (const recovery of remembered) recovery.persistenceError = "浏览器恢复缓存写入失败；当前会话继续阻断写入";
    toast("恢复证据未能写入浏览器缓存；本次会话已保持阻断，请勿关闭应用", "error", 9000);
  }
  notifyConfigRemoteRecoveryChanged();
  if (pendingEvidence.length && typeof loadConfigRemoteRecoveries === "function") {
    void loadConfigRemoteRecoveries().finally(() => {
      if (state.configHostId === inputTarget.hostId) renderConfigRemotePanel();
    });
  }
  return remembered[0];
}

function configRemoteWriteBlocked(target, { notify = true } = {}) {
  const ledgerUnavailable = state.configRemoteRecoveryLoaded !== true || Boolean(state.configRemoteRecoveryLoadError);
  if (!ledgerUnavailable && !configRemoteRecoveryForTarget(target)) return false;
  if (notify) toast(ledgerUnavailable ? "恢复账本尚未就绪或不可用，已保护性阻止远端写入" : "当前目标存在未和解的远端提交，已阻止再次写入", "error", 7000);
  return true;
}

if (typeof window !== "undefined") {
  window.__514ccConfigRemoteRecovery = Object.freeze({
    isReady: () => state.configRemoteRecoveryLoaded === true && !state.configRemoteRecoveryLoadError,
    isHostBlocked: (hostId) => configRemoteWriteBlocked({ key: `host:${hostId}`, hostId, projectId: null }, { notify: false }),
    entriesForHost: (hostId) => configRemoteRecoveryEntriesForTarget({ key: `host:${hostId}`, hostId, projectId: null }).map(([key, value]) => ({ key, ...value })),
    remember: (hostId, value, kind = "sync") => {
      const recovery = rememberConfigRemoteRecovery({ key: `host:${hostId}`, hostId, projectId: null }, value, value?.message, kind);
      if (recovery && state.configHostId === hostId) renderConfigRemotePanel();
      return recovery;
    },
    reconcile: (recoveryKey) => reconcileConfigRemoteRecovery(recoveryKey),
    reload: () => loadConfigRemoteRecoveries(),
  });
}

/* ===== 远程三面图谱（v41 波五）：三个 surface body 全部来自 /api/ssh/hosts/:id/graph 实况 ===== */

const CONFIG_REMOTE_CAP_GROUPS = Object.freeze([
  { kind: "agent", label: "Agent", icon: "bot" },
  { kind: "skill", label: "Skill", icon: "puzzle" },
  { kind: "command", label: "Command", icon: "terminal" },
  { kind: "prompt", label: "Prompt", icon: "file-text" },
]);

function remoteCliLabel(cli) {
  return PROVIDER_APP_META.find((meta) => meta.app === cli)?.label ?? cli;
}

function formatConfigBytes(bytes) {
  const n = Number(bytes) || 0;
  if (n >= 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  if (n >= 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${n} B`;
}

function formatRemoteMetricBytes(bytes, { rate = false } = {}) {
  const value = configRemoteMetricNumber(bytes);
  if (value == null || value < 0) return "不可用";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let scaled = value;
  let index = 0;
  while (scaled >= 1024 && index < units.length - 1) {
    scaled /= 1024;
    index += 1;
  }
  const digits = scaled >= 100 || index === 0 ? 0 : scaled >= 10 ? 1 : 2;
  return `${scaled.toFixed(digits)} ${units[index]}${rate ? "/s" : ""}`;
}

function configRemoteMetricNumber(value) {
  if (value == null || value === "" || typeof value === "boolean") return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function formatRemoteUptime(seconds) {
  const value = configRemoteMetricNumber(seconds);
  if (value == null || value < 0) return "不可用";
  const days = Math.floor(value / 86400);
  const hours = Math.floor((value % 86400) / 3600);
  const minutes = Math.floor((value % 3600) / 60);
  return [days ? `${days}天` : "", hours ? `${hours}小时` : "", !days && minutes ? `${minutes}分钟` : ""].filter(Boolean).join(" ") || "不足 1 分钟";
}

function configRemoteMetricHistory(hostId) {
  return state.configRemoteMetricHistory.get(hostId) ?? [];
}

function configRemoteSparkline(hostId, key, label) {
  const values = configRemoteMetricHistory(hostId)
    .map((sample) => configRemoteMetricNumber(sample[key]))
    .filter((value) => value != null);
  if (values.length < 2) return `<span class="remote-sparkline-empty">刷新后生成真实趋势</span>`;
  const max = Math.max(100, ...values);
  const width = 160;
  const height = 34;
  const points = values.map((value, index) => {
    const x = values.length === 1 ? 0 : (index / (values.length - 1)) * width;
    const y = height - Math.max(1, Math.min(height - 1, (value / max) * height));
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(" ");
  return `<svg class="remote-sparkline" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHtml(label)}最近 ${values.length} 次真实探针趋势"><polyline points="${points}"></polyline></svg>`;
}

function configRemoteHealthLevel(metrics) {
  const cpu = configRemoteMetricNumber(metrics?.cpu?.usagePercent);
  const memory = configRemoteMetricNumber(metrics?.memory?.usagePercent);
  const disk = configRemoteMetricNumber(metrics?.disk?.usagePercent);
  const cores = configRemoteMetricNumber(metrics?.cpu?.cores);
  const load = configRemoteMetricNumber(metrics?.load?.one);
  const pressure = [cpu, memory, disk, load != null && cores != null && cores > 0 ? (load / cores) * 100 : null].filter((value) => value != null);
  if (!pressure.length) return { level: "unknown", label: "数据不足", value: null };
  const value = Math.max(...pressure);
  if (value >= 90) return { level: "critical", label: "高负载", value };
  if (value >= 75) return { level: "warning", label: "需关注", value };
  return { level: "healthy", label: "健康", value };
}

function configRemotePercentCard(hostId, { label, icon, value, detail, historyKey, tone = "default" }) {
  const numeric = configRemoteMetricNumber(value);
  const available = numeric != null;
  return `<article class="remote-health-card is-${tone}">
    <div class="remote-health-card-head"><span><svg aria-hidden="true" class="icon lucide"><use href="#lucide-${icon}"></use></svg>${escapeHtml(label)}</span><strong>${available ? `${numeric.toFixed(1)}%` : "不可用"}</strong></div>
    <progress class="remote-health-meter" max="100" value="${available ? Math.max(0, Math.min(100, numeric)) : 0}" aria-hidden="true"></progress>
    <div class="remote-health-card-foot"><span>${escapeHtml(detail)}</span>${historyKey ? configRemoteSparkline(hostId, historyKey, label) : ""}</div>
  </article>`;
}

function configRemoteHealthDashboard(host, graph) {
  const probe = state.configHostProbes.get(host.id);
  if (!probe || probe.status === "loading") {
    return `<section class="remote-health-dashboard is-loading" aria-label="远程主机状态">${skeleton({ variant: "card", rows: 3, label: "正在读取主机 CPU、内存、磁盘、负载与网络状态" })}</section>`;
  }
  if (probe.status === "error") {
    return `<section class="remote-health-dashboard is-error" aria-label="远程主机状态"><div><strong>主机状态探测失败</strong><span>${escapeHtml(probe.error)}</span></div><button class="button secondary" type="button" data-config-host-probe="${escapeHtml(host.id)}">重试</button></section>`;
  }
  const data = probe.data ?? {};
  const metrics = data.metrics ?? {};
  const health = configRemoteHealthLevel(metrics);
  const history = configRemoteMetricHistory(host.id);
  const latest = history.at(-1);
  const previous = history.at(-2);
  const elapsed = latest && previous ? Math.max(0.001, (latest.at - previous.at) / 1000) : null;
  const rxRate = elapsed && latest.rxBytes != null && previous.rxBytes != null && latest.rxBytes >= previous.rxBytes ? (latest.rxBytes - previous.rxBytes) / elapsed : null;
  const txRate = elapsed && latest.txBytes != null && previous.txBytes != null && latest.txBytes >= previous.txBytes ? (latest.txBytes - previous.txBytes) / elapsed : null;
  const memory = metrics.memory ?? {};
  const disk = metrics.disk ?? {};
  const installed = (data.clis ?? []).filter((cli) => cli.installed).length;
  const ringValue = Number.isFinite(health.value) ? Math.max(0, Math.min(100, health.value)) : 0;
  return `<section class="remote-health-dashboard" aria-labelledby="remote-health-title">
    <div class="remote-health-heading">
      <div><p class="eyebrow">HOST HEALTH</p><h3 id="remote-health-title"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-gauge"></use></svg>服务器状态</h3><p>${escapeHtml(data.hostname ?? host.name ?? host.id)} · ${escapeHtml(data.os ?? "系统未知")} · ${history.length} 次真实采样</p></div>
      <span class="status-label ${health.level === "healthy" ? "is-ok" : health.level === "critical" ? "is-error" : health.level === "warning" ? "is-warning" : "is-neutral"}">${health.label}</span>
    </div>
    <div class="remote-health-overview">
      <div class="remote-health-gauge is-${health.level}" role="img" aria-label="${health.label}${Number.isFinite(health.value) ? `，最高资源压力 ${health.value.toFixed(1)}%` : "，没有可用指标"}"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="remote-health-gauge-track" cx="60" cy="60" r="50" pathLength="100"></circle><circle class="remote-health-gauge-value" cx="60" cy="60" r="50" pathLength="100" stroke-dasharray="${ringValue.toFixed(1)} ${(100 - ringValue).toFixed(1)}" transform="rotate(-90 60 60)"></circle></svg><div><strong>${Number.isFinite(health.value) ? `${Math.round(health.value)}%` : "--"}</strong><span>最高压力</span></div></div>
      <div class="remote-health-primary">
        ${configRemotePercentCard(host.id, { label: "CPU", icon: "cpu", value: metrics.cpu?.usagePercent, detail: metrics.cpu?.cores ? `${metrics.cpu.cores} 核` : "核心数不可用", historyKey: "cpu" })}
        ${configRemotePercentCard(host.id, { label: "内存", icon: "memory-stick", value: memory.usagePercent, detail: configRemoteMetricNumber(memory.usedBytes) != null ? `${formatRemoteMetricBytes(memory.usedBytes)} / ${formatRemoteMetricBytes(memory.totalBytes)}` : data.memory ?? "不可用", historyKey: "memory" })}
        ${configRemotePercentCard(host.id, { label: "根磁盘", icon: "hard-drive", value: disk.usagePercent, detail: configRemoteMetricNumber(disk.usedBytes) != null ? `${formatRemoteMetricBytes(disk.usedBytes)} / ${formatRemoteMetricBytes(disk.totalBytes)}` : data.disk ?? "不可用", historyKey: "disk", tone: (configRemoteMetricNumber(disk.usagePercent) ?? 0) >= 90 ? "danger" : "default" })}
      </div>
    </div>
    <div class="remote-health-secondary">
      <div><span>系统负载</span><strong>${[metrics.load?.one, metrics.load?.five, metrics.load?.fifteen].some((value) => configRemoteMetricNumber(value) != null) ? [metrics.load?.one, metrics.load?.five, metrics.load?.fifteen].map((value) => configRemoteMetricNumber(value)?.toFixed(2) ?? "--").join(" / ") : "不可用"}</strong><small>1 / 5 / 15 分钟</small></div>
      <div><span>在线时长</span><strong>${formatRemoteUptime(metrics.uptimeSeconds)}</strong><small>${metrics.processes == null ? "进程数不可用" : `${metrics.processes} 个进程`}</small></div>
      <div><span>网络吞吐</span><strong>${rxRate == null ? "等待第二次采样" : `↓ ${formatRemoteMetricBytes(rxRate, { rate: true })}`}</strong><small>${txRate == null ? `累计 ↓ ${formatRemoteMetricBytes(metrics.network?.rxBytes)} · ↑ ${formatRemoteMetricBytes(metrics.network?.txBytes)}` : `↑ ${formatRemoteMetricBytes(txRate, { rate: true })}`}</small></div>
      <div><span>运行配置</span><strong>${installed}/${data.clis?.length ?? 0} CLI</strong><small>${(graph.providers ?? []).filter((row) => row.exists).length} live 配置 · ${(graph.sources ?? []).filter((row) => row.exists).length} 真源</small></div>
    </div>
  </section>`;
}

function configRemoteActionMarkup(host, targetKey, { compact = false, project = configRemoteProject() } = {}) {
  const buttonClass = compact ? "icon-button" : "button secondary";
  const label = (text) => compact ? "" : ` ${text}`;
  const recoveryBlocked = Boolean(configRemoteRecoveryForTarget(targetKey));
  const syncLabel = project ? "同步到主机 Home" : "同步本机配置";
  const syncTitle = project
    ? `当前是项目「${project.name ?? project.id}」；此操作仍写入远端用户主目录，不写项目目录`
    : "选择本机配置并同步到远程主机的用户主目录";
  return `<div class="config-remote-actions${compact ? " is-compact" : ""}">
    <button type="button" class="${buttonClass}" data-config-target-refresh="${escapeHtml(targetKey)}" title="刷新远程配置与环境" aria-label="刷新远程配置与环境"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-refresh-cw"></use></svg>${label("刷新")}</button>
    <button type="button" class="${buttonClass}" data-config-target-terminal="${escapeHtml(targetKey)}" title="打开 SSH 终端" aria-label="打开 SSH 终端"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-square-terminal"></use></svg>${label("SSH 终端")}</button>
    <button type="button" class="button secondary" data-config-host-sync="${escapeHtml(host.id)}" title="${escapeHtml(recoveryBlocked ? "上一次远端提交状态不确定；核对前禁止同步" : syncTitle)}"${recoveryBlocked ? " disabled" : ""}><svg aria-hidden="true" class="icon lucide"><use href="#lucide-cloud-upload"></use></svg> ${recoveryBlocked ? "等待事务核对" : syncLabel}</button>
  </div>`;
}

function configRemoteStandardSurface(host, context, { eyebrow, title, body }) {
  return `<div class="config-surface-heading config-remote-surface-heading">
      <div>
        <p class="eyebrow">${escapeHtml(eyebrow)}</p>
        <h2><svg aria-hidden="true" class="icon lucide"><use href="#lucide-${context.project ? "folder-git-2" : "globe"}"></use></svg> ${escapeHtml(title)}</h2>
        <p class="subtle config-remote-location">${escapeHtml(context.title)} · ${escapeHtml(context.location)}</p>
      </div>
      ${configRemoteActionMarkup(host, context.targetKey, { project: context.project })}
    </div>${body}`;
}

function configRemoteSurfaceBody(host, context) {
  if (state.configSurface === "local-runtime") {
    return configRemoteGraphBody(host, (graph) => configRemoteRuntimeWorkbench(host, graph));
  }
  if (state.configSurface === "hooks") {
    return `<section class="config-remote-hooks"><p class="eyebrow">远端钩子</p><h2>远端钩子尚未接入</h2><p class="subtle">Claude / Cursor / Codex 的 hooks 真源目前只支持本机编辑。请切回本机目标后再增删。</p></section>`;
  }
  if (state.configSurface === "capabilities") {
    return configRemoteStandardSurface(host, context, {
      eyebrow: `${context.eyebrow} · Agent · Skill · MCP`,
      title: "能力配置",
      body: configRemoteCapsBody(host),
    });
  }
  if (state.configSurface === "sources") {
    return configRemoteStandardSurface(host, context, {
      eyebrow: `${context.eyebrow} · Runtime & Sources`,
      title: "运行席位与真源",
      body: configRemoteSourcesBody(host),
    });
  }
  return configRemoteProvidersBody(host, context);
}

/** graph 三态壳：loading / error 如实呈现，ok 才进 render(data)。 */
function configRemoteGraphBody(host, render) {
  const entry = state.configHostGraph.get(configRemoteTargetKey());
  if (!entry || entry.status === "loading") {
    return skeleton({ variant: "list", rows: 5, label: "正在读取远程图谱（目录清单 + live 配置浅提取，最长 30s）" });
  }
  if (entry.status === "error") {
    return `<div class="waveg-review"><strong>远程图谱读取失败</strong><p class="subtle">${escapeHtml(entry.error)}</p></div>`;
  }
  return render(entry.data ?? {});
}

function configRemoteProviderSourceId(graph, row) {
  if (row.sourceId) return row.sourceId;
  return (graph.sources ?? []).find((file) => file.cli === row.cli
    && (file.scope ?? "host") === (row.scope ?? "host")
    && (file.projectRelative ?? file.remote) === row.file)?.id ?? null;
}

function configRemoteProviderApp(graph) {
  const targetKey = configRemoteTargetKey();
  const selected = state.configRemoteProviderApps.get(targetKey);
  if (PROVIDER_APPS.includes(selected)) return selected;
  const firstLive = (graph.providers ?? []).find((row) => row.exists && PROVIDER_APPS.includes(row.cli))?.cli;
  return firstLive ?? "claude";
}

function setConfigRemoteProviderApp(app) {
  if (!PROVIDER_APPS.includes(app)) return;
  state.configRemoteProviderApps.set(configRemoteTargetKey(), app);
  renderConfigRemotePanel();
}

function configRemoteProviderAppBar(graph) {
  return providerAppTabsMarkup({
    active: configRemoteProviderApp(graph),
    dataAttr: "data-config-remote-provider-app",
    focusable: true,
    extraTitle: (meta, count) => {
      const liveCount = (graph.providers ?? []).filter((row) => row.cli === meta.app && row.exists).length;
      return `${count} 个中央档案 · ${liveCount} 个远端 live 配置`;
    },
  });
}

function normalizeRemoteProviderUrl(value) {
  return String(value ?? "").trim().replace(/\/+$/, "").toLowerCase();
}

function configRemoteProviderMatchState(graph, app, provider) {
  const rows = (graph.providers ?? []).filter((row) => row.cli === app && row.exists);
  const confirmed = rows.some((row) => [row.providerId, row.profileId]
    .some((value) => String(value ?? "") === String(provider.id ?? "")));
  if (confirmed) return "confirmed";
  const expected = normalizeRemoteProviderUrl(provider.baseUrl);
  if (!expected) return "none";
  return rows.some((row) => normalizeRemoteProviderUrl(row.baseUrl) === expected) ? "endpoint" : "none";
}

function configRemoteProviderProfileRow(graph, item, meta, app) {
  const matchState = configRemoteProviderMatchState(graph, app, item);
  const confirmed = matchState === "confirmed";
  const endpointMatched = matchState === "endpoint";
  const health = healthBadgeOf(item.id);
  const latency = item.baseUrl ? state.providerLatency[item.baseUrl] : null;
  const busyKey = `${configRemoteTargetKey()}:provider:${app}:${item.id}`;
  const busy = state.configRemoteBusy.has(busyKey);
  const unsupported = app === "claude-desktop";
  const recoveryBlocked = Boolean(configRemoteRecoveryForTarget());
  return `<article class="provider-row${confirmed ? " is-current" : ""}${endpointMatched ? " is-endpoint-match" : ""} config-remote-provider-row" data-config-remote-provider-row="${escapeHtml(item.id)}">
    ${providerRowIdentityMarkup({
      item,
      meta,
      health,
      latency,
      handle: '<span class="provider-drag-handle" title="中央供应商档案" aria-hidden="true"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-database"></use></svg></span>',
      badges: confirmed
        ? '<span class="provider-badge is-live">档案已确认</span>'
        : endpointMatched ? '<span class="provider-badge is-warning">端点相同 · 档案待确认</span>' : "",
    })}
    <div class="provider-row-actions">
      <button class="${confirmed ? "provider-state-pill" : "button secondary provider-card-action"}" type="button" data-config-remote-provider-apply="${escapeHtml(`${app}::${item.id}`)}"${busy || unsupported || recoveryBlocked ? " disabled" : ""} title="${recoveryBlocked ? "上一次远端提交状态不确定；核对前禁止再次写入" : unsupported ? "无图形远端不支持 Claude Desktop" : confirmed ? "重新投影到当前远端" : endpointMatched ? "端点相同但远端未提供稳定档案标识；重新应用此档案" : "应用到远端"}">${confirmed ? '<svg class="icon lucide provider-state-pill-check" aria-hidden="true"><use href="#lucide-check"></use></svg>已确认' : busy ? "发布中…" : endpointMatched ? "重新应用并确认" : "应用到远端"}</button>
      <button class="icon-button provider-card-action" type="button" data-config-remote-provider-check="${escapeHtml(item.id)}" title="本机连通性检查" aria-label="检查 ${escapeHtml(item.name)}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-activity"></use></svg></button>
      ${item.baseUrl ? `<button class="icon-button provider-card-action" type="button" data-config-remote-provider-speed="${escapeHtml(item.id)}" title="本机到端点测速" aria-label="测速 ${escapeHtml(item.name)}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-gauge"></use></svg></button>` : ""}
      <button class="icon-button provider-card-action" type="button" data-config-remote-provider-edit="${escapeHtml(item.id)}" title="编辑中央档案" aria-label="编辑 ${escapeHtml(item.name)}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-settings"></use></svg></button>
      <button class="icon-button provider-card-action" type="button" data-config-remote-provider-delete="${escapeHtml(item.id)}" title="删除中央档案" aria-label="删除 ${escapeHtml(item.name)}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-trash-2"></use></svg></button>
    </div>
  </article>`;
}

function configRemoteLiveSummary(graph, app, meta) {
  const liveRows = (graph.providers ?? []).filter((row) => row.cli === app && row.exists);
  if (!liveRows.length) return `<p class="provider-live-line">远端 live：未检测到 ${escapeHtml(meta.label)} 配置</p>`;
  return liveRows.map((row) => {
    const sourceId = configRemoteProviderSourceId(graph, row);
    const scope = row.scope === "project" ? "项目覆盖" : "主机";
    const endpoint = row.baseUrl || "官方默认端点";
    return `<div class="config-remote-live-line"><span><span class="provider-badge is-live">live</span><strong>${escapeHtml(scope)}</strong><span>${escapeHtml(endpoint)}${row.model ? ` · ${escapeHtml(row.model)}` : ""}</span></span><button class="icon-button" type="button" data-config-remote-provider-source="${escapeHtml(sourceId ?? "")}" title="查看脱敏真源" aria-label="查看脱敏真源"${sourceId ? "" : " disabled"}><svg aria-hidden="true" class="icon lucide"><use href="#lucide-file-text"></use></svg></button></div>`;
  }).join("");
}

function configRemoteProviderTargetSnapshot() {
  const host = configRemoteHost();
  const project = configRemoteProject();
  return {
    key: configRemoteTargetKey(),
    hostId: state.configHostId,
    projectId: state.configProjectId,
    label: project ? `项目 ${project.name ?? project.id}` : `主机 ${host?.name ?? host?.id ?? state.configHostId}`,
  };
}

function configRemoteProviderEndpoint(target, action, { app = "", providerId = "" } = {}) {
  const base = target.projectId
    ? `/api/remote-projects/${encodeURIComponent(target.projectId)}`
    : `/api/ssh/hosts/${encodeURIComponent(target.hostId)}`;
  if (action === "plan") return `${base}/provider-plan?app=${encodeURIComponent(app)}&providerId=${encodeURIComponent(providerId)}`;
  return `${base}/provider-apply`;
}

async function applyConfigRemoteProvider(app, providerId, { skipConfirm = false, target = configRemoteProviderTargetSnapshot(), plan = null } = {}) {
  const provider = providerById(providerId);
  const meta = PROVIDER_APP_META.find((entry) => entry.app === app);
  if (!provider || !meta || !target.hostId) return null;
  if (configRemoteWriteBlocked(target, { notify: !skipConfirm })) return null;
  if (app === "claude-desktop") {
    toast("Claude Desktop 需要图形桌面，不能发布到当前无图形远端", "warning", 6000);
    return null;
  }
  const busyKey = `${target.key}:provider:${app}:${providerId}`;
  if (state.configRemoteBusy.has(busyKey)) return null;
  state.configRemoteBusy.add(busyKey);
  if (target.key === configRemoteTargetKey()) renderConfigRemotePanel();
  try {
    const publishPlan = plan ?? await request(configRemoteProviderEndpoint(target, "plan", { app, providerId }));
    if (!skipConfirm) {
      const changed = (publishPlan.files ?? []).filter((file) => file.changed);
      const proceed = await confirmAction({
        eyebrow: target.projectId ? "发布到远程项目" : "发布到远程主机",
        title: `将「${provider.name}」应用到 ${meta.label}？`,
        rows: [
          ["目标", target.label],
          ["文件", (publishPlan.files ?? []).map((file) => file.remote).join("、") || "无写入目标"],
          ["变更", `${changed.length} 个文件待发布，${(publishPlan.files ?? []).length - changed.length} 个无需改动`],
          ["事务", "远端原文件合并、0600 临时文件、备份、原子替换；多文件失败自动回滚"],
        ],
        warning: (publishPlan.files ?? []).some((file) => file.containsCredentialMaterial)
          ? "发布内容包含凭据材料。明文仅在服务端内存与 SSH/SFTP 通道中流动，不返回浏览器。"
          : "远端 live 配置将按中央档案投影，未知字段会从远端原文件保留。",
        confirmLabel: changed.length ? "应用到远端" : "重新校验",
      });
      if (!proceed) return null;
    }
    if (configRemoteWriteBlocked(target, { notify: !skipConfirm })) return null;
    const result = await request(configRemoteProviderEndpoint(target, "apply"), {
      method: "POST",
      body: { app, providerId, planRevision: publishPlan.planRevision },
    });
    const report = [
      ...(result.applied ?? []).map((file) => `已写入 ${file.remote}（${file.bytes}B，备份 ${file.backup ?? "无"}）`),
      ...(result.unchanged ?? []).map((remote) => `未改动 ${remote}`),
    ];
    configRemoteResult(`<div class="waveg-review"><strong>${escapeHtml(meta.label)} 已应用「${escapeHtml(provider.name)}」</strong><div class="waveg-log">${escapeHtml(report.join("\n") || "无文件变更")}</div></div>`, target.key);
    if (target.key === configRemoteTargetKey()) await loadConfigHostGraph(target.hostId, { force: true });
    return result;
  } catch (error) {
    const recovery = rememberConfigRemoteRecovery(target, error, error.message, "provider");
    configRemoteResult(`<div class="waveg-review${recovery ? " is-error" : ""}"><strong>${recovery ? "远端提交状态不确定，后续写入已阻断" : "远端发布失败"}</strong><p class="subtle">${escapeHtml(error.message)}</p>${recovery?.transactionId ? `<p class="mono">事务 ${escapeHtml(recovery.transactionId)}</p>` : ""}</div>`, target.key);
    if (!skipConfirm) toast(`远端发布失败：${error.message}`, "error", 7000);
    throw error;
  } finally {
    state.configRemoteBusy.delete(busyKey);
    if (target.key === configRemoteTargetKey()) renderConfigRemotePanel();
  }
}

async function applyConfigRemoteTeam(teamId) {
  const team = state.teams.find((entry) => entry.id === teamId);
  const target = configRemoteProviderTargetSnapshot();
  if (!team || !target.hostId) return;
  if (configRemoteWriteBlocked(target)) return;
  const bindings = Object.entries(team.providers ?? {}).filter(([app, id]) => PROVIDER_APPS.includes(app) && providerById(id));
  if (!bindings.length) {
    toast("该团队没有有效供应商绑定", "warning");
    return;
  }
  const busyKey = `${target.key}:team:${team.id}`;
  if (state.configRemoteBusy.has(busyKey)) return;
  state.configRemoteBusy.add(busyKey);
  if (target.key === configRemoteTargetKey()) renderConfigRemotePanel();
  const planned = [];
  try {
    for (const [app, providerId] of bindings) {
      if (app === "claude-desktop") {
        planned.push({ app, providerId, error: "无图形远端不支持 Claude Desktop" });
        continue;
      }
      try {
        const plan = await request(configRemoteProviderEndpoint(target, "plan", { app, providerId }));
        planned.push({ app, providerId, plan });
      } catch (error) {
        planned.push({ app, providerId, error: error.message });
      }
    }
    const proceed = await confirmAction({
      eyebrow: "远端团队方案",
      title: `将团队「${team.name}」应用到 ${target.label}？`,
      rows: [
        ["目标", target.label],
        ...planned.map((entry) => [
          PROVIDER_APP_META.find((meta) => meta.app === entry.app)?.label ?? entry.app,
          entry.error ? `不可发布：${entry.error}` : `${providerById(entry.providerId)?.name ?? entry.providerId} · ${entry.plan.files?.filter((file) => file.changed).length ?? 0} 个文件变更`,
        ]),
      ],
      warning: "每个应用各自原子发布并回滚；跨应用不做全局回滚，部分失败会逐项回报。",
      confirmLabel: "应用团队方案",
    });
    if (!proceed) return;
    const results = [];
    for (const entry of planned) {
      if (configRemoteWriteBlocked(target, { notify: false })) {
        results.push({ app: entry.app, ok: false, error: "上一项提交状态不确定，已阻止后续发布" });
        continue;
      }
      if (entry.error) {
        results.push({ app: entry.app, ok: false, error: entry.error });
        continue;
      }
      try {
        const result = await applyConfigRemoteProvider(entry.app, entry.providerId, { skipConfirm: true, target, plan: entry.plan });
        results.push(result
          ? { app: entry.app, ok: true }
          : { app: entry.app, ok: false, error: "提交前出现未和解事务，已阻止发布" });
      } catch (error) {
        results.push({ app: entry.app, ok: false, error: error.message });
      }
    }
    const lines = results.map((entry) => `${entry.ok ? "成功" : "失败"} ${PROVIDER_APP_META.find((meta) => meta.app === entry.app)?.label ?? entry.app}${entry.error ? `：${entry.error}` : ""}`);
    configRemoteResult(`<div class="waveg-review"><strong>团队「${escapeHtml(team.name)}」远端方案已执行</strong><div class="waveg-log">${escapeHtml(lines.join("\n"))}</div></div>`, target.key);
    if (target.key === configRemoteTargetKey()) await loadConfigHostGraph(target.hostId, { force: true });
  } finally {
    state.configRemoteBusy.delete(busyKey);
    if (target.key === configRemoteTargetKey()) renderConfigRemotePanel();
  }
}

const CONFIG_REMOTE_WORKBENCH_TABS = Object.freeze([
  { id: "env", label: "环境", icon: "wrench" },
  { id: "proxy", label: "代理", icon: "route" },
  { id: "resources", label: "资源", icon: "boxes" },
  { id: "sync", label: "同步", icon: "refresh-cw" },
  { id: "accounts", label: "账户", icon: "key-round" },
]);

const CONFIG_REMOTE_RESOURCE_TABS = Object.freeze([
  { id: "prompts", label: "Prompt" },
  { id: "mcps", label: "MCP" },
  { id: "skills", label: "Skill" },
  { id: "profiles", label: "Profile" },
  { id: "workspace", label: "Workspace" },
  { id: "backups", label: "Backup" },
]);

function configRemoteWorkbenchTab() {
  const selected = state.configRemoteWorkbenchTabs.get(configRemoteTargetKey());
  return CONFIG_REMOTE_WORKBENCH_TABS.some((tab) => tab.id === selected) ? selected : "env";
}

function setConfigRemoteWorkbenchTab(tab) {
  if (!CONFIG_REMOTE_WORKBENCH_TABS.some((entry) => entry.id === tab)) return;
  state.configRemoteWorkbenchTabs.set(configRemoteTargetKey(), tab);
  renderConfigRemotePanel();
}

function configRemoteResourceTab() {
  const selected = state.configRemoteResourceTabs.get(configRemoteTargetKey());
  return CONFIG_REMOTE_RESOURCE_TABS.some((tab) => tab.id === selected) ? selected : "prompts";
}

function setConfigRemoteResourceTab(tab) {
  if (!CONFIG_REMOTE_RESOURCE_TABS.some((entry) => entry.id === tab)) return;
  state.configRemoteResourceTabs.set(configRemoteTargetKey(), tab);
  renderConfigRemotePanel();
}

function configRemoteEnvironmentPanel(host, graph) {
  const probe = state.configHostProbes.get(host.id);
  const probeData = probe?.status === "ok" ? probe.data ?? {} : {};
  const clis = probeData.clis ?? [];
  const liveCount = (graph.providers ?? []).filter((row) => row.exists).length;
  const sourceCount = (graph.sources ?? []).filter((row) => row.exists).length;
  return `<div class="ccs-panel-body">
    <div class="ccs-metrics config-remote-metrics">
      <div><span>目标</span><strong>${escapeHtml(host.name ?? host.id)}</strong></div>
      <div><span>地址</span><strong class="mono">${escapeHtml(`${host.host ?? "?"}:${host.port ?? 22}`)}</strong></div>
      <div><span>live 配置</span><strong>${liveCount}/${graph.providers?.length ?? 0}</strong></div>
      <div><span>CLI</span><strong>${clis.filter((cli) => cli.installed).length}/${clis.length}</strong></div>
      <div><span>真源</span><strong>${sourceCount}</strong></div>
    </div>
    <section class="ccs-tool config-remote-runtime-environment">
      <div class="ccs-tool-heading"><h3>远程环境</h3><span>${escapeHtml(probeData.os ?? "等待探测")}</span></div>
      ${configRemoteEnvBody(host)}
    </section>
  </div>`;
}

function configRemoteProxyPanel(host) {
  const targetKey = configRemoteTargetKey();
  const probe = state.configRemoteProxyProbes.get(targetKey);
  if (!probe) {
    return `<div class="ccs-panel-body"><section class="ccs-tool"><div class="ccs-tool-heading"><h3>远端代理诊断</h3><button class="button secondary" type="button" data-config-remote-proxy-diagnose="${escapeHtml(host.id)}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-activity"></use></svg>运行诊断</button></div><p class="subtle">尚未读取代理环境、常见监听端口和固定 API 端点出站状态。</p></section></div>`;
  }
  if (probe.status === "loading") return `<div class="ccs-panel-body">${skeleton({ variant: "list", rows: 4, label: "正在远端执行代理与出站诊断" })}</div>`;
  if (probe.status === "error") return `<div class="ccs-panel-body"><div class="waveg-review"><strong>代理诊断失败</strong><p class="subtle">${escapeHtml(probe.error)}</p><button class="button secondary" type="button" data-config-remote-proxy-diagnose="${escapeHtml(host.id)}">重试</button></div></div>`;
  const data = probe.data ?? {};
  const envRows = (data.environment ?? []).map((entry) => `<tr><td><code>${escapeHtml(entry.name)}</code></td><td class="mono">${escapeHtml(entry.value)}</td></tr>`).join("");
  const outbound = (data.outbound ?? []).map((entry) => `<tr><td>${escapeHtml(entry.url)}</td><td><span class="status-label ${entry.ok ? "is-ok" : "is-error"}">${entry.status || `exit ${entry.exitCode}`}</span></td><td>${entry.timeMs == null ? "—" : `${entry.timeMs}ms`}</td></tr>`).join("");
  return `<div class="ccs-panel-body config-remote-proxy-panel">
    <section class="ccs-tool"><div class="ccs-tool-heading"><h3>代理环境</h3><button class="icon-button" type="button" data-config-remote-proxy-diagnose="${escapeHtml(host.id)}" title="重新诊断" aria-label="重新诊断"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-refresh-cw"></use></svg></button></div>${envRows ? `<div class="table-wrap"><table class="config-remote-table"><thead><tr><th>变量</th><th>值</th></tr></thead><tbody>${envRows}</tbody></table></div>` : '<p class="subtle">未设置代理环境变量。</p>'}</section>
    <section class="ccs-tool"><div class="ccs-tool-heading"><h3>监听端口</h3><span>${data.listeners?.length ?? 0}</span></div>${data.listeners?.length ? `<pre class="waveg-log">${escapeHtml(data.listeners.join("\n"))}</pre>` : '<p class="subtle">常见代理端口未发现监听。</p>'}</section>
    <section class="ccs-tool"><div class="ccs-tool-heading"><h3>出站</h3><span>${data.curlAvailable === false ? "curl 未安装" : `${data.outbound?.filter((entry) => entry.ok).length ?? 0}/${data.outbound?.length ?? 0}`}</span></div>${outbound ? `<div class="table-wrap"><table class="config-remote-table"><thead><tr><th>端点</th><th>HTTP</th><th>耗时</th></tr></thead><tbody>${outbound}</tbody></table></div>` : inlineEmpty("无出站结果")}</section>
    <p class="subtle">当前远端未部署 514cc 常驻代理内核，此处仅诊断，不提供启停控制。</p>
  </div>`;
}

function configRemoteResourceRows(graph, tab) {
  if (tab === "prompts") return (graph.capabilities ?? []).filter((item) => ["prompt", "command"].includes(item.kind)).map((item) => ({ name: item.name, type: item.kind, scope: item.scope ?? "host", detail: remoteCliLabel(item.cli) }));
  if (tab === "mcps") return (graph.mcp ?? []).map((item) => ({ name: item.name, type: "MCP", scope: item.scope ?? "host", detail: `${remoteCliLabel(item.cli)} · ${item.source}` }));
  if (tab === "skills") return (graph.capabilities ?? []).filter((item) => item.kind === "skill").map((item) => ({ name: item.name, type: "Skill", scope: item.scope ?? "host", detail: remoteCliLabel(item.cli) }));
  if (tab === "profiles") return (graph.providers ?? []).filter((item) => item.exists).map((item) => ({ name: item.label, type: "Profile", scope: item.scope ?? "host", detail: item.file, sourceId: configRemoteProviderSourceId(graph, item) }));
  if (tab === "workspace") return (graph.sources ?? []).map((item) => ({ name: item.label, type: item.exists ? "Source" : "Missing", scope: item.scope ?? "host", detail: item.projectRelative ?? item.remote, sourceId: item.id, disabled: !item.exists }));
  return (graph.backups ?? []).map((item) => ({ name: item.name, type: "Backup", scope: item.scope ?? "host", detail: `${item.remote}${item.size != null ? ` · ${formatConfigBytes(item.size)}` : ""}` }));
}

function configRemoteResourcesPanel(graph) {
  const active = configRemoteResourceTab();
  const rows = configRemoteResourceRows(graph, active);
  return `<div class="ccs-panel-body config-remote-resources-panel">
    <div class="config-remote-resource-tabs" role="tablist" aria-label="远端资源分类">${CONFIG_REMOTE_RESOURCE_TABS.map((tab) => `<button type="button" role="tab" class="button secondary${tab.id === active ? " is-active" : ""}" aria-selected="${tab.id === active}" tabindex="${tab.id === active ? "0" : "-1"}" data-config-remote-resource-tab="${tab.id}">${tab.label}</button>`).join("")}</div>
    <div class="config-remote-resource-list">${rows.length ? rows.map((item) => `<div class="config-remote-resource-row"><span class="config-remote-resource-icon"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-${active === "mcps" ? "webhook" : active === "skills" ? "puzzle" : active === "backups" ? "archive" : "file-text"}"></use></svg></span><div><strong>${escapeHtml(item.name)}</strong><span>${escapeHtml(item.type)} · ${item.scope === "project" ? "项目" : "主机"} · ${escapeHtml(item.detail)}</span></div><div class="config-remote-resource-actions">${item.sourceId ? `<button class="icon-button" type="button" data-config-remote-provider-source="${escapeHtml(item.sourceId)}" title="打开真源" aria-label="打开真源"${item.disabled ? " disabled" : ""}><svg aria-hidden="true" class="icon lucide"><use href="#lucide-scan-search"></use></svg></button>` : ""}<button class="icon-button" type="button" data-config-target-terminal="${escapeHtml(configRemoteTargetKey())}" title="在 SSH 终端管理" aria-label="在 SSH 终端管理"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-square-terminal"></use></svg></button></div></div>`).join("") : `<div class="provider-global-empty"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-archive"></use></svg><div><strong>当前分类为空</strong><span>${active === "backups" ? "尚未在图谱中检测到 514forge 发布备份" : "远端已知目录中没有对应条目"}</span></div><button class="button secondary" type="button" data-config-target-terminal="${escapeHtml(configRemoteTargetKey())}">SSH 终端</button></div>`}</div>
  </div>`;
}

function loadConfigRemoteSyncPlan(hostId, { force = false } = {}) {
  if (!hostId || (!force && state.configRemoteSyncPlans.has(hostId))) return;
  state.configRemoteSyncPlans.set(hostId, { status: "loading" });
  request(`/api/ssh/hosts/${encodeURIComponent(hostId)}/env-sync/plan`).then((result) => {
    state.configRemoteSyncPlans.set(hostId, { status: "ok", data: result });
  }).catch((error) => {
    state.configRemoteSyncPlans.set(hostId, { status: "error", error: error.message });
  }).finally(() => {
    if (state.configHostId === hostId && configRemoteWorkbenchTab() === "sync") renderConfigRemotePanel();
  });
}

function configRemoteSyncPanel(host) {
  const plan = state.configRemoteSyncPlans.get(host.id);
  if (!plan) {
    loadConfigRemoteSyncPlan(host.id);
    return `<div class="ccs-panel-body">${skeleton({ variant: "list", rows: 4, label: "正在读取本机可同步配置清单" })}</div>`;
  }
  if (plan.status === "loading") return `<div class="ccs-panel-body">${skeleton({ variant: "list", rows: 4, label: "正在读取本机可同步配置清单" })}</div>`;
  if (plan.status === "error") return `<div class="ccs-panel-body"><div class="waveg-review"><strong>同步计划读取失败</strong><p class="subtle">${escapeHtml(plan.error)}</p><button class="button secondary" type="button" data-config-remote-sync-refresh="${escapeHtml(host.id)}">重试</button></div></div>`;
  const files = plan.data?.files ?? [];
  const blocked = configRemoteWriteBlocked({ key: `host:${host.id}`, hostId: host.id, projectId: null }, { notify: false });
  return `<div class="ccs-panel-body"><section class="ccs-tool"><div class="ccs-tool-heading"><h3>本机配置同步</h3><div><button class="icon-button" type="button" data-config-remote-sync-refresh="${escapeHtml(host.id)}" title="刷新计划" aria-label="刷新计划"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-refresh-cw"></use></svg></button><button class="button secondary" type="button" data-config-host-sync="${escapeHtml(host.id)}"${blocked ? ' disabled title="存在未核对远端事务，暂不可同步"' : ""}><svg aria-hidden="true" class="icon lucide"><use href="#lucide-cloud-upload"></use></svg>${blocked ? "等待事务核对" : "选择并同步"}</button></div></div><div class="config-remote-resource-list">${files.map((file) => `<div class="config-remote-resource-row"><span class="config-remote-resource-icon"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-file-input"></use></svg></span><div><strong>${escapeHtml(file.label)}</strong><span>${escapeHtml(file.local)} → ~/${escapeHtml(file.remote)} · ${file.exists ? formatConfigBytes(file.size) : "本机不存在"}</span></div><span class="status-label ${!file.exists ? "is-neutral" : file.containsSecrets ? "is-warning" : "is-ok"}">${!file.exists ? "缺失" : file.containsSecrets ? "含秘密" : "可同步"}</span></div>`).join("")}</div></section></div>`;
}

function configRemoteAccountsPanel(host, graph) {
  const probe = state.configHostProbes.get(host.id);
  const clis = probe?.status === "ok" ? probe.data?.clis ?? [] : [];
  const cliId = (app) => app === "grokbuild" ? "grok" : app;
  const rows = PROVIDER_APP_META.map((meta) => {
    const cli = clis.find((entry) => entry.id === cliId(meta.app));
    const configs = (graph.providers ?? []).filter((entry) => entry.cli === meta.app && entry.exists);
    const unsupported = meta.app === "claude-desktop";
    return `<div class="config-remote-account-row"><span class="config-remote-resource-icon"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-${meta.icon}"></use></svg></span><div><strong>${escapeHtml(meta.label)}</strong><span>${unsupported ? "无图形远端不适用" : `${cli?.installed ? `CLI ${escapeHtml(cli.version ?? "已安装")}` : "CLI 未安装"} · ${configs.length ? `${configs.length} 个配置已检测` : "未检测到配置"}`}</span></div><span class="status-label ${unsupported ? "is-neutral" : cli?.installed && configs.length ? "is-ok" : "is-warning"}">${unsupported ? "不适用" : cli?.installed && configs.length ? "配置存在" : "待配置"}</span>${unsupported ? "" : `<button class="icon-button" type="button" data-config-target-terminal="${escapeHtml(configRemoteTargetKey())}" title="在 SSH 终端登录或检查账户" aria-label="在 SSH 终端检查 ${escapeHtml(meta.label)} 账户"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-square-terminal"></use></svg></button>`}</div>`;
  }).join("");
  return `<div class="ccs-panel-body"><div class="config-remote-account-list">${rows}</div><p class="subtle">“配置存在”不等于已登录；登录与设备码授权在对应 SSH 终端中完成。</p></div>`;
}

function configRemoteRuntimeWorkbench(host, graph) {
  const probe = state.configHostProbes.get(host.id);
  const statusClass = probe?.status === "error" ? "is-error" : probe?.status === "ok" ? "is-ok" : "is-neutral";
  const statusLabel = probe?.status === "error" ? "探测失败" : probe?.status === "ok" ? "已连接" : "探测中";
  const active = configRemoteWorkbenchTab();
  const body = active === "proxy"
    ? configRemoteProxyPanel(host)
    : active === "resources"
      ? configRemoteResourcesPanel(graph)
      : active === "sync"
        ? configRemoteSyncPanel(host)
        : active === "accounts"
          ? configRemoteAccountsPanel(host, graph)
          : configRemoteEnvironmentPanel(host, graph);
  return `<section class="ccswitch-workbench config-remote-workbench" aria-label="远端运行与配置工作台">
    <div class="ccs-heading">
      <div><p class="eyebrow">远端运行时</p><h2>运行与配置工作台</h2></div>
      <div class="ccs-heading-actions"><span class="status-label ${statusClass}">${statusLabel}</span><button class="icon-button" type="button" data-config-target-refresh="${escapeHtml(configRemoteTargetKey())}" title="刷新远程运行环境" aria-label="刷新远程运行环境"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-refresh-cw"></use></svg></button></div>
    </div>
    <div class="ccs-tabs" role="tablist" aria-label="远端运行工作台视图">
      ${CONFIG_REMOTE_WORKBENCH_TABS.map((tab) => `<button type="button" role="tab" class="ccs-tab${tab.id === active ? " is-active" : ""}" aria-selected="${tab.id === active}" tabindex="${tab.id === active ? "0" : "-1"}" data-config-remote-workbench-tab="${tab.id}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-${tab.icon}"></use></svg><span>${tab.label}</span></button>`).join("")}
    </div>
    ${body}
  </section>`;
}

/** surface ①：供应商与应用——与本机同构的应用标签、live 配置行和运行工作台。 */
function configRemoteProvidersBody(host, context) {
  return configRemoteGraphBody(host, (graph) => {
    const activeApp = configRemoteProviderApp(graph);
    const activeMeta = PROVIDER_APP_META.find((entry) => entry.app === activeApp) ?? PROVIDER_APP_META[0];
    const liveRows = (graph.providers ?? []).filter((row) => row.cli === activeApp && row.exists);
    const profiles = (state.providersData?.providers ?? []).filter((item) => item.apps?.[activeApp]);
    const rows = profiles.map((item) => configRemoteProviderProfileRow(graph, item, activeMeta, activeApp)).join("");
    const boundTeams = state.teams.filter((team) => providerSchemeBindings(team).length > 0);
    const teamBusy = boundTeams.some((team) => state.configRemoteBusy.has(`${context.targetKey}:team:${team.id}`));
  const recoveryBlocked = Boolean(configRemoteRecoveryForTarget(context.targetKey));
    return `${configRemoteHealthDashboard(host, graph)}<section class="provider-deck config-remote-provider-deck" aria-labelledby="config-remote-provider-title">
        <div class="provider-deck-heading">
          <div>
            <h2 id="config-remote-provider-title">供应商方案</h2>
            <p>${escapeHtml(context.title)} · ${escapeHtml(context.location)} · 中央档案与本机共用，发布目标切换到当前远端。</p>
          </div>
          <div class="provider-deck-actions">
            <span class="status-label is-ok config-remote-target-status"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-${context.project ? "folder-git-2" : "globe"}"></use></svg>${context.project ? "项目" : "主机"}</span>
            <button class="button secondary" type="button" data-config-remote-provider-add="${escapeHtml(activeApp)}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-plus"></use></svg> 新增供应商</button>
            ${configRemoteActionMarkup(host, context.targetKey, { compact: true, project: context.project })}
          </div>
        </div>
        <div class="provider-app-bar" role="tablist" aria-label="按应用切换远端供应商列表">${configRemoteProviderAppBar(graph)}</div>
        <div class="provider-columns config-remote-provider-columns">
          <div class="provider-app-strip">
            ${configRemoteLiveSummary(graph, activeApp, activeMeta)}
            <div class="provider-row-list">${rows || `<p class="subtle provider-deck-placeholder">中央档案尚未关联 ${escapeHtml(activeMeta.label)}。 <button class="provider-link-button" type="button" data-config-remote-provider-add="${escapeHtml(activeApp)}">新增/关联</button></p>`}</div>
          </div>
          <div class="provider-team-apply config-remote-team-apply"><label>团队方案<select data-config-remote-team>${boundTeams.length ? boundTeams.map((team) => `<option value="${escapeHtml(team.id)}">${escapeHtml(team.name)}（${providerSchemeBindings(team).length} 绑）</option>`).join("") : '<option value="">无绑定团队</option>'}</select></label><button class="button secondary" type="button" data-config-remote-team-apply${!boundTeams.length || teamBusy || recoveryBlocked ? " disabled" : ""} title="${recoveryBlocked ? "上一次远端提交状态不确定；核对前禁止批量发布" : "应用团队供应商绑定"}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-users"></use></svg>${teamBusy ? "应用中…" : recoveryBlocked ? "等待事务核对" : "应用到当前远端"}</button></div>
        </div>
      </section>`;
  });
}

/** surface ②：Agent·Skill·MCP——按已知目录浅扫描的能力清单 + live 配置里的 MCP 键名。 */
function configRemoteCapabilityName(value) {
  return String(value ?? "").replace(/\.(?:md|toml|json|ya?ml)$/i, "");
}

function configRemoteCapsBody(host) {
  return configRemoteGraphBody(host, (graph) => {
    const caps = graph.capabilities ?? [];
    const probe = state.configHostProbes.get(host.id);
    const clis = probe?.status === "ok" ? probe.data?.clis ?? [] : [];
    const agents = caps.filter((cap) => cap.kind === "agent");
    const skills = caps.filter((cap) => cap.kind === "skill");
    const declaredClis = [...new Set([...clis.filter((cli) => cli.installed).map((cli) => cli.id), ...skills.map((skill) => skill.cli)])];
    const agentCards = agents.length ? agents.map((agent) => {
      const cli = agent.cli === "grokbuild" ? "grok" : agent.cli;
      const logo = cliIconMarkup(cli, "cli-logo") || '<svg aria-hidden="true" class="icon lucide"><use href="#lucide-bot"></use></svg>';
      return `<article class="cap-agent-chip config-remote-agent-chip"><span class="config-remote-agent-logo">${logo}</span><strong>${escapeHtml(configRemoteCapabilityName(agent.name))}</strong><span>${escapeHtml(remoteCliLabel(agent.cli))} · ${agent.scope === "project" ? "项目" : "主机"}</span><code>${escapeHtml(agent.name)}</code></article>`;
    }).join("") : '<span class="subtle">已扫描的远端目录中没有 Agent 声明。</span>';
    const skillHead = declaredClis.map((cli) => `<th scope="col">${escapeHtml(remoteCliLabel(cli === "grok" ? "grokbuild" : cli))}</th>`).join("");
    const skillRows = skills.length ? skills.map((skill) => `<tr><td class="mono cap-skill-source"><span>${escapeHtml(configRemoteCapabilityName(skill.name))}</span><small>${skill.scope === "project" ? "项目" : "主机"}</small></td>${declaredClis.map((cli) => {
      const detected = skill.cli === cli || (skill.cli === "grokbuild" && cli === "grok");
      return `<td class="cap-cell">${detected ? `<span class="cap-detected-badge" aria-label="${escapeHtml(remoteCliLabel(cli))} 已检测到 ${escapeHtml(skill.name)}">已检测到</span>` : `<span class="subtle">未检测到</span>`}</td>`;
    }).join("")}</tr>`).join("") : `<tr><td colspan="${Math.max(1, declaredClis.length + 1)}" class="subtle">未检测到 Skill 目录条目</td></tr>`;
    const mcp = graph.mcp ?? [];
    const mcpRows = mcp.length ? mcp.map((entry) => `<tr><td class="mono">${escapeHtml(entry.name)}</td><td>配置声明</td><td>${escapeHtml(remoteCliLabel(entry.cli))}</td><td>${entry.scope === "project" ? "项目" : "主机"}</td><td class="mono cap-path" title="${escapeHtml(entry.source)}">${escapeHtml(entry.source)}</td><td><button class="icon-button" type="button" data-config-target-terminal="${escapeHtml(configRemoteTargetKey())}" title="在 SSH 终端管理" aria-label="在 SSH 终端管理 ${escapeHtml(entry.name)}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-square-terminal"></use></svg></button></td></tr>`).join("") : '<tr><td colspan="6" class="subtle">未检测到 MCP 配置声明</td></tr>';
    return `<section class="content-section config-remote-cap-section" aria-labelledby="config-remote-agents-title"><div class="section-heading"><div><h2 id="config-remote-agents-title">Agent 花名册</h2><p>远端已知 Agent 目录中的命名 Agent 及其 CLI 承载</p></div><span class="status-label is-neutral">${agents.length} Agent</span></div><div class="chip-grid config-remote-agent-grid">${agentCards}</div></section>
      <section class="content-section config-remote-cap-section" aria-labelledby="config-remote-skills-title"><div class="section-heading"><div><h2 id="config-remote-skills-title">Skill 检测矩阵</h2><p>${skills.length} 个 Skill · ${declaredClis.length} 个已接入 CLI · 徽标只表示目录探测结果，远端不能在这里启停</p></div></div><div class="table-scroll"><table class="data-table cap-matrix config-remote-skill-matrix"><thead><tr><th scope="col">Skill</th>${skillHead}</tr></thead><tbody>${skillRows}</tbody></table></div></section>
      <section class="content-section config-remote-cap-section" aria-labelledby="config-remote-mcp-title"><div class="section-heading"><div><h2 id="config-remote-mcp-title">MCP 服务器</h2><p>${mcp.length} 个配置声明 · 只展示名称、来源和范围，不将 env 或参数带入浏览器</p></div></div><div class="table-scroll"><table class="data-table config-remote-mcp-table"><thead><tr><th>名称</th><th>传输</th><th>入口</th><th>范围</th><th>来源文件</th><th>操作</th></tr></thead><tbody>${mcpRows}</tbody></table></div></section>`;
  });
}

/** surface ③：运行席位与真源——CLI 矩阵（probe 实况 + 安装钮）+ 真源文件列表（点击展开脱敏内容）。 */
function configRemoteRuntimeMode() {
  const selected = state.configRemoteRuntimeModes.get(configRemoteTargetKey());
  return selected === "sources" ? "sources" : "seats";
}

function setConfigRemoteRuntimeMode(mode) {
  if (!["seats", "sources"].includes(mode)) return;
  state.configRemoteRuntimeModes.set(configRemoteTargetKey(), mode);
  renderConfigRemotePanel();
}

function handleConfigRemoteTabKey(event) {
  if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return;
  const current = event.target.closest('[role="tab"]');
  const tablist = current?.closest('[role="tablist"]');
  if (!current || !tablist || !tablist.closest("#config-surface-remote")) return;
  const tabs = [...tablist.querySelectorAll(':scope > [role="tab"]')].filter((tab) => !tab.disabled);
  const index = tabs.indexOf(current);
  if (index < 0 || tabs.length < 2) return;
  const direction = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : -1;
  const nextIndex = event.key === "Home" ? 0 : event.key === "End" ? tabs.length - 1 : (index + direction + tabs.length) % tabs.length;
  const next = tabs[nextIndex];
  const selector = next.dataset.configRemoteProviderApp
    ? `[data-config-remote-provider-app="${CSS.escape(next.dataset.configRemoteProviderApp)}"]`
    : next.dataset.configRemoteWorkbenchTab
      ? `[data-config-remote-workbench-tab="${CSS.escape(next.dataset.configRemoteWorkbenchTab)}"]`
      : next.dataset.configRemoteResourceTab
        ? `[data-config-remote-resource-tab="${CSS.escape(next.dataset.configRemoteResourceTab)}"]`
        : `[data-config-remote-runtime-mode="${CSS.escape(next.dataset.configRemoteRuntimeMode ?? "")}"]`;
  event.preventDefault();
  next.click();
  requestAnimationFrame(() => document.querySelector(`#config-surface-remote ${selector}`)?.focus());
}

function configRemoteCliGraphId(cliId) {
  return cliId === "grok" ? "grokbuild" : cliId;
}

function configRemoteSelectedCli(host, graph) {
  const targetKey = configRemoteTargetKey();
  const clis = state.configHostProbes.get(host.id)?.data?.clis ?? [];
  const selected = state.configRemoteSelectedClis.get(targetKey);
  if (clis.some((cli) => cli.id === selected)) return selected;
  const graphClis = new Set([...(graph.providers ?? []).map((row) => row.cli), ...(graph.sources ?? []).map((row) => row.cli)]);
  return clis.find((cli) => cli.installed && graphClis.has(configRemoteCliGraphId(cli.id)))?.id
    ?? clis.find((cli) => cli.installed)?.id
    ?? clis[0]?.id
    ?? null;
}

function setConfigRemoteSelectedCli(cliId) {
  if (!cliId) return;
  state.configRemoteSelectedClis.set(configRemoteTargetKey(), cliId);
  renderConfigRemotePanel();
}

/**
 * 差异视图：远端真源只在「返回内容 === 远端原文」时可编辑（remote-graph.mjs readSource 的
 * redacted 判定），所以这里的基线是真原文，不是脱敏投影——否则 diff 会把 [REDACTED] 当成事实。
 */
function configRemoteDiffMarkup(before, after, { emptyLabel = "无变更", label = "差异预览" } = {}) {
  const diff = createLocalDiff(before ?? "", after ?? "");
  if (diff === "无变更") return `<p class="subtle config-remote-diff-empty">${escapeHtml(emptyLabel)}</p>`;
  return `<pre class="diff-output config-remote-diff" aria-label="${escapeHtml(label)}">${diffMarkup(diff)}</pre>`;
}

function configRemoteBackupRows(graph, fileId) {
  return (graph.backups ?? [])
    .filter((entry) => entry.sourceId === fileId)
    .slice()
    .sort((left, right) => String(right.mtime ?? "").localeCompare(String(left.mtime ?? "")));
}

function formatConfigBackupTime(value) {
  return value ? String(value).replace("T", " ").slice(0, 16) : "时间未知";
}

/**
 * 备份时间线：发布备份（writeSource 的 `.514forge-backup-<txid>`）是远端唯一的回滚材料。
 * 对比读服务端脱敏投影；恢复只提交备份名与当前 digest——原文在服务端从备份直接进 writeSource
 * 事务，既不过浏览器，也不新增写通道（CAS/锁/原子发布/恢复台账全部继承）。
 */
function configRemoteBackupTimeline(graph, file, targetKey, { editable = false, hidden = false, currentContent = "" } = {}) {
  const rows = configRemoteBackupRows(graph, file.id);
  const heading = (extra) => `<section class="config-remote-backup-timeline" aria-label="${escapeHtml(file.label)} 发布备份">
    <header><h4>发布备份</h4><span class="subtle">${rows.length} 份</span></header>${extra}</section>`;
  if (hidden) return heading(`<p class="subtle">凭据载体的备份内容不出远端主机，此处不提供对比或恢复。</p>`);
  if (!rows.length) return heading(`<p class="subtle">该真源还没有 514forge 发布备份；每次保存或恢复都会留下一份。</p>`);
  const compareName = state.configRemoteBackupCompare.get(`${targetKey}:${file.id}`) ?? null;
  const items = rows.map((entry) => {
    const active = compareName === entry.name;
    const cache = active ? state.configRemoteBackupCache.get(`${targetKey}:${file.id}:${entry.name}`) : null;
    const busy = state.configRemoteBusy.has(`${targetKey}:restore:${entry.name}`);
    // 服务端才是恢复的最终判据；对比过之后 restorable=false 就提前禁用，并如实说明原因。
    const unrestorable = cache?.status === "ok" && cache.data?.restorable === false;
    const restoreTitle = !editable
      ? "该真源在远端为只读，恢复会被服务端拒绝"
      : unrestorable
        ? cache.data?.truncated ? "备份超过 1MB 读取上限，恢复会截断内容" : "备份含凭据材料，不能经编辑器恢复"
        : "用此备份覆盖当前远端内容";
    let body = "";
    if (active) {
      if (!cache || cache.status === "loading") {
        body = skeleton({ variant: "list", rows: 3, label: "正在读取备份（SFTP 围栏 + 1MB cap + 脱敏）" });
      } else if (cache.status === "error") {
        body = `<p class="subtle">备份读取失败：${escapeHtml(cache.error)}</p>`;
      } else {
        const data = cache.data ?? {};
        body = `<p class="subtle config-remote-backup-note">下面是「恢复这份备份」会产生的变更：<code>-</code> 会失去，<code>+</code> 会回来。</p>`
          + configRemoteDiffMarkup(currentContent, data.content ?? "", {
            emptyLabel: "此备份与当前远端内容一致，恢复不会改变任何内容。",
            label: `${file.label} 恢复差异`,
          })
          + (data.redacted ? `<p class="subtle">对比视图中有片段被脱敏替换；恢复写回的是服务端读到的原文，不是这里显示的文本。</p>` : "")
          + (data.truncated ? `<p class="subtle">备份超过 1MB，仅对比前段，且不允许恢复（会截断）。</p>` : "");
      }
    }
    return `<div class="config-remote-backup-row${active ? " is-open" : ""}">
      <div class="config-remote-backup-head">
        <span class="config-remote-backup-dot" aria-hidden="true"></span>
        <div class="config-remote-backup-meta"><strong>${escapeHtml(formatConfigBackupTime(entry.mtime))}</strong><code title="${escapeHtml(entry.remote ?? entry.name)}">${escapeHtml(entry.name)}</code><span class="subtle">${escapeHtml(formatConfigBytes(entry.size))}</span></div>
        <div class="config-remote-backup-actions">
          <button class="button secondary" type="button" data-config-remote-backup-compare="${escapeHtml(entry.name)}" data-config-remote-backup-source="${escapeHtml(file.id)}" aria-pressed="${active}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-scan-search"></use></svg>${active ? "收起" : "对比"}</button>
          <button class="button secondary" type="button" data-config-remote-backup-restore="${escapeHtml(entry.name)}" data-config-remote-backup-source="${escapeHtml(file.id)}" title="${escapeHtml(restoreTitle)}"${!editable || busy || unrestorable ? " disabled" : ""}><svg aria-hidden="true" class="icon lucide"><use href="#lucide-history"></use></svg>${busy ? "恢复中…" : "恢复"}</button>
        </div>
      </div>
      ${active ? `<div class="config-remote-backup-body">${body}</div>` : ""}
    </div>`;
  }).join("");
  return heading(`<div class="config-remote-backup-list">${items}</div>
    <p class="subtle">恢复复用保存的同一条事务链：先按 digest 比对远端现状，再为当前内容留下新备份后原子替换——所以恢复本身仍可回滚。</p>`);
}

function configRemoteSourceList(graph) {
    const openSel = state.configHostSourceOpen;
    const targetKey = configRemoteTargetKey();
    const rows = (graph.sources ?? []).map((file) => {
      const isOpen = openSel?.targetKey === targetKey && openSel?.fileId === file.id;
      let detail = "";
      if (isOpen) {
        const cache = state.configHostSourceCache.get(`${targetKey}:${file.id}`);
        if (!cache || cache.status === "loading") {
          detail = skeleton({ variant: "list", rows: 3, label: "正在读取真源（SFTP 围栏 + 1MB cap + 脱敏）" });
        } else if (cache.status === "error") {
          detail = `<p class="subtle">读取失败：${escapeHtml(cache.error)}</p>`;
        } else {
          const data = cache.data ?? {};
          const cacheKey = `${targetKey}:${file.id}`;
          const draft = state.configHostSourceDrafts.get(cacheKey);
          const sourceBusy = state.configRemoteBusy.has(`${targetKey}:source:${file.id}`);
          const diffOpen = state.configRemoteSourceDiffs.has(`${targetKey}:${file.id}`);
          if (data.editable) {
            const content = draft?.content ?? data.content ?? "";
            detail = `<div class="config-remote-source-editor-shell">
              <textarea class="config-remote-source-editor" data-config-remote-source-editor="${escapeHtml(file.id)}" spellcheck="false" aria-label="编辑 ${escapeHtml(file.label)}">${escapeHtml(content)}</textarea>
              <div class="config-remote-source-editor-actions"><span class="subtle">${sourceBusy ? "正在保存…" : data.exists ? `SHA-256 ${escapeHtml(String(data.digest).slice(0, 12))}…` : "新建文件"}${draft?.dirty ? " · 未保存" : ""}</span><button class="button secondary" type="button" data-config-remote-source-diff="${escapeHtml(file.id)}" aria-pressed="${diffOpen}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-list"></use></svg>${diffOpen ? "收起变更" : "预览变更"}</button><button class="button secondary" type="button" data-config-remote-source-reload="${escapeHtml(file.id)}"${sourceBusy ? " disabled" : ""}>重新载入</button><button class="button primary" type="button" data-config-remote-source-save="${escapeHtml(file.id)}"${draft?.dirty && !sourceBusy ? "" : " disabled"}><svg aria-hidden="true" class="icon lucide"><use href="#lucide-save"></use></svg>${data.exists ? "保存" : "创建"}</button></div>
              ${diffOpen ? `<div class="config-remote-source-diff-shell"><header><h4>保存前差异</h4><span class="subtle">基线＝打开时读到的远端原文</span></header>${configRemoteDiffMarkup(data.content ?? "", content, { emptyLabel: "草稿与远端当前内容一致。", label: `${file.label} 保存前差异` })}</div>` : ""}
            </div>`;
          } else {
            detail = data.contentHidden
              ? `<p class="subtle">该文件是凭据载体，内容不会进入浏览器。</p>`
              : `<pre class="waveg-log">${escapeHtml(data.content ?? "")}</pre>`
                + (data.sensitive ? `<p class="subtle">检测到凭据材料，保持脱敏只读。</p>` : "")
              + (data.truncated ? `<p class="subtle">内容超过 1MB，仅显示前段（已脱敏）。</p>` : "")
              + (data.redacted && !data.sensitive && !data.contentHidden
                ? `<p class="subtle">内容中有片段被脱敏替换；为避免保存时把 <code>[REDACTED]</code> 写回远端真源，此文件保持只读。</p>`
                : "");
          }
          if (data.exists) {
            detail += configRemoteBackupTimeline(graph, file, targetKey, {
              editable: data.editable === true,
              hidden: data.contentHidden === true,
              currentContent: data.content ?? "",
            });
          }
        }
      }
      const meta = file.exists
        ? `${formatConfigBytes(file.size)}${file.mtime ? ` · ${escapeHtml(file.mtime.replace("T", " ").slice(0, 16))}` : ""}`
        : file.editable ? "不存在 · 可创建" : "不存在";
      return `<div class="config-source-row${file.exists ? "" : " is-missing"}${isOpen ? " is-open" : ""}">
        <button type="button" class="config-source-open" data-config-graph-file="${escapeHtml(file.id)}" ${file.exists || file.editable ? "" : "disabled"}>
          <svg aria-hidden="true" class="icon lucide"><use href="#lucide-file-text"></use></svg>
          <span class="config-source-label">${escapeHtml(file.label)}${file.scope === "project" ? ` <span class="config-scope-badge">项目</span>` : ""}</span>
          <code title="${escapeHtml(file.remote)}">${escapeHtml(file.projectRelative ?? file.remote)}</code>
          <span class="subtle">${meta}</span>
        </button>
        ${isOpen ? `<div class="config-source-content">${detail}</div>` : ""}
      </div>`;
    }).join("");
    return `<div class="config-source-list">${rows}</div>
      <p class="subtle">真源内容经 SFTP 读取：主机 $HOME 与项目登记目录双重围栏 + 1MB 截断 + 秘密脱敏；客户端不能提交任意路径，不存在文件不可点开。</p>`;
}

function configRemoteSeatWorkspace(host, graph) {
  const probe = state.configHostProbes.get(host.id);
  if (!probe || probe.status === "loading") {
    return skeleton({ variant: "list", rows: 3, label: "正在读取远端 CLI 席位" });
  }
  if (probe.status === "error") return `<div class="waveg-review"><strong>运行席位探测失败</strong><p class="subtle">${escapeHtml(probe.error)}</p></div>`;
  const clis = probe.data?.clis ?? [];
  const selectedId = configRemoteSelectedCli(host, graph);
  const selected = clis.find((cli) => cli.id === selectedId) ?? clis[0];
  if (!selected) return '<p class="subtle config-remote-seat-loading">探针没有返回 CLI 清单。</p>';
  const graphCli = configRemoteCliGraphId(selected.id);
  const providers = (graph.providers ?? []).filter((row) => row.cli === graphCli && row.exists);
  const sources = (graph.sources ?? []).filter((row) => row.cli === graphCli);
  const capabilities = (graph.capabilities ?? []).filter((row) => row.cli === graphCli || row.cli === selected.id);
  const mcps = (graph.mcp ?? []).filter((row) => row.cli === graphCli || row.cli === selected.id);
  const logo = cliIconMarkup(selected.id, "cli-logo") || '<svg aria-hidden="true" class="icon lucide"><use href="#lucide-square-terminal"></use></svg>';
  const sourceRows = sources.map((source) => `<div class="config-remote-seat-source${source.exists ? "" : " is-missing"}"><div><strong>${escapeHtml(source.label)}</strong><code>${escapeHtml(source.projectRelative ?? source.remote)}</code></div><span class="status-label ${source.exists ? source.scope === "project" ? "is-ok" : "is-neutral" : "is-warning"}">${source.exists ? source.scope === "project" ? "项目" : "主机" : "缺失"}</span>${source.exists || source.editable ? `<button class="icon-button" type="button" data-config-remote-provider-source="${escapeHtml(source.id)}" title="打开配置真源" aria-label="打开 ${escapeHtml(source.label)}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-scan-search"></use></svg></button>` : ""}</div>`).join("");
  const providerRows = providers.map((provider) => `<div class="config-remote-seat-provider"><span class="provider-badge is-live">live</span><div><strong>${escapeHtml(provider.baseUrl || "官方默认端点")}</strong><span>${escapeHtml(provider.model || provider.provider || "未声明模型")}</span></div></div>`).join("");
  return `<div class="runtime-seat-definition config-remote-seat-definition" aria-label="远端运行席位术语"><div><strong>运行席位</strong><span>当前远端 CLI 的命令、版本、Provider 与配置来源快照</span></div><div><strong>Adapter</strong><span>经 SSH 受控执行的 CLI 命令；此页不改变运行协议</span></div><div><strong>Provider</strong><span>从远端 live 配置脱敏提取；凭据不会进入浏览器</span></div></div>
    <div class="runtime-seat-layout config-remote-seat-layout">
      <aside class="runtime-seat-index" aria-labelledby="config-remote-seat-list-title"><header class="runtime-seat-index-header"><div><span class="eyebrow">远端 CLI 席位</span><h3 id="config-remote-seat-list-title">席位目录 <span>${clis.length}</span></h3></div></header><div class="runtime-seat-filters config-remote-seat-summary" role="status"><span>${clis.filter((cli) => cli.installed).length} 已安装</span><span>${clis.length - clis.filter((cli) => cli.installed).length} 未安装</span></div><div class="runtime-seat-list config-remote-seat-list" role="listbox" aria-label="远端 CLI 席位列表">${clis.map((cli) => { const icon = cliIconMarkup(cli.id, "runtime-seat-logo") || '<svg aria-hidden="true" class="icon lucide"><use href="#lucide-square-terminal"></use></svg>'; return `<button type="button" class="runtime-seat-item${cli.id === selected.id ? " is-active" : ""}" role="option" aria-selected="${cli.id === selected.id}" data-config-remote-cli="${escapeHtml(cli.id)}" data-brand="${escapeHtml(cli.id)}"><span class="runtime-seat-item-icon">${icon}</span><span class="runtime-seat-item-copy"><strong>${escapeHtml(cli.label)}</strong><span>${escapeHtml(cli.installed ? cli.version ?? "已安装" : cli.command)}</span></span><span class="runtime-seat-item-state${cli.installed ? " is-ready" : ""}" title="${cli.installed ? "已安装" : "未安装"}"></span></button>`; }).join("")}</div></aside>
      <section class="runtime-seat-editor config-remote-seat-editor" aria-labelledby="config-remote-seat-title"><header class="runtime-seat-editor-header"><div><span class="eyebrow">可执行档案</span><h3 id="config-remote-seat-title">${escapeHtml(selected.label)} 远端席位</h3></div><span class="status-label ${selected.installed ? "is-ok" : "is-warning"}">${selected.installed ? "已检测" : "未安装"}</span></header>
        <div class="runtime-seat-editor-body"><div class="config-remote-seat-identity"><span class="config-remote-seat-logo">${logo}</span><div><strong>${escapeHtml(selected.label)}</strong><span>${escapeHtml(selected.command)} · ${escapeHtml(selected.rawVersion ?? selected.version ?? "未安装")}</span></div>${selected.installed ? `<button class="button secondary" type="button" data-config-target-terminal="${escapeHtml(configRemoteTargetKey())}"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-square-terminal"></use></svg>SSH 终端</button>` : `<button class="button primary" type="button" data-config-install-cli="${escapeHtml(host.id)}:${escapeHtml(selected.id)}"${configRemoteRecoveryForTarget() ? ' disabled title="上一次远端提交状态不确定；核对前禁止远端安装"' : ""}><svg aria-hidden="true" class="icon lucide"><use href="#lucide-download"></use></svg>安装</button>`}</div>
          <section class="config-remote-seat-section"><p class="eyebrow">执行协议</p><h4>Adapter 与 Provider</h4><div class="config-remote-seat-facts"><div><span>执行后端</span><strong>SSH · ${escapeHtml(selected.command)}</strong></div><div><span>传输</span><strong>受控远程 CLI</strong></div><div><span>Provider 配置</span><strong>${providers.length} 个 live</strong></div><div><span>能力接入</span><strong>${capabilities.length} 项 · ${mcps.length} MCP</strong></div></div>${providerRows || '<p class="subtle">该 CLI 暂未检测到 live Provider 配置。</p>'}</section>
          <section class="config-remote-seat-section"><p class="eyebrow">配置来源</p><h4>配置来源</h4><div class="config-remote-seat-sources">${sourceRows || '<p class="subtle">该 CLI 没有登记的配置真源。</p>'}</div></section>
          <p class="runtime-seat-note">这是远端只读席位快照。安装、Provider 发布和真源保存继续分别经过既有确认与摘要锁。</p></div>
      </section>
    </div>`;
}

function configRemoteSourcesBody(host) {
  return configRemoteGraphBody(host, (graph) => {
    const mode = configRemoteRuntimeMode();
    return `${configRemoteHealthDashboard(host, graph)}<div class="runtime-workspace-tabs config-remote-runtime-tabs" role="tablist" aria-label="远端运行配置视图"><button class="${mode === "seats" ? "is-active" : ""}" type="button" role="tab" aria-selected="${mode === "seats"}" tabindex="${mode === "seats" ? "0" : "-1"}" data-config-remote-runtime-mode="seats"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-cpu"></use></svg>运行席位</button><button class="${mode === "sources" ? "is-active" : ""}" type="button" role="tab" aria-selected="${mode === "sources"}" tabindex="${mode === "sources" ? "0" : "-1"}" data-config-remote-runtime-mode="sources"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-file-json"></use></svg>高级真源</button></div>${mode === "seats" ? configRemoteSeatWorkspace(host, graph) : `<section class="config-remote-source-workspace" aria-label="远端高级真源">${configRemoteSourceList(graph)}</section>`}`;
  });
}

/** CLI 矩阵（probe 实况）：sources 面与远程环境卡共用。 */
function configRemoteEnvBody(host) {
  const probe = state.configHostProbes.get(host.id);
  if (!probe || probe.status === "loading") {
    return skeleton({ variant: "card", rows: 3, label: "正在探测远程环境（OS / Shell / CLI 矩阵）" });
  }
  if (probe.status === "error") {
    // UI-AUDIT P0-6：错误态必须给恢复路径，不能只是一行灰字
    return emptyState({
      tone: "error",
      title: "远程环境探测失败",
      desc: `主机 ${host.name ?? host.id} 返回：${probe.error}。确认 SSH 可达与 CLI 安装后重试。`,
      action: { label: "重新探测", icon: "refresh-cw", attrs: { "data-config-host-probe": String(host.id ?? "") } },
      compact: true,
    });
  }
  const data = probe.data ?? {};
  const recoveryBlocked = configRemoteWriteBlocked({ key: `host:${host.id}`, hostId: host.id, projectId: null }, { notify: false });
  return `
    <div class="sshconn-env-grid">
      <span>OS</span><b>${escapeHtml(data.os ?? "?")}</b>
      <span>Shell</span><b>${escapeHtml(data.shell ?? "?")}</b>
      <span>Home</span><b>${escapeHtml(data.home ?? "?")}</b>
      <span>磁盘</span><b>${escapeHtml(data.disk ?? "?")}</b>
      <span>内存</span><b>${escapeHtml(data.memory ?? "?")}</b>
    </div>
    <div class="sshconn-clis">
      ${(data.clis ?? []).map((cli) => `
        <div class="sshconn-cli${cli.installed ? "" : " is-missing"}">
          <span class="sshconn-cli-name">${escapeHtml(cli.label)}</span>
          <code>${escapeHtml(cli.command)}</code>
          ${cli.installed
            ? `<span class="sshconn-cli-ver" title="${escapeHtml(cli.rawVersion ?? "")}">${escapeHtml(cli.version ?? "已安装")}</span>`
            : `<span class="subtle">未安装</span>
               <button type="button" class="button mini" data-config-install-cli="${escapeHtml(host.id)}:${escapeHtml(cli.id)}"${recoveryBlocked ? ' disabled title="存在未核对远端事务，暂不可安装"' : ""}>安装</button>`}
        </div>`).join("")}
    </div>`;
}

/** 远程图谱拉取：主机/项目都按 targetKey 隔离缓存，项目端点由服务端台账解析 path。 */
async function loadConfigHostGraph(hostId, { force = false } = {}) {
  const target = configRemoteProviderTargetSnapshot();
  const targetKey = target.key;
  if (!force && state.configHostGraph.has(targetKey)) return;
  const loading = { status: "loading" };
  state.configHostGraph.set(targetKey, loading);
  renderConfigTopology();
  if (state.configHostId === hostId && configRemoteTargetKey() === targetKey) renderConfigRemotePanel();
  try {
    const result = await request(configRemoteGraphEndpoint({ target }));
    if (state.configHostGraph.get(targetKey) !== loading) return;
    state.configHostGraph.set(targetKey, { status: "ok", data: result ?? null });
    if (force) {
      // 图谱读回仅证明 UI 已刷新，不等于未知事务已和解；保留阻断直到服务端 reconcile 明确确认。
      for (const [, recovery] of configRemoteRecoveryEntriesForTarget(target)) recovery.readbackAt = Date.now();
    }
  } catch (error) {
    if (state.configHostGraph.get(targetKey) !== loading) return;
    state.configHostGraph.set(targetKey, { status: "error", error: error.message });
  }
  renderConfigTopology();
  if (state.configHostId === hostId && configRemoteTargetKey() === targetKey) renderConfigRemotePanel();
}

/** 真源文件点击展开/收起；内容按 targetKey:fileId 缓存，再点同一行收起。 */
async function toggleConfigGraphFile(fileId) {
  const target = configRemoteProviderTargetSnapshot();
  const targetKey = target.key;
  const open = state.configHostSourceOpen;
  if (open?.targetKey === targetKey && open?.fileId === fileId) {
    state.configHostSourceOpen = null;
    renderConfigRemotePanel();
    return;
  }
  state.configHostSourceOpen = { targetKey, fileId };
  const key = `${targetKey}:${fileId}`;
  if (!state.configHostSourceCache.has(key)) {
    const loading = { status: "loading" };
    state.configHostSourceCache.set(key, loading);
    renderConfigRemotePanel();
    try {
      const result = await request(configRemoteGraphEndpoint({ sourceFile: fileId, target }));
      if (state.configHostSourceCache.get(key) !== loading) return;
      state.configHostSourceCache.set(key, { status: "ok", data: result ?? null });
      state.configHostSourceDrafts.set(key, { content: result?.content ?? "", digest: result?.digest ?? null, dirty: false });
    } catch (error) {
      if (state.configHostSourceCache.get(key) !== loading) return;
      state.configHostSourceCache.set(key, { status: "error", error: error.message });
    }
  }
  renderConfigRemotePanel();
}

async function reloadConfigRemoteSource(fileId) {
  const target = configRemoteProviderTargetSnapshot();
  const targetKey = target.key;
  const key = `${targetKey}:${fileId}`;
  if (state.configRemoteBusy.has(`${targetKey}:source:${fileId}`)) return;
  const draft = state.configHostSourceDrafts.get(key);
  if (draft?.dirty) {
    const proceed = await confirmAction({
      eyebrow: "重新载入远端真源",
      title: "放弃未保存修改？",
      rows: [["文件", fileId]],
      warning: "当前编辑器中的未保存内容会被远端最新版本替换。",
      confirmLabel: "放弃并载入",
      danger: true,
    });
    if (!proceed) return;
  }
  const loading = { status: "loading" };
  state.configHostSourceCache.set(key, loading);
  state.configHostSourceDrafts.delete(key);
  if (targetKey === configRemoteTargetKey()) renderConfigRemotePanel();
  try {
    const result = await request(configRemoteGraphEndpoint({ sourceFile: fileId, target }));
    if (state.configHostSourceCache.get(key) !== loading) return;
    state.configHostSourceCache.set(key, { status: "ok", data: result ?? null });
    state.configHostSourceDrafts.set(key, { content: result?.content ?? "", digest: result?.digest ?? null, dirty: false });
  } catch (error) {
    if (state.configHostSourceCache.get(key) !== loading) return;
    state.configHostSourceCache.set(key, { status: "error", error: error.message });
  }
  if (targetKey === configRemoteTargetKey()) renderConfigRemotePanel();
}

async function saveConfigRemoteSource(fileId) {
  const target = configRemoteProviderTargetSnapshot();
  const key = `${target.key}:${fileId}`;
  const cache = state.configHostSourceCache.get(key);
  const data = cache?.status === "ok" ? cache.data : null;
  const draft = state.configHostSourceDrafts.get(key);
  if (!data?.editable || !draft?.dirty) return;
  if (configRemoteWriteBlocked(target)) return;
  const proceed = await confirmAction({
    eyebrow: data.exists ? "保存远端真源" : "创建远端真源",
    title: `${data.exists ? "保存" : "创建"}「${data.label ?? fileId}」？`,
    rows: [
      ["远端路径", data.remote],
      ["并发保护", data.exists ? `SHA-256 ${String(draft.digest).slice(0, 12)}…` : "目标必须仍不存在"],
      ["发布", "同目录备份、0600 临时文件、digest 复核、原子替换"],
    ],
    warning: "若远端文件已被其他进程修改，保存会以 409 拒绝，不覆盖外部改动。",
    confirmLabel: data.exists ? "保存" : "创建",
  });
  if (!proceed) return;
  const submittedDraft = state.configHostSourceDrafts.get(key);
  const submittedCache = state.configHostSourceCache.get(key);
  const submittedData = submittedCache?.status === "ok" ? submittedCache.data : null;
  if (!submittedData?.editable || !submittedDraft?.dirty) return;
  if (configRemoteWriteBlocked(target)) return;
  const busyKey = `${target.key}:source:${fileId}`;
  if (state.configRemoteBusy.has(busyKey)) return;
  state.configRemoteBusy.add(busyKey);
  renderConfigRemotePanel();
  const endpoint = target.projectId
    ? `/api/remote-projects/${encodeURIComponent(target.projectId)}/graph/source`
    : `/api/ssh/hosts/${encodeURIComponent(target.hostId)}/graph/source`;
  try {
    const result = await request(endpoint, { method: "POST", body: { file: fileId, content: submittedDraft.content, digest: submittedDraft.digest } });
    configRemoteResult(`<div class="waveg-review"><strong>远端真源已${result.created ? "创建" : "保存"}</strong><div class="waveg-log">${escapeHtml(`${result.remote}\n${result.bytes}B${result.backup ? `\n备份 ${result.backup}` : ""}`)}</div></div>`, target.key);
    const latestDraft = state.configHostSourceDrafts.get(key);
    const nextData = {
      ...submittedData,
      ...result,
      exists: true,
      content: submittedDraft.content,
      digest: result.digest,
      editable: true,
    };
    state.configHostSourceCache.set(key, { status: "ok", data: nextData });
    state.configHostSourceDrafts.set(key, latestDraft === submittedDraft
      ? { content: submittedDraft.content, digest: result.digest, dirty: false }
      : { content: latestDraft?.content ?? submittedDraft.content, digest: result.digest, dirty: (latestDraft?.content ?? submittedDraft.content) !== submittedDraft.content });
    if (target.key === configRemoteTargetKey()) {
      await loadConfigHostGraph(target.hostId, { force: true });
    }
  } catch (error) {
    rememberConfigRemoteRecovery(target, error, error.message, "graph");
    configRemoteResult(`<div class="waveg-review"><strong>远端真源保存失败</strong><p class="subtle">${escapeHtml(error.message)}</p></div>`, target.key);
    toast(`远端真源保存失败：${error.message}`, "error", 7000);
  } finally {
    state.configRemoteBusy.delete(busyKey);
    if (target.key === configRemoteTargetKey()) renderConfigRemotePanel();
  }
}

function toggleConfigRemoteSourceDiff(fileId) {
  const key = `${configRemoteTargetKey()}:${fileId}`;
  if (state.configRemoteSourceDiffs.has(key)) state.configRemoteSourceDiffs.delete(key);
  else state.configRemoteSourceDiffs.add(key);
  renderConfigRemotePanel();
}

/** 备份对比：读服务端脱敏投影；慢响应只写回自己的缓存键，切目标后不覆盖当前面板。 */
async function toggleConfigRemoteBackupCompare(fileId, name) {
  if (!fileId || !name) return;
  const target = configRemoteProviderTargetSnapshot();
  const targetKey = target.key;
  const compareKey = `${targetKey}:${fileId}`;
  if (state.configRemoteBackupCompare.get(compareKey) === name) {
    state.configRemoteBackupCompare.delete(compareKey);
    renderConfigRemotePanel();
    return;
  }
  state.configRemoteBackupCompare.set(compareKey, name);
  const cacheKey = `${compareKey}:${name}`;
  if (!state.configRemoteBackupCache.has(cacheKey)) {
    const loading = { status: "loading" };
    state.configRemoteBackupCache.set(cacheKey, loading);
    renderConfigRemotePanel();
    try {
      const result = await request(configRemoteGraphEndpoint({ sourceFile: fileId, backupName: name, target }));
      if (state.configRemoteBackupCache.get(cacheKey) !== loading) return;
      state.configRemoteBackupCache.set(cacheKey, { status: "ok", data: result ?? null });
    } catch (error) {
      if (state.configRemoteBackupCache.get(cacheKey) !== loading) return;
      state.configRemoteBackupCache.set(cacheKey, { status: "error", error: error.message });
    }
  }
  if (targetKey === configRemoteTargetKey()) renderConfigRemotePanel();
}

/**
 * 备份恢复：只提交备份名 + 当前真源 digest（CAS），原文由服务端从备份直接送入 writeSource。
 * 确认对话是异步窗口，期间远端 digest 可能已变——确认后必须重取并严格比对，不拿旧快照写盘。
 */
async function restoreConfigRemoteBackup(fileId, name) {
  if (!fileId || !name) return;
  const target = configRemoteProviderTargetSnapshot();
  const targetKey = target.key;
  const sourceKey = `${targetKey}:${fileId}`;
  const cache = state.configHostSourceCache.get(sourceKey);
  const data = cache?.status === "ok" ? cache.data : null;
  if (!data?.editable || !data.exists) return;
  if (configRemoteWriteBlocked(target)) return;
  const busyKey = `${targetKey}:restore:${name}`;
  if (state.configRemoteBusy.has(busyKey)) return;
  const graph = state.configHostGraph.get(targetKey);
  const entry = graph?.status === "ok"
    ? configRemoteBackupRows(graph.data ?? {}, fileId).find((row) => row.name === name)
    : null;
  const draft = state.configHostSourceDrafts.get(sourceKey);
  const proceed = await confirmAction({
    eyebrow: "从备份恢复远端真源",
    title: `用备份覆盖「${data.label ?? fileId}」？`,
    rows: [
      ["远端路径", data.remote],
      ["备份文件", name],
      ["备份时间", formatConfigBackupTime(entry?.mtime)],
      ["恢复内容", `${entry?.size == null ? "大小未知" : formatConfigBytes(entry.size)} · 原文由服务端读取，不经浏览器`],
      ["并发保护", `SHA-256 ${String(data.digest).slice(0, 12)}…`],
      ["可回滚", "恢复同样会为当前内容留下新备份"],
    ],
    warning: draft?.dirty
      ? "当前远端内容会被此备份整体替换，编辑器里的未保存草稿也会一并丢弃。远端若已被其他进程改动，恢复以 409 拒绝，不覆盖外部改动。"
      : "当前远端内容会被此备份整体替换。远端若已被其他进程改动，恢复以 409 拒绝，不覆盖外部改动。",
    confirmLabel: "恢复",
    danger: true,
  });
  if (!proceed) return;
  const confirmedCache = state.configHostSourceCache.get(sourceKey);
  const confirmedData = confirmedCache?.status === "ok" ? confirmedCache.data : null;
  if (!confirmedData?.editable || confirmedData.digest !== data.digest) {
    toast("远端真源在确认期间已变化，恢复已取消——请重新对比后再决定。", "warning", 6000);
    if (targetKey === configRemoteTargetKey()) renderConfigRemotePanel();
    return;
  }
  if (configRemoteWriteBlocked(target)) return;
  if (state.configRemoteBusy.has(busyKey)) return;
  state.configRemoteBusy.add(busyKey);
  renderConfigRemotePanel();
  const endpoint = target.projectId
    ? `/api/remote-projects/${encodeURIComponent(target.projectId)}/graph/backup/restore`
    : `/api/ssh/hosts/${encodeURIComponent(target.hostId)}/graph/backup/restore`;
  try {
    const result = await request(endpoint, { method: "POST", body: { file: fileId, name, digest: confirmedData.digest } });
    configRemoteResult(`<div class="waveg-review"><strong>远端真源已从备份恢复</strong><div class="waveg-log">${escapeHtml(`${result.remote}\n${result.bytes}B · 来自 ${result.restoredFrom ?? name}${result.backup ? `\n恢复前内容已备份为 ${result.backup}` : ""}`)}</div></div>`, targetKey);
    state.configRemoteBackupCompare.delete(sourceKey);
    state.configRemoteSourceDiffs.delete(sourceKey);
    state.configHostSourceDrafts.delete(sourceKey);
    if (targetKey === configRemoteTargetKey()) {
      // 内容已整体替换：真源重读 + 图谱强刷（备份多一份），不拿旧缓存冒充现状
      await Promise.allSettled([
        reloadConfigRemoteSource(fileId),
        loadConfigHostGraph(target.hostId, { force: true }),
      ]);
    }
  } catch (error) {
    rememberConfigRemoteRecovery(target, error, error.message, "graph");
    configRemoteResult(`<div class="waveg-review"><strong>远端备份恢复失败</strong><p class="subtle">${escapeHtml(error.message)}</p></div>`, targetKey);
    toast(`远端备份恢复失败：${error.message}`, "error", 7000);
  } finally {
    state.configRemoteBusy.delete(busyKey);
    if (targetKey === configRemoteTargetKey()) renderConfigRemotePanel();
  }
}

async function openConfigRemoteProviderSource(fileId) {
  if (!fileId || !state.configHostId) return;
  const targetKey = configRemoteTargetKey();
  setConfigSurface("sources");
  state.configRemoteRuntimeModes.set(targetKey, "sources");
  if (state.configHostSourceOpen?.targetKey === targetKey && state.configHostSourceOpen?.fileId === fileId) {
    renderConfigRemotePanel();
    return;
  }
  await toggleConfigGraphFile(fileId);
}

async function refreshConfigRemoteTarget(hostId) {
  if (!hostId) return;
  await Promise.allSettled([
    probeConfigHost(hostId),
    loadConfigHostGraph(hostId, { force: true }),
  ]);
}

async function reconcileConfigRemoteRecovery(recoveryKeyOrTarget) {
  const direct = state.configRemoteRecovery?.get(recoveryKeyOrTarget);
  const entry = direct
    ? [recoveryKeyOrTarget, direct]
    : configRemoteRecoveryEntryForTarget(recoveryKeyOrTarget);
  const recoveryKey = entry?.[0];
  const recovery = entry?.[1];
  if (!recoveryKey || !recovery?.transactionId || !["provider", "graph", "sync"].includes(recovery.kind)) {
    toast("缺少可核对的远端事务标识", "error", 6000);
    return;
  }
  const target = {
    key: recovery.targetKey,
    hostId: recovery.hostId,
    projectId: recovery.projectId ?? null,
  };
  const base = recovery.kind === "sync" || !target.projectId
    ? `/api/ssh/hosts/${encodeURIComponent(target.hostId)}`
    : `/api/remote-projects/${encodeURIComponent(target.projectId)}`;
  const busyKey = `reconcile:${recoveryKey}`;
  if (state.configRemoteBusy.has(busyKey)) return;
  state.configRemoteBusy.add(busyKey);
  if (target.hostId === configRemoteHost()?.id) renderConfigRemotePanel();
  try {
    const result = await request(`${base}/recovery/reconcile`, {
      method: "POST",
      body: { kind: recovery.kind, transactionId: recovery.transactionId },
    });
    if (state.configRemoteRecovery.get(recoveryKey) !== recovery) return;
    if (result?.recoveryRequired === false && Array.isArray(result?.released)) {
      state.configRemoteRecovery.delete(recoveryKey);
      persistConfigRemoteRecoveries();
      notifyConfigRemoteRecoveryChanged();
      configRemoteResult(`<div class="waveg-review"><strong>远端事务已核对，写入阻断解除</strong><p class="subtle">${escapeHtml(result.message ?? recovery.transactionId)}</p></div>`, target.key);
      await refreshConfigRemoteTarget(target.hostId);
      toast("远端事务已核对", "success");
    } else {
      state.configRemoteRecovery.set(recoveryKey, { ...recovery, reconcile: result, message: result?.message ?? recovery.message });
      persistConfigRemoteRecoveries();
      toast("远端事务仍未确定，继续保持写入阻断", "warning", 7000);
    }
  } catch (error) {
    if (state.configRemoteRecovery.get(recoveryKey) !== recovery) return;
    const next = configRemoteRecoveryEvidence(error, error.message, recovery.kind);
    state.configRemoteRecovery.set(recoveryKey, {
      ...recovery,
      ...(next ?? {}),
      targetKey: recovery.targetKey,
      hostId: recovery.hostId,
      projectId: recovery.projectId,
      scope: recovery.scope,
      reconcileError: error.message,
    });
    persistConfigRemoteRecoveries();
    toast(`远端事务核对失败：${error.message}`, "error", 7000);
  } finally {
    state.configRemoteBusy.delete(busyKey);
    if (target.hostId === configRemoteHost()?.id) renderConfigRemotePanel();
  }
}

async function diagnoseConfigRemoteProxy(hostId) {
  if (!hostId) return;
  const targetKey = configRemoteTargetKey();
  const loading = { status: "loading" };
  state.configRemoteProxyProbes.set(targetKey, loading);
  renderConfigRemotePanel();
  try {
    const result = await request(`/api/ssh/hosts/${encodeURIComponent(hostId)}/proxy-diagnose`, { method: "POST", body: {} });
    if (state.configRemoteProxyProbes.get(targetKey) !== loading) return;
    state.configRemoteProxyProbes.set(targetKey, { status: "ok", data: result?.diagnosis ?? {} });
  } catch (error) {
    if (state.configRemoteProxyProbes.get(targetKey) !== loading) return;
    state.configRemoteProxyProbes.set(targetKey, { status: "error", error: error.message });
  }
  if (targetKey === configRemoteTargetKey()) renderConfigRemotePanel();
}

async function probeConfigHost(id) {
  const loading = { status: "loading" };
  state.configHostProbes.set(id, loading);
  if (typeof renderConfigHostBar === "function") renderConfigHostBar();
  renderConfigTopology();
  if (state.configHostId === id) renderConfigRemotePanel();
  try {
    const result = await request(`/api/ssh/hosts/${id}/probe`, { method: "POST", body: JSON.stringify({}) });
    if (state.configHostProbes.get(id) !== loading) return;
    const data = result?.probe ?? null;
    state.configHostProbes.set(id, { status: "ok", data });
    const metrics = data?.metrics ?? {};
    const sample = {
      at: Date.now(),
      cpu: configRemoteMetricNumber(metrics.cpu?.usagePercent),
      memory: configRemoteMetricNumber(metrics.memory?.usagePercent),
      disk: configRemoteMetricNumber(metrics.disk?.usagePercent),
      rxBytes: configRemoteMetricNumber(metrics.network?.rxBytes),
      txBytes: configRemoteMetricNumber(metrics.network?.txBytes),
    };
    if ([sample.cpu, sample.memory, sample.disk, sample.rxBytes, sample.txBytes].some((value) => value != null)) {
      const history = state.configRemoteMetricHistory.get(id) ?? [];
      state.configRemoteMetricHistory.set(id, [...history, sample].slice(-24));
    }
  } catch (error) {
    if (state.configHostProbes.get(id) !== loading) return;
    state.configHostProbes.set(id, { status: "error", error: error.message });
  }
  if (typeof renderConfigHostBar === "function") renderConfigHostBar();
  renderConfigTopology();
  if (state.configHostId === id) renderConfigRemotePanel();
}

/** 远程安装 CLI：确认框明示命令通道，结果内联如实回显，成功后重探测刷新矩阵。 */
async function installConfigCli(hostId, toolId) {
  const target = configRemoteTargetSnapshotForKey();
  if (configRemoteWriteBlocked(target)) return;
  const host = (state.configHosts ?? []).find((entry) => entry.id === hostId);
  const probe = state.configHostProbes.get(hostId);
  const cli = probe?.data?.clis?.find((entry) => entry.id === toolId);
  const platform = /darwin/i.test(probe?.data?.os ?? "") ? "darwin" : "linux";
  const verdict = await confirmAction({
    eyebrow: "远程安装",
    title: `在 ${host?.name ?? hostId} 安装 ${cli?.label ?? toolId}？`,
    rows: [
      ["主机", `${host?.user ?? ""}@${host?.host ?? ""}:${host?.port ?? ""}`],
      ["CLI", `${cli?.label ?? toolId}（${cli?.command ?? toolId}）`],
      ["通道", "官方安装命令（npm i -g / 官方脚本），输出如实回显，失败不伪造成功"],
    ],
    confirmLabel: "执行安装",
  });
  if (!verdict) return; // confirmAction 无 checkbox 时 resolve 布尔
  if (configRemoteWriteBlocked(target)) return;
  configRemoteResult(`<p class="subtle">正在安装 ${escapeHtml(cli?.label ?? toolId)}（最长 120s）…</p>`, target.key);
  try {
    const result = await request(`/api/ssh/hosts/${hostId}/install-cli`, { method: "POST", body: JSON.stringify({ toolId, platform }) });
    if (result.ok) await probeConfigHost(hostId); // 先重探测——重渲面板会清结果区，回报必须在重渲之后落
    configRemoteResult(`
      <div class="waveg-review">
        <strong>${result.ok ? "安装完成" : `安装失败（退出码 ${result.code ?? "?"}）`}：${escapeHtml(result.display ?? "")}</strong>
        <div class="waveg-log">${escapeHtml(result.stdout || "")}${result.stderr ? `\n[stderr]\n${escapeHtml(result.stderr)}` : ""}</div>
        </div>`, target.key);
  } catch (error) {
    configRemoteResult(`<div class="waveg-review"><strong>安装失败</strong><p class="subtle">${escapeHtml(error.message)}</p></div>`, target.key);
  }
}

/** 在该主机 home 目录开 SSH 终端（复用 pty ssh 面，与项目右键终端同链路）。 */
async function openConfigTargetTerminal(hostId) {
  const host = configRemoteHost() ?? (state.configHosts ?? []).find((entry) => entry.id === hostId);
  const project = configRemoteProject();
  const path = project?.path ?? state.configHostProbes.get(hostId)?.data?.home ?? "/";
  try {
    const result = await request("/api/pty", {
      method: "POST",
      body: JSON.stringify({ ssh: { hostId, path }, title: `${project?.name ?? host?.name ?? hostId} · ${path}` }),
    });
    window.dispatchEvent(new CustomEvent("forge:pty-session-created", { detail: { session: result?.session } }));
    openBottomTerminal();
    toast(`已打开「${project?.name ?? host?.name ?? hostId}」的远程终端`, "success");
  } catch (error) {
    toast(`打开远程终端失败:${error.message}`, "error");
  }
}

/** 沉浸 CLI 罩层若开着则收起；返回是否确实收了一个。切会话/新建任务/快捷键收回共用。 */
function closeCliImmersiveIfOpen() {
  if (!document.getElementById("cli-immersive")) return false;
  window.dispatchEvent(new CustomEvent("forge:cli-immersive-close"));
  return true;
}

/** 一键跳到当前会话的原生 CLI 界面：交互式 resume（claude -r / codex resume…），
 *  与控制台共享同一原生会话文件——终端里说的话，控制台续聊时 CLI 记得；反之亦然。
 *  LO 2026-08-17：对话主列整体罩层变终端（沉浸接续），Esc/× 返回对话；罩层头部有成员
 *  页签条，团队多名成员各有原生会话时可切换/懒启动。罩层宿主不在当前视图时先切回协作台
 *  再开——不回底部抽屉（抽屉只放项目路径下的纯 shell，CLI 会话不进）。 */
async function openRunCliTerminal() {
  // 沉浸罩层已开时再次触发（Ctrl+Alt+O）= 收回罩层，开关语义成对
  if (closeCliImmersiveIfOpen()) return;
  const run = selectedRun();
  if (!run) {
    toast("先选中一个会话，再跳 CLI 终端", "warning", 2400);
    return;
  }
  try {
    const target = activeComposerTarget();
    // 成员优先级：composer 当前目标 → 这条会话上次在罩层里看的成员（dedupe 接回时恢复焦点）
    let rememberedAgent = null;
    try { rememberedAgent = sessionStorage.getItem(`514cc:cli-active:${run.id}`); } catch { /* storage 可能被禁 */ }
    const result = await request(`/api/runs/${encodeURIComponent(run.id)}/cli-terminal`, {
      method: "POST",
      body: JSON.stringify({ agentId: target.memberId || rememberedAgent || undefined }),
    });
    // 成员条数据：服务端给全部可接续成员，这里补上展示名（teamCatalog 标签）
    const members = (Array.isArray(result?.members) ? result.members : [])
      .map((member) => ({ ...member, label: agentLabel(member.agentId) }));
    const detail = {
      session: result?.session,
      title: `${run.title || "当前会话"} · 原生 CLI 接续`,
      members,
      runId: run.id,
      activeAgentId: result?.spec?.agentId || null,
    };
    window.dispatchEvent(new CustomEvent("forge:cli-immersive-open", { detail }));
    // 罩层宿主（conversation-pane）不在当前视图 → 切回协作台再开一次；仍不行如实报错
    if (!document.getElementById("cli-immersive")) {
      document.querySelector('.settings-rail-back[data-view="workbench"], [data-view="workbench"]')?.click?.();
      await new Promise((resolve) => { setTimeout(resolve, 400); });
      window.dispatchEvent(new CustomEvent("forge:cli-immersive-open", { detail }));
    }
    if (!document.getElementById("cli-immersive")) {
      toast("打开 CLI 终端失败：当前视图没有会话面板，请切到协作台会话页再试", "error", 4200);
      return;
    }
    if (result?.busy) {
      toast("该会话有轮次在途：终端里继续可能与控制台轮次交错，建议先等本轮结束或点停止", "warning", 5200);
    } else {
      const extra = members.length > 1 ? `；罩层可切换 ${members.length} 名成员` : "";
      const verb = result?.session?.reused === true ? "接回仍在运行的" : "用原生会话打开";
      toast(`已${verb} ${agentLabel(result?.spec?.agentId) || "CLI"} 终端（${result?.spec?.command || ""}）${extra}`, "success", 3200);
    }
  } catch (error) {
    toast(`打开 CLI 终端失败：${error.message}`, "error", 4200);
  }
}

/** 一键同步本机配置：plan 列清单（含 secret 红字警示）→ 显式勾选确认 → 逐文件推送回报。 */
async function openConfigSyncDialog(host) {
  const openedTarget = configRemoteProviderTargetSnapshot();
  if (!openedTarget.hostId || openedTarget.hostId !== host.id || configRemoteWriteBlocked(openedTarget)) return;
  const project = configRemoteProject();
  const targetLabel = project
    ? `${host.name ?? host.id} 的主机 Home（当前项目：${project.name ?? project.id}）`
    : host.name ?? host.id;
  const dialog = document.createElement("dialog");
  dialog.className = "action-dialog sshconn-dialog";
  dialog.innerHTML = `<div class="dialog-heading"><div><span class="eyebrow">同步到主机 Home</span><h2>同步到 ${escapeHtml(targetLabel)}</h2></div></div><div class="dialog-body">${skeleton({ variant: "list", rows: 5, label: "正在读取本机配置清单" })}</div>`;
  document.body.appendChild(dialog);
  dialog.addEventListener("close", () => dialog.remove(), { once: true }); // 一次性 dialog，关即销毁
  dialog.showModal();
  let plan;
  try {
    plan = await request(`/api/ssh/hosts/${host.id}/env-sync/plan`);
  } catch (error) {
    dialog.querySelector(".dialog-body").innerHTML = `<p class="subtle">读取失败：${escapeHtml(error.message)}</p><div class="dialog-actions"><button type="button" class="button secondary" data-act="cancel">关闭</button></div>`;
    dialog.querySelector('[data-act="cancel"]')?.addEventListener("click", () => dialog.close());
    return;
  }
  const files = plan?.files ?? [];
  dialog.innerHTML = `
    <div class="dialog-heading">
      <div><span class="eyebrow">同步到主机 Home</span><h2>同步到 ${escapeHtml(targetLabel)}</h2></div>
      <button type="button" class="icon-button" data-act="cancel" aria-label="关闭对话框" title="关闭"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-x"></use></svg></button>
    </div>
    <div class="dialog-body">
      <p class="subtle">推送本机运行时实况文件到远端用户主目录同名路径（整文件覆盖远端同名文件）。${project ? `当前项目目录 <code>${escapeHtml(project.path)}</code> 不会被写入。` : ""}凭据文件（auth.json / .env）永不在清单内。</p>
      <div class="sshconn-sync-list">
        ${files.map((file) => `
          <label class="sshconn-sync-row${file.exists ? "" : " is-missing"}">
            <input type="checkbox" data-sync-file="${escapeHtml(file.id)}" ${file.exists && !file.containsSecrets ? "checked" : ""} ${file.exists ? "" : "disabled"} />
            <span class="sshconn-sync-main">
              <span>${escapeHtml(file.label)}${file.containsSecrets ? ` <span class="sshconn-badge is-warn">检测到疑似秘密</span>` : ""}</span>
              <span class="subtle">${escapeHtml(file.local)} → ~/${escapeHtml(file.remote)}${file.exists ? ` · ${file.size}B` : " · 本机不存在"}</span>
            </span>
          </label>`).join("")}
      </div>
      <p class="subtle" data-sync-msg></p>
    </div>
    <div class="dialog-actions">
      <button type="button" class="button secondary" data-act="cancel">取消</button>
      <button type="button" class="button primary" data-act="push"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-cloud-upload"></use></svg> 推送所选</button>
    </div>`;
  dialog.querySelectorAll('[data-act="cancel"]').forEach((button) => button.addEventListener("click", () => dialog.close()));
  dialog.querySelector('[data-act="push"]')?.addEventListener("click", async () => {
    const pushButton = dialog.querySelector('[data-act="push"]');
    if (pushButton?.disabled) return;
    const selectedIds = [...dialog.querySelectorAll("[data-sync-file]:checked")].map((box) => box.dataset.syncFile);
    const msg = dialog.querySelector("[data-sync-msg]");
    if (!selectedIds.length) {
      if (msg) msg.textContent = "未选择任何文件。";
      return;
    }
    const secretPicks = selectedIds.filter((id) => files.find((file) => file.id === id)?.containsSecrets);
    if (secretPicks.length) {
      const verdict = await confirmAction({
        eyebrow: "二次确认",
        title: "所选文件含疑似秘密",
        rows: [["文件", secretPicks.map((id) => files.find((file) => file.id === id)?.label ?? id).join("、")]],
        warning: "含疑似秘密字面量，将经 SSH 出本机写入远端。确认继续？",
        confirmLabel: "仍要推送",
        danger: true,
      });
      if (!verdict) return; // confirmAction 无 checkbox 时 resolve 布尔
    }
    if (configRemoteWriteBlocked(openedTarget)) {
      if (msg) msg.textContent = "该主机出现未和解事务，本次同步已阻止。";
      return;
    }
    if (pushButton) pushButton.disabled = true;
    if (msg) msg.textContent = "正在推送…";
    try {
      const selections = selectedIds.map((id) => {
        const file = files.find((entry) => entry.id === id);
        return { id, digest: file?.digest, allowSecrets: secretPicks.includes(id) };
      });
      const result = await request(`/api/ssh/hosts/${openedTarget.hostId}/env-sync`, { method: "POST", body: { files: selections } });
      const entries = result?.results ?? [];
      const recovery = rememberConfigRemoteRecovery(openedTarget, result, result?.message, "sync");
      const complete = !recovery && result?.complete === true && entries.every((entry) => entry.ok);
      const title = recovery
        ? "同步状态不确定，远端写入已阻断，请核对事务"
        : complete
          ? `同步完成（远端 HOME=${result?.home ?? "?"}）`
          : result?.status === "rolled_back"
            ? "同步未完成，远端改动已回滚"
            : "同步部分失败";
      dialog.close();
      configRemoteResult(`
        <div class="waveg-review${recovery ? " is-error" : ""}">
          <strong>${escapeHtml(title)}</strong>
          <div class="waveg-log">${escapeHtml(entries.map((entry) => `${entry.ok ? "已写入" : "失败"} ${entry.label} → ${entry.remote}${entry.ok ? `（${entry.bytes}B）` : `：${entry.error}`}`).join("\n"))}</div>
        </div>`, openedTarget.key);
      if (!complete) toast(title, "error", 7000);
    } catch (error) {
      const recovery = rememberConfigRemoteRecovery(openedTarget, error, error.message, "sync");
      if (error?.payload?.code === "REMOTE_RECOVERY_BLOCKED" || error?.payload?.pending || error?.payload?.error?.pending) {
        await loadConfigRemoteRecoveries();
      }
      if (recovery) {
        dialog.close();
        configRemoteResult(`<div class="waveg-review is-error"><strong>同步状态不确定，远端写入已阻断</strong><p class="subtle">${escapeHtml(error.message)}</p></div>`, openedTarget.key);
      } else if (msg) {
        msg.textContent = `推送失败：${error.message}`;
      }
    } finally {
      if (pushButton?.isConnected) pushButton.disabled = false;
    }
  });
}

// latest-wins 门闩：重入刷新（刷新按钮/视图往返）时，先发慢响应不得覆盖后发快响应
let observabilityLoadGeneration = 0;
async function loadObservability() {
  const generation = ++observabilityLoadGeneration;
  state.obsLoaded = true;
  try {
    const [summary, routeGate, delta, handoffs, ops, worktrees] = await Promise.all([
      request(API.obsSummary),
      request(API.obsRouteGate),
      request(API.obsDelta),
      request(API.obsHandoffs),
      request(API.obsOps),
      request(API.worktrees).catch(() => null), // W3.10 台账读取失败不拖垮其余观测面
    ]);
    if (generation !== observabilityLoadGeneration) return;
    state.obsSummary = summary;
    state.obsRouteGate = routeGate;
    state.obsDelta = delta;
    state.obsHandoffs = handoffs.handoffs ?? [];
    state.obsOps = ops;
    state.obsWorktrees = worktrees ?? null;
  } catch (error) {
    if (generation !== observabilityLoadGeneration) return;
    state.obsLoaded = false;
    const failRow = (cols) => `<tr><td colspan="${cols}" class="subtle">加载失败：${escapeHtml(error.message)} — 点击「刷新数据」重试</td></tr>`;
    elements["obs-routegate-body"].innerHTML = failRow(4);
    elements["obs-delta-body"].innerHTML = failRow(3);
    elements["obs-handoff-body"].innerHTML = failRow(4);
    if (elements["obs-ops-body"]) elements["obs-ops-body"].innerHTML = failRow(3);
    toast(`体系观测数据加载失败：${error.message}`, "error");
    return; // 失败行不进 renderObservability——handoff 表会被空 state 无条件重绘成"暂无"，失败态要留住
  }
  renderObservability();
}

async function runDriftCheck() {
  const button = elements["obs-drift-button"];
  const status = elements["obs-drift-status"];
  // UI-AUDIT P1-6：忙态（含防连点）交给 runAsyncAction；状态文字仍由本函数负责
  try {
    await runAsyncAction(button, async () => {
      status.textContent = "检查中…";
      state.obsDrift = await request(API.obsDrift, { method: "POST" });
    }, { busyLabel: "检查中…" });
  } catch (error) {
    state.obsDrift = null;
    status.textContent = "检查失败";
    // UI-AUDIT P0-6：错误行改走行内空提示单一出口（自带转义）
    elements["obs-drift-body"].innerHTML = `<tr><td colspan="2">${inlineEmpty(`检查失败：${error.message}`)}</td></tr>`;
    toast(`漂移检查失败：${error.message}`, "error");
  }
  renderObservability();
}

function formatOpsUnknown(value, suffix = "") {
  if (value == null || (typeof value === "number" && !Number.isFinite(value))) return "未知";
  return `${value}${suffix}`;
}

function formatOpsRate(rate) {
  if (rate == null || !Number.isFinite(rate)) return "未知";
  return `${Math.round(rate * 100)}%`;
}

function formatOpsUsd(value) {
  if (value == null || !Number.isFinite(value)) return "未知";
  return `$${value.toFixed(4)}`;
}

// 指标大字位统一入口（PM 走查修复）：数值/短符号保留 display 级 serif，
// 文本值（未知/无日志/比率串）自动降级 metric-word（text-2xl）——否则
// 「未知 / 未知 / 未知」在卡片里三行换行挤爆版面（2026-08-30 走查实拍）。
function setMetricValue(id, value) {
  const node = elements[id];
  if (!node) return;
  node.textContent = value;
  const shortNumeric = /^[-—\d./% ]*$/.test(String(value).trim()) && String(value).trim().length <= 8;
  node.classList.toggle("metric-word", !shortNumeric);
}

function renderOpsMetrics(ops) {
  if (!ops || !elements["obs-ops-body"]) return;
  const first = ops.firstUsefulResponse || {};
  const outcomes = ops.outcomes || {};
  const cost = ops.costUsd || {};
  const stale = ops.stale || {};
  const approval = ops.approvalWait || {};
  const fallback = ops.routeFallback || {};
  const evidence = ops.evidence || {};
  const transport = ops.promptTransport || {};
  setMetricValue("obs-ops-first", formatOpsUnknown(first.p50Ms, " ms"));
  elements["obs-ops-first-detail"].textContent = first.samples
    ? `${first.samples} 个样本 · ${first.unknown || 0} 个未知时钟`
    : "无样本时不填 0";
  setMetricValue("obs-ops-outcomes", [
    formatOpsRate(outcomes.successRate),
    formatOpsRate(outcomes.failureRate),
    formatOpsRate(outcomes.recoveryRate),
  ].join(" / "));
  elements["obs-ops-outcomes-detail"].textContent = outcomes.total
    ? `成功 ${outcomes.succeeded || 0} · 失败 ${outcomes.failed || 0} · 恢复 ${outcomes.recoveryRequired || 0}`
    : "空窗口比率保持未知";
  setMetricValue("obs-ops-cost", cost.receiptTurns
    ? `${cost.known || 0}/${cost.receiptTurns} 已知`
    : "未知");
  const knownMean = formatOpsUsd(cost.knownMeanUsd);
  elements["obs-ops-cost-detail"].textContent = cost.unknown
    ? `${cost.unknown} 次回执无成本，不计入均值（已知均值 ${knownMean}）`
    : `缺失成本不当 $0 · 已知均值 ${knownMean}`;
  setMetricValue("obs-ops-stale", formatOpsUnknown(stale.total));
  elements["obs-ops-stale-detail"].textContent = stale.healthCacheStale
    ? `健康缓存过期 · 在途 stale ${stale.staleRunCount || 0}`
    : `健康缓存有效 · 在途 stale ${stale.staleRunCount || 0}`;
  const rows = [
    ["首个有效响应 p50", formatOpsUnknown(first.p50Ms, " ms"), `${first.samples || 0} 样本 / ${first.unknown || 0} 未知`],
    ["成功 / 失败 / 恢复率", `${formatOpsRate(outcomes.successRate)} / ${formatOpsRate(outcomes.failureRate)} / ${formatOpsRate(outcomes.recoveryRate)}`, "无结局样本时为未知"],
    ["审批等待 p50", formatOpsUnknown(approval.p50Ms, " ms"), `仅 pending 队列可观测 · ${approval.pending || 0} 条`],
    ["stale 合计", formatOpsUnknown(stale.total), `健康 ${stale.staleHealthItemCount || 0} + run ${stale.staleRunCount || 0}`],
    ["route fallback", formatOpsUnknown(fallback.events), `路由 ${fallback.runs || 0} + adapter ${fallback.adapterEvents || 0}`],
    ["证据完整率", formatOpsRate(evidence.rate), `${evidence.complete || 0}/${evidence.terminal || 0} 终态执行`],
    ["costUsd 可用率", formatOpsRate(cost.availability), `已知均值 ${knownMean}，未知 ${cost.unknown || 0}`],
    ["中文传输失败", formatOpsUnknown(transport.failures), `UNSAFE ${transport.codes?.PROMPT_TRANSPORT_UNSAFE || 0} · CORRUPT ${transport.codes?.PROMPT_TRANSPORT_CORRUPT || 0}`],
  ];
  elements["obs-ops-body"].innerHTML = rows.map(([name, value, note]) => `<tr>
    <td>${escapeHtml(name)}</td>
    <td class="mono">${escapeHtml(value)}</td>
    <td class="subtle">${escapeHtml(note)}</td>
  </tr>`).join("");
}

function renderObservability() {
  const gate = state.obsRouteGate;
  if (gate) {
    setMetricValue("obs-routegate-count", gate.available ? String(gate.total) : "无日志");
    elements["obs-routegate-detail"].textContent = gate.available
      ? `${gate.red} RED / ${gate.gray} gray`
      : "route-gate.log 不存在";
    elements["obs-routegate-body"].innerHTML = (gate.recent ?? [])
      .map(
        (row) => `<tr>
          <td class="mono">${escapeHtml(row.ts)}</td>
          <td><span class="status-label ${row.flag === "red" ? "is-error" : "is-neutral"}">${row.flag === "red" ? "RED" : "gray"}</span></td>
          <td class="mono">${escapeHtml(row.reason)}</td>
          <td>${escapeHtml(row.prompt)}</td>
        </tr>`,
      )
      .join("") || `<tr><td colspan="4">近 7 天无记录</td></tr>`;
  }
  const delta = state.obsDelta;
  if (delta) {
    setMetricValue("obs-delta-count", String(delta.total));
    elements["obs-delta-detail"].textContent = `白发 ${delta.byScore[0]} · 补强 ${delta.byScore[1]} · 推翻 ${delta.byScore[2]}`;
    elements["obs-delta-body"].innerHTML = (delta.recent ?? [])
      .map(
        (entry) => `<tr>
          <td>${escapeHtml(entry.agent)}</td>
          <td><span class="status-label ${entry.score === 2 ? "is-error" : entry.score === 1 ? "is-warning" : "is-neutral"}">${entry.score ?? "?"}</span></td>
          <td>${escapeHtml(entry.evidence)}</td>
        </tr>`,
      )
      .join("") || `<tr><td colspan="3">账本为空</td></tr>`;
  }
  const summary = state.obsSummary;
  if (summary) {
    setMetricValue("obs-fire-days",
      summary.handoffs.daysSinceLastFire === null ? "无记录" : `${summary.handoffs.daysSinceLastFire} 天`);
    elements["obs-fire-detail"].textContent = summary.handoffs.lastFire ?? "尚无外部发火 handoff";
  }
  const drift = state.obsDrift;
  if (drift) {
    // 空对账不冒充"全部一致"——0 对解析结果只可能是脚本/解析异常，如实标出
    const pairCount = (drift.pairs ?? []).length;
    setMetricValue("obs-drift-status", drift.drifted ? `${drift.drifted} 对不一致` : pairCount ? "全部一致" : "无对账数据");
    elements["obs-drift-status"].classList.toggle("is-error", drift.drifted > 0 || !pairCount);
    // 漂移 pairs 明细三态（consistent/drift/missing，与 sync-runtime 同口径），异常行置顶
    const pairs = [...(drift.pairs ?? [])].sort((a, b) => (a.status !== "consistent" ? -1 : 0) - (b.status !== "consistent" ? -1 : 0));
    elements["obs-drift-body"].innerHTML = pairs
      .map((pair) => {
        const label = pair.status === "drift" ? "漂移" : pair.status === "missing" ? "缺失" : "一致";
        const tone = pair.status === "drift" ? "is-error" : pair.status === "missing" ? "is-warning" : "is-ok";
        return `<tr>
          <td class="mono">${escapeHtml(pair.name)}</td>
          <td><span class="status-label ${tone}">${label}</span></td>
        </tr>`;
      })
      .join("") || `<tr><td colspan="2" class="subtle">漂移检查未返回配对明细。</td></tr>`;
  }
  elements["obs-handoff-body"].innerHTML = state.obsHandoffs
    .map(
      (item) => `<tr class="handoff-row" data-handoff="${escapeHtml(item.name)}" title="点击查看内容">
        <td class="mono">${escapeHtml(item.name)}</td>
        <td><span class="status-label ${item.direction === "external-fire" ? "is-warning" : "is-neutral"}">${escapeHtml(item.direction)}</span></td>
        <td>${(item.size / 1024).toFixed(1)} KB</td>
        <td class="mono">${escapeHtml(item.modifiedAt.slice(0, 16).replace("T", " "))}</td>
      </tr>`,
    )
    .join("") || `<tr><td colspan="4">暂无 handoff</td></tr>`;
  elements["obs-handoff-meta"].textContent = `${state.obsHandoffs.length} 个交接件 · 点击行查看内容`;
  renderObservabilityWorktrees();
  renderOpsMetrics(state.obsOps);
}

// W3.10 worktree 台账渲染：活跃树提供清理入口（DELETE /api/system/worktrees，fail-closed 只清台账内活跃路径）
function renderObservabilityWorktrees() {
  const body = document.getElementById("obs-worktree-body");
  const meta = document.getElementById("obs-worktree-meta");
  if (!body || !meta) return;
  const view = state.obsWorktrees;
  if (!view) {
    body.innerHTML = `<tr><td colspan="6" class="subtle">台账不可用（旧数据根或读取失败）</td></tr>`;
    meta.textContent = "台账不可用";
    return;
  }
  meta.textContent = `共 ${view.total} 条记录 · 活跃 ${view.activeCount}`;
  body.innerHTML = (view.worktrees ?? [])
    .map((item) => `<tr class="worktree-row">
      <td class="mono" title="${escapeHtml(item.path)}">${escapeHtml(item.path)}</td>
      <td>${escapeHtml(item.source ?? "–")}</td>
      <td class="mono">${escapeHtml(item.runId ? item.runId.slice(0, 8) : "–")}</td>
      <td class="mono">${escapeHtml(String(item.createdAt ?? "–").slice(0, 16).replace("T", " "))}</td>
      <td><span class="status-label ${item.removedAt ? "is-neutral" : "is-ok"}">${item.removedAt ? "已清理" : "活跃"}</span></td>
      <td>${item.removedAt ? "" : `<button class="button danger compact" type="button" data-worktree-remove="${escapeHtml(item.path)}">清理</button>`}</td>
    </tr>`)
    .join("") || `<tr><td colspan="6" class="subtle">台账为空——还没有过建树记录</td></tr>`;
}

async function removeWorktree(path) {
  try {
    await request(`${API.worktrees}?path=${encodeURIComponent(path)}`, { method: "DELETE" });
    toast("工作树已清理", "success", 2200);
  } catch (error) {
    toast(`清理失败：${error.message}`, "error");
    return;
  }
  void loadObservability();
}

async function openHandoff(name) {
  try {
    const payload = await request(`${API.obsHandoffs}/${encodeURIComponent(name)}`);
    elements["obs-handoff-content"].hidden = false;
    elements["obs-handoff-content"].textContent = payload.content;
    elements["obs-handoff-content"].scrollIntoView({ behavior: "smooth", block: "nearest" });
  } catch (error) {
    toast(`读取 handoff 失败：${error.message}`, "error");
  }
}

// latest-wins 门闩：摘要开关/重复刷新并发时，先发慢响应不得覆盖后发快响应
let sessionsLoadGeneration = 0;
async function loadSessions() {
  const generation = ++sessionsLoadGeneration;
  const withSummaries = elements["sessions-summaries-toggle"]?.checked;
  state.sessionsError = null;
  if (!state.sessionsData) renderSessions(); // 首次进视图先画加载态——扫描要数秒，不能白屏
  try {
    const payload = await request(`${API.sessions}${withSummaries ? "?summaries=1" : ""}`);
    if (generation !== sessionsLoadGeneration) return;
    state.sessionsData = payload;
  } catch (error) {
    if (generation !== sessionsLoadGeneration) return;
    state.sessionsData = null;
    state.sessionsError = error.message;
  }
  renderSessions();
}

function renderSessions() {
  const container = elements["sessions-groups"];
  const data = state.sessionsData;
  if (!data) {
    container.innerHTML = state.sessionsError
      ? `<section class="content-section">${emptyMarkup("会话扫描失败", `${state.sessionsError} — 点击右上角「重新扫描」重试`)}</section>`
      : `<section class="content-section">${emptyMarkup("正在扫描本地会话…", "Claude Code / Codex / Grok 历史，通常几秒内完成")}</section>`;
    return;
  }
  container.innerHTML = data.sources
    .map((group) => {
      const rows = (group.sessions ?? [])
        .map(
          (item) => `<tr>
            <td class="mono" title="${escapeHtml(String(item.id))}">${escapeHtml(String(item.id).slice(0, 24))}…</td>
            <td class="mono">${escapeHtml(item.scope ?? "")}</td>
            <td>${item.summary ? escapeHtml(item.summary) : '<span class="subtle">—</span>'}</td>
            <td class="mono">${escapeHtml(item.modifiedAt ? String(item.modifiedAt).slice(0, 16).replace("T", " ") : "--")}</td>
          </tr>`,
        )
        .join("");
      return `<section class="content-section">
        <div class="section-heading">
          <div>
            <h2>${escapeHtml(group.label)}</h2>
            <p>${(() => {
              // 服务端每源默认截断 25 条（上限 100），真实总数在 sessionCount——不能把截断数当全量报
              const shown = group.sessions.length;
              const total = Number(group.sessionCount);
              if (!group.available) return `不可用：${escapeHtml(group.error ?? "未知")}`;
              return Number.isFinite(total) && total > shown
                ? `最近 ${shown} / 共 ${total} 个会话`
                : `${shown} 个会话`;
            })()}</p>
          </div>
          <span class="status-label ${group.available ? "is-ok" : "is-neutral"}">${group.available ? "已扫描" : "未接入"}</span>
        </div>
        <div class="table-scroll">
          <table class="data-table">
            <thead><tr><th>会话 ID</th><th>范围</th><th>摘要</th><th>更新时间</th></tr></thead>
            <tbody>${rows || `<tr><td colspan="4">无会话</td></tr>`}</tbody>
          </table>
        </div>
      </section>`;
    })
    .join("");
}

// 配置图谱的能力面：skills 矩阵 + 花名册 + MCP 声明扫描
let capabilitiesLoadPromise = null;
let capabilitiesQueuedFreshPromise = null;
let capabilitiesFreshRequested = false;
let capabilitiesLoadEpoch = 0;

function invalidateCapabilitiesCatalog() {
  state.capabilitiesData = null;
  state.capabilitiesError = null;
  if (capabilitiesLoadPromise || capabilitiesQueuedFreshPromise) {
    return loadCapabilities({ fresh: true });
  }
  return Promise.resolve(successfulLoadResult(null, { invalidated: true }));
}

function startCapabilitiesLoad() {
  const epoch = ++capabilitiesLoadEpoch;
  state.capabilitiesLoading = true;
  let requestPromise;
  requestPromise = (async () => {
    try {
      const payload = await request(API.capabilities);
      if (epoch !== capabilitiesLoadEpoch) return successfulLoadResult(payload, { stale: true });
      state.capabilitiesData = payload;
      state.capabilitiesError = null;
      return successfulLoadResult(state.capabilitiesData);
    } catch (error) {
      if (epoch !== capabilitiesLoadEpoch) return successfulLoadResult(null, { stale: true });
      state.capabilitiesData = null;
      state.capabilitiesError = error.message;
      return failedLoadResult(error);
    } finally {
      if (epoch === capabilitiesLoadEpoch) {
        state.capabilitiesLoading = false;
        renderCapabilities();
        renderConfigTopology();
        // 团队设置已并入团队页；目录晚到时保留表单当前勾选，不回滚用户草稿。
        if (elements["team-settings-panel"]) {
          const editing = state.teams.find((team) => team.id === state.editingTeamId) ?? null;
          renderTeamChips(
            checkedChipValues("team-skills-chips", editing?.skills ?? []),
            checkedChipValues("team-mcp-chips", editing?.mcp ?? []),
            Boolean(editing?.builtin),
            editing?.members ?? [],
          );
        }
      }
    }
  })().finally(() => {
    if (capabilitiesLoadPromise === requestPromise) capabilitiesLoadPromise = null;
  });
  capabilitiesLoadPromise = requestPromise;
  return requestPromise;
}

function loadCapabilities({ fresh = false } = {}) {
  if (capabilitiesQueuedFreshPromise) {
    if (fresh) {
      capabilitiesFreshRequested = true;
      if (capabilitiesLoadPromise) capabilitiesLoadEpoch += 1;
    }
    return capabilitiesQueuedFreshPromise;
  }
  if (!capabilitiesLoadPromise) {
    capabilitiesFreshRequested = false;
    return startCapabilitiesLoad();
  }
  if (!fresh) return capabilitiesLoadPromise;

  capabilitiesFreshRequested = true;
  capabilitiesLoadEpoch += 1;
  const activeLoad = capabilitiesLoadPromise;
  let queuedPromise;
  queuedPromise = (async () => {
    try {
      let result = await activeLoad;
      while (capabilitiesFreshRequested) {
        capabilitiesFreshRequested = false;
        result = await startCapabilitiesLoad();
      }
      return result;
    } finally {
      if (capabilitiesQueuedFreshPromise === queuedPromise) capabilitiesQueuedFreshPromise = null;
    }
  })();
  capabilitiesQueuedFreshPromise = queuedPromise;
  return capabilitiesQueuedFreshPromise;
}

function mcpServerWritable(server) {
  return server?.scope === "全局" && String(server.source || "").endsWith(".claude.json");
}

function capabilityMemberMeta(id) {
  const catalog = state.bootstrap?.memberCatalog || state.memberCatalog || [];
  return catalog.find((member) => member.id === id) || { id, label: agentLabel(id) };
}

function setCapabilityWorkspace(workspace, { focus = false, recordHistory = true } = {}) {
  const previous = recordHistory ? captureViewRoute() : null;
  const next = workspace === "mcp" ? "mcp" : "skills";
  state.capabilityWorkspace = next;
  const surface = byId("config-surface-capabilities");
  if (surface) surface.dataset.capActiveWorkspace = next;
  document.querySelectorAll("#cap-workspace-tabs [data-cap-workspace]").forEach((tab) => {
    const active = tab.dataset.capWorkspace === next;
    tab.classList.toggle("is-active", active);
    tab.setAttribute("aria-selected", String(active));
    tab.tabIndex = active ? 0 : -1;
  });
  const skills = byId("cap-workspace-skills");
  const mcp = byId("cap-workspace-mcp");
  if (skills) skills.hidden = next !== "skills";
  if (mcp) mcp.hidden = next !== "mcp";
  syncSettingsRailActive(state.view, state.configSurface);
  if (state.view === "config") {
    const title = forgeViewTitle("config");
    if (elements["current-view-title"]) elements["current-view-title"].textContent = title;
    if (elements["current-view-group"]) elements["current-view-group"].textContent = forgeViewGroup("config");
    document.title = `${title} · 514 Bot`;
  }
  if (focus) byId(`cap-workspace-${next}-tab`)?.focus({ preventScroll: true });
  if (recordHistory) rememberRouteChange(previous);
}

function capabilitySourceButton(sourceId, label) {
  if (!sourceId) return "";
  return `<button class="icon-button cap-source-button" type="button" data-capability-source-id="${escapeHtml(sourceId)}" title="在真源编辑器中打开" aria-label="打开 ${escapeHtml(label)} 的相关真源"><svg aria-hidden="true" class="icon lucide"><use href="#lucide-file-text"></use></svg></button>`;
}

async function openCapabilitySource(sourceId) {
  if (!state.sources.length) {
    try {
      await loadSources();
    } catch (error) {
      toast(`真源索引读取失败：${error.message}`, "error", 6000);
      return;
    }
  }
  const source = state.sources.find((item) => item.id === sourceId) ?? null;
  if (!source) {
    toast(`未登记相关真源：${sourceId}`, "warning", 5000);
    return;
  }
  await selectSource(source.id);
  if (state.selectedSourceId !== source.id) return;
  setView("config", { configSurface: "sources", focus: false });
  runtimeSeatManager?.setMode("sources", { focus: false });
  const heading = elements["editor-title"];
  if (heading) {
    heading.setAttribute("tabindex", "-1");
    requestAnimationFrame(() => {
      heading.scrollIntoView({ block: "start", behavior: "smooth" });
      heading.focus({ preventScroll: true });
    });
  }
}

function renderCapabilities() {
  const data = state.capabilitiesData;
  if (!elements["cap-skills-body"]) return;
  setCapabilityWorkspace(state.capabilityWorkspace, { focus: false });
  if (!data) {
    const message = state.capabilitiesError ? `读取失败：${state.capabilitiesError}` : "正在扫描…";
    elements["cap-agents-grid"].innerHTML = "";
    elements["cap-skills-body"].innerHTML = `<tr><td colspan="6" class="subtle">${escapeHtml(message)}</td></tr>`;
    elements["cap-mcp-body"].innerHTML = `<p class="cap-empty">${escapeHtml(message)}</p>`;
    elements["cap-mcp-map"].innerHTML = "";
    if (elements["cap-stat-skills"]) elements["cap-stat-skills"].textContent = "—";
    if (elements["cap-stat-declared"]) elements["cap-stat-declared"].textContent = "—";
    if (elements["cap-stat-mcp"]) elements["cap-stat-mcp"].textContent = "—";
    if (elements["cap-stat-writable"]) elements["cap-stat-writable"].textContent = "—";
    if (elements["cap-stat-skills-sub"]) elements["cap-stat-skills-sub"].textContent = message;
    return;
  }
  const { skills, mcp } = data;
  if (!skills || typeof skills !== "object" || !mcp || typeof mcp !== "object" || !Array.isArray(skills.items)) {
    const message = "能力配置返回不完整，已保护性停用矩阵";
    elements["cap-agents-grid"].innerHTML = "";
    elements["cap-skills-body"].innerHTML = `<tr><td colspan="6" class="subtle">${escapeHtml(message)}</td></tr>`;
    elements["cap-mcp-body"].innerHTML = `<p class="cap-empty">${escapeHtml(message)}</p>`;
    if (elements["cap-stat-skills-sub"]) elements["cap-stat-skills-sub"].textContent = message;
    return;
  }
  const members = Array.isArray(skills.memberIds) ? skills.memberIds : [];
  const memberSet = new Set(members);
  elements["cap-agents-grid"].innerHTML = (skills.agents ?? []).length
    ? skills.agents
        .map((agent) => {
          const focusId = memberSet.has(agent.code) ? agent.code : "";
          const tag = focusId ? "button" : "div";
          const focusAttr = focusId
            ? ` type="button" data-cap-focus-member="${escapeHtml(focusId)}"`
            : "";
          return `<${tag} class="cap-agent-chip${focusId ? " is-focusable" : ""}${focusId && focusId === state.configMemberFocusId ? " is-member-focus" : ""}"${focusAttr} title="${escapeHtml(agent.skill ?? "未挂 skill")}">
            <strong>${escapeHtml(agent.name ?? agent.code)}</strong>
            <span>${escapeHtml(agent.title ?? "")}</span>
            <code>${escapeHtml(agent.code)}</code>
          </${tag}>`;
        })
        .join("")
    : '<span class="subtle">module.yaml 花名册不可用</span>';
  const registered = skills.items.filter((skill) => skill.registered).length;
  const capabilityStatus = skills.configurationStatus ?? {};
  const mcpStatus = mcp.configurationStatus ?? {};
  const capabilityDegraded = capabilityStatus.failClosed === true;
  elements["cap-skills-summary"].textContent = capabilityDegraded
    ? `能力配置已降级：${capabilityStatus.message || capabilityStatus.code || "配置不可读"}。全部 Skill 声明已停用，修复配置前禁止派发。`
    : `${skills.items.length} 个 skill（${registered} 已注册）· ${members.length} 个成员 · 勾选=向成员编排提示词声明（非工具沙箱）` +
      (skills.registryStatus === "ok" ? "" : " · 注册表不可用（仅文件系统扫描）");
  // 启停矩阵：行=skill，列=成员；checkbox 勾选=启用（负名单 disabledSkills 之外）
  const states = skills.agentSkillStates ?? {};
  const skillEnabled = (memberId, code) => !(states[memberId]?.disabledSkills ?? []).includes(code);
  const memberWritable = (memberId) => !capabilityDegraded && states[memberId]?.failClosed !== true;
  // 筛选只影响展示与批量作用域；统计始终按全集算，避免筛选后"覆盖率"读数失真
  const filter = String(state.capabilityFilter ?? "").trim().toLowerCase();
  const visible = filter
    ? skills.items.filter((skill) => `${skill.code} ${skill.description ?? ""} ${skill.path ?? ""}`.toLowerCase().includes(filter))
    : skills.items;
  const totalCells = skills.items.length * members.length;
  const declaredCells = skills.items.reduce(
    (sum, skill) => sum + members.filter((id) => skillEnabled(id, skill.code)).length,
    0,
  );
  if (elements["cap-skills-coverage"]) {
    elements["cap-skills-coverage"].textContent = totalCells
      ? `已声明 ${declaredCells}/${totalCells}`
      : "无可声明项";
    elements["cap-skills-coverage"].className = `status-label is-${totalCells && declaredCells === totalCells ? "ok" : "neutral"}`;
  }
  if (elements["cap-skills-scope"]) {
    elements["cap-skills-scope"].textContent = filter
      ? `筛选命中 ${visible.length}/${skills.items.length} 个 Skill · 批量只作用于命中项`
      : "批量作用于全部 Skill × 全部成员";
  }
  if (elements["cap-skills-model-chips"]) {
    elements["cap-skills-model-chips"].innerHTML = members.length
      ? members.map((id) => {
          const count = skills.items.filter((skill) => skillEnabled(id, skill.code)).length;
          return `<span class="cap-skill-model-chip${id === state.configMemberFocusId ? " is-member-focus" : ""}" title="${escapeHtml(id)}">${escapeHtml(agentLabel(id))} ${count}</span>`;
        }).join("")
      : "";
  }
  if (elements["cap-stat-skills"]) elements["cap-stat-skills"].textContent = String(skills.items.length);
  if (elements["cap-stat-skills-sub"]) {
    elements["cap-stat-skills-sub"].textContent = `${registered} 已注册 · ${skills.items.length - registered} 未注册`;
  }
  if (elements["cap-stat-declared"]) {
    elements["cap-stat-declared"].textContent = totalCells ? `${declaredCells}/${totalCells}` : "—";
  }
  if (elements["cap-stat-declared-sub"]) {
    elements["cap-stat-declared-sub"].textContent = capabilityDegraded ? "配置已降级，声明已停用" : `${members.length} 个成员列`;
  }
  elements["cap-skills-head"].innerHTML = `<tr><th scope="col">Skill</th>${members.map((id) => {
    const label = agentLabel(id);
    const meta = capabilityMemberMeta(id);
    const columnDeclared = visible.filter((skill) => skillEnabled(id, skill.code)).length;
    const allOn = visible.length > 0 && columnDeclared === visible.length;
    return `<th scope="col" tabindex="-1" title="${escapeHtml(id)}" aria-label="${escapeHtml(label)} Skill 配置列" data-member-column="${escapeHtml(id)}" class="${id === state.configMemberFocusId ? "is-member-focus" : ""}">
      <span class="cap-col-identity">${memberAvatarMarkup(meta, { className: "avatar-photo cap-col-avatar", iconClass: "cli-logo cap-col-icon" })}<span class="cap-col-label">${escapeHtml(label)}</span></span>
      <button type="button" class="cap-bulk-button" data-cap-column-toggle="${escapeHtml(id)}"${memberWritable(id) && visible.length ? "" : " disabled"} title="${allOn ? "取消该成员对当前列出 Skill 的全部声明" : "为该成员声明当前列出的全部 Skill"}" aria-label="${escapeHtml(label)} 整列${allOn ? "取消" : "声明"}">${columnDeclared}/${visible.length}</button>
    </th>`;
  }).join("")}</tr>`;
  elements["cap-skills-body"].innerHTML = visible.length
    ? visible
        .map(
          (skill) => {
            const rowDeclared = members.filter((id) => skillEnabled(id, skill.code)).length;
            const rowAllOn = members.length > 0 && rowDeclared === members.length;
            const desc = skill.description || skill.path || "";
            return `<tr>
            <td class="cap-skill-source">
              <div class="cap-skill-copy">
                <div class="cap-skill-title-row">
                  <strong>${escapeHtml(skill.code)}</strong>
                  <span class="cap-skill-scope">${skill.scope === "codex" ? "本地 · .agents" : "本地 · skills"}</span>
                  ${skill.version ? `<span class="cap-skill-badge" title="SKILL.md frontmatter version">v${escapeHtml(skill.version)}</span>` : ""}
                  ${skill.registered ? "" : '<span class="cap-skill-badge">未注册</span>'}
                </div>
                ${desc ? `<span class="cap-skill-desc" title="${escapeHtml(desc)}">${escapeHtml(desc)}</span>` : ""}
              </div>
              <div class="cap-skill-actions">
                ${capabilitySourceButton(skill.sourceId, skill.code)}
                <button type="button" class="cap-bulk-button" data-cap-row-toggle="${escapeHtml(skill.code)}"${capabilityDegraded ? " disabled" : ""} title="${rowAllOn ? "对所有成员取消该 Skill 声明" : "对所有成员声明该 Skill"}" aria-label="${escapeHtml(skill.code)} 整行${rowAllOn ? "取消" : "声明"}">${rowDeclared}/${members.length}</button>
              </div>
            </td>
            ${members
              .map((id) => {
                const enabled = skillEnabled(id, skill.code);
                const disabled = !memberWritable(id);
                const title = disabled
                  ? "能力配置损坏或不可读，已按 fail-closed 停用"
                  : "控制编排提示词中的 Skill 声明；真实调用仍受运行时权限约束";
                return `<td class="cap-cell${enabled ? " is-declared" : ""}${id === state.configMemberFocusId ? " is-member-focus" : ""}" data-member-column="${escapeHtml(id)}"><label class="cap-cell-toggle"><input type="checkbox" data-skill-toggle="${escapeHtml(id)}::${escapeHtml(skill.code)}"${enabled ? " checked" : ""}${disabled ? " disabled" : ""} title="${escapeHtml(title)}" aria-label="${escapeHtml(agentLabel(id))} 声明 ${escapeHtml(skill.code)}" /><span></span></label></td>`;
              })
              .join("")}
          </tr>`;
          },
        )
        .join("")
    : `<tr><td colspan="${members.length + 1}" class="subtle">${filter ? `没有匹配「${escapeHtml(filter)}」的 Skill` : "未扫描到 skill 目录"}</td></tr>`;
  const ghosts = skills.ghostRegistrations ?? [];
  elements["cap-skills-ghosts"].hidden = !ghosts.length;
  elements["cap-skills-ghosts"].textContent = ghosts.length
    ? `幽灵注册（注册表有而磁盘无）：${ghosts.map((ghost) => ghost.code).join("、")}——建议清理 module.yaml`
    : "";
  const writableCount = (mcp.servers ?? []).filter((server) => mcpServerWritable(server)).length;
  const disabledCount = (mcp.servers ?? []).filter((server) => server.disabled).length;
  const mcpFreshness = Number(mcp.claudeJsonMtimeMs) > 0
    ? ` · 配置更新于 ${new Date(Number(mcp.claudeJsonMtimeMs)).toLocaleString()}`
    : "";
  elements["cap-mcp-summary"].textContent = mcpStatus.failClosed
    ? `MCP 启停已冻结 [${mcpStatus.code || "MCP_QUARANTINE_UNAVAILABLE"}]：${mcpStatus.message || "隔离配置不可用"}${mcpStatus.causeCode ? `（${mcpStatus.causeCode}）` : ""}`
    : `${mcp.servers.length} 个声明 · ${writableCount} 个可启停 · ${mcp.sources.length} 个来源文件${mcpFreshness}`;
  if (elements["cap-stat-mcp"]) elements["cap-stat-mcp"].textContent = String(mcp.servers.length);
  if (elements["cap-stat-mcp-sub"]) {
    elements["cap-stat-mcp-sub"].textContent = mcpStatus.failClosed
      ? "启停已冻结"
      : `${mcp.sources.length} 个来源 · ${disabledCount} 已禁用`;
  }
  if (elements["cap-stat-writable"]) elements["cap-stat-writable"].textContent = String(writableCount);
  if (elements["cap-stat-writable-sub"]) {
    elements["cap-stat-writable-sub"].textContent = mcpStatus.failClosed ? "隔离配置不可用" : "仅 claude.json 全局";
  }
  const mcpQuery = String(state.capabilityMcpQuery ?? "").trim().toLowerCase();
  const mcpFilter = state.capabilityMcpFilter === "writable" || state.capabilityMcpFilter === "disabled"
    ? state.capabilityMcpFilter
    : "all";
  const visibleMcp = (mcp.servers ?? []).filter((server) => {
    if (mcpFilter === "writable" && !mcpServerWritable(server)) return false;
    if (mcpFilter === "disabled" && !server.disabled) return false;
    if (!mcpQuery) return true;
    const hay = `${server.name} ${server.transport} ${server.command ?? ""} ${server.urlHost ?? ""} ${server.scope} ${server.source}`.toLowerCase();
    return hay.includes(mcpQuery);
  });
  document.querySelectorAll("[data-mcp-filter]").forEach((button) => {
    const active = button.dataset.mcpFilter === mcpFilter;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  elements["cap-mcp-body"].innerHTML = visibleMcp.length
    ? visibleMcp.map((server) => {
        const writable = mcpServerWritable(server);
        const entry = server.command ?? server.urlHost ?? "—";
        const fileName = String(server.source || "").split(/[\\/]/).pop() || "—";
        return `<article class="cap-mcp-card${server.disabled ? " is-disabled" : ""}${writable ? " is-writable" : ""}" data-transport="${escapeHtml(server.transport || "other")}">
          <header class="cap-mcp-card-head">
            <span class="cap-mcp-transport">${escapeHtml(server.transport || "—")}</span>
            <h3>${escapeHtml(server.name)}</h3>
            <span class="status-label ${server.disabled ? "is-warning" : "is-ok"}">${server.disabled ? "已禁用" : writable ? "可启停" : "只读接入"}</span>
          </header>
          <p class="cap-mcp-entry" title="${escapeHtml(entry)}">${escapeHtml(entry)}</p>
          <footer class="cap-mcp-card-foot">
            <span class="cap-mcp-meta" title="${escapeHtml(server.source)}">${escapeHtml(server.scope)} · ${escapeHtml(fileName)}</span>
            ${capabilitySourceButton(server.sourceId, server.name)}
            ${mcpActionMarkup(server, mcp)}
          </footer>
        </article>`;
      }).join("")
    : `<p class="cap-empty">${mcp.servers.length ? `没有匹配「${escapeHtml(mcpQuery || mcpFilter)}」的 MCP` : "未扫描到 MCP 声明"}</p>`;
  elements["cap-mcp-map"].innerHTML = (mcp.capabilityMap ?? []).length
    ? `<p class="subtle">514cc 能力映射（module.yaml 策展层）：</p>` +
      `<div class="cap-map-grid">` +
      mcp.capabilityMap
        .map((entry) => `<span class="cap-map-entry"><strong>${escapeHtml(entry.capability)}</strong><span class="cap-map-servers">${escapeHtml(Array.isArray(entry.servers) ? entry.servers.join("、") : String(entry.servers))}</span></span>`)
        .join("") +
      `</div>`
    : "";
}

function focusMemberCapabilityColumn(memberId) {
  if (!memberId) return false;
  const heading = elements["cap-skills-head"]?.querySelector(`[data-member-column="${CSS.escape(memberId)}"]`);
  if (!heading) return false;
  requestAnimationFrame(() => {
    if (state.configMemberFocusId !== memberId || state.view !== "config" || state.configSurface !== "capabilities") return;
    const reduceMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches === true;
    heading.scrollIntoView({ block: "nearest", inline: "center", behavior: reduceMotion ? "auto" : "smooth" });
    heading.focus({ preventScroll: true });
  });
  return true;
}

function focusConfigSurfaceHeading(surface) {
  const heading = byId(`config-surface-${surface}`)?.querySelector("h2");
  if (!heading) return;
  heading.setAttribute("tabindex", "-1");
  requestAnimationFrame(() => {
    if (state.view === "config" && state.configSurface === surface) heading.focus({ preventScroll: true });
  });
}

async function openMemberConfigTarget({ surface, memberId, runtimeProfileId, create = false } = {}) {
  const targetEpoch = ++memberConfigTargetEpoch;
  if (surface === "capabilities") {
    setCapabilityWorkspace("skills", { focus: false });
    state.configMemberFocusId = memberId || null;
    state.configRuntimeFocusId = runtimeProfileId || null;
    setView("config", {
      configSurface: "capabilities",
      focus: false,
      preserveMemberTarget: true,
    });
    const cachedMembers = state.capabilitiesData?.skills?.memberIds ?? [];
    let loadResult = successfulLoadResult(state.capabilitiesData, { cached: true });
    if (!memberId || !cachedMembers.includes(memberId)) {
      loadResult = await loadCapabilities({ fresh: true });
    }
    if (targetEpoch !== memberConfigTargetEpoch) return;
    renderCapabilities();
    if (loadResultFailed(loadResult)) {
      focusConfigSurfaceHeading("capabilities");
      toast(`Skill / MCP 读取失败：${loadResult.error?.message || "未知错误"}`, "error", 6000);
      return;
    }
    if (!focusMemberCapabilityColumn(memberId)) {
      focusConfigSurfaceHeading("capabilities");
      toast("该成员尚未进入 Skill 配置目录", "warning");
    }
    return;
  }

  if (!runtimeProfileId && !create) {
    toast("当前成员尚未绑定运行席位", "warning");
    return;
  }
  state.configMemberFocusId = memberId || null;
  state.configRuntimeFocusId = runtimeProfileId || null;
  setView("config", {
    configSurface: "sources",
    focus: false,
    preserveMemberTarget: true,
  });
  try {
    if (!runtimeSeatManager) throw new Error("运行席位管理器尚未初始化");
    runtimeSeatManager.setMode("seats", { focus: false });
    if (create) await runtimeSeatManager.create();
    else {
      await runtimeSeatManager.load();
      const found = await runtimeSeatManager.focus(runtimeProfileId);
      if (!found) toast(`运行席位目录中未找到 ${runtimeProfileId}`, "warning");
    }
    if (targetEpoch !== memberConfigTargetEpoch) return;
  } catch (error) {
    if (targetEpoch !== memberConfigTargetEpoch) return;
    focusConfigSurfaceHeading("sources");
    toast(`运行席位读取失败：${error.message}`, "error");
  }
}

// MCP 行操作：编辑跳到本机投影表单；claude.json 全局 server 可隔离启停（禁用=移隔离区可恢复）
function mcpActionMarkup(server, mcp) {
  const edit = `<button class="text-button" type="button" data-mcp-edit="${escapeHtml(server.name)}">编辑</button>`;
  const writable = mcpServerWritable(server);
  if (!writable) return `${edit}<span class="subtle">只读启停</span>`;
  const action = server.disabled ? "enable" : "disable";
  const label = server.disabled ? "恢复" : "禁用";
  const degraded = mcp.configurationStatus?.failClosed === true;
  const title = degraded ? `MCP 启停已冻结：${mcp.configurationStatus.message || mcp.configurationStatus.code || "隔离配置不可用"}` : "";
  return `${edit}<button class="text-button" type="button" data-mcp-toggle="${escapeHtml(server.name)}::${action}" data-mcp-source="${escapeHtml(server.source)}" data-mcp-mtime="${Number(mcp.claudeJsonMtimeMs) || ""}"${degraded ? ` disabled aria-describedby="cap-mcp-summary" title="${escapeHtml(title)}"` : ""}>${label}</button>`;
}

async function toggleMcp(button) {
  const mcpStatus = state.capabilitiesData?.mcp?.configurationStatus ?? {};
  if (mcpStatus.failClosed) {
    button.disabled = true;
    toast(`MCP 启停已冻结：${mcpStatus.message || mcpStatus.code || "隔离配置不可用"}`, "error", 6000);
    return;
  }
  const [name, action] = String(button.dataset.mcpToggle).split("::");
  if (action === "disable") {
    const verdict = await confirmAction({
      eyebrow: "MCP 启停",
      title: `禁用「${name}」？`,
      rows: [
        ["方式", "移入控制面隔离区（可从本页一键恢复，不是删除）"],
        ["影响", "禁用后 Claude Code 新会话不再加载该 server"],
      ],
      warning: "若 Claude Code 正在运行，它可能并发回写 .claude.json 覆盖本次修改——建议关闭 Claude Code 后操作。",
      confirmLabel: "禁用",
    });
    if (!verdict) return;
  }
  // UI-AUDIT P1-6：忙态统一交给 runAsyncAction——防连点重复提交、失败必恢复
  // （原写法把 disabled=false 放在 catch 之后而非 finally，异常路径会留下卡死按钮，
  //  且会覆盖"因 failClosed 本就该保持禁用"的初始状态）。
  try {
    await runAsyncAction(button, async () => {
      await request("/api/capabilities/mcp/toggle", {
        method: "POST",
        body: { name, source: button.dataset.mcpSource, action, knownMtimeMs: button.dataset.mcpMtime || undefined },
      });
      toast(action === "disable" ? `已禁用 ${name}（隔离区可恢复）` : `已恢复 ${name}`, "success");
    }, { busyLabel: action === "disable" ? "禁用中…" : "恢复中…" });
  } catch (error) {
    toast(`操作失败：${error.message}`, "error", 6000);
  }
  void loadCapabilities();
}

/** 当前筛选命中的 skill（与矩阵渲染同一口径，保证"看到什么就批量什么"）。 */
function visibleSkillItems() {
  const items = state.capabilitiesData?.skills?.items ?? [];
  const filter = String(state.capabilityFilter ?? "").trim().toLowerCase();
  if (!filter) return items;
  return items.filter((skill) => `${skill.code} ${skill.description ?? ""} ${skill.path ?? ""}`.toLowerCase().includes(filter));
}

/** 只收集"当前状态与目标不同"的格子——已是目标状态的不重复提交，批量条数即真实变更数。 */
function skillMatrixTargets({ memberId = null, skillCode = null, enabled }) {
  const skills = state.capabilitiesData?.skills;
  if (!skills || skills.configurationStatus?.failClosed === true) return [];
  const states = skills.agentSkillStates ?? {};
  const members = (memberId ? [memberId] : skills.memberIds ?? [])
    .filter((id) => states[id]?.failClosed !== true);
  const items = skillCode
    ? (skills.items ?? []).filter((skill) => skill.code === skillCode)
    : visibleSkillItems();
  const targets = [];
  for (const skill of items) {
    for (const id of members) {
      const current = !(states[id]?.disabledSkills ?? []).includes(skill.code);
      if (current !== enabled) targets.push({ agentId: id, skill: skill.code });
    }
  }
  return targets;
}

/**
 * 矩阵批量声明：复用单条 PUT 原子接口（不新增批量写面），受控并发 + 逐条失败回报。
 * 一次可能改动上百条声明，因此按影响面二次确认；部分失败如实分开报，不伪装整批成功。
 */
async function applySkillMatrixBulk(targets, enabled, scopeLabel) {
  if (!targets.length) {
    toast("这些格子已经是目标状态，无需变更", "info", 2400);
    return;
  }
  const proceed = await confirmAction({
    eyebrow: "批量 Skill 声明",
    title: `${enabled ? "声明" : "取消"} ${targets.length} 条 Skill？`,
    rows: [
      ["作用范围", scopeLabel],
      ["实际变更", `${targets.length} 条（已是目标状态的不重复提交）`],
      ["生效面", "编排提示词中的 Skill 声明；不改变运行时权限与工具沙箱"],
    ],
    warning: enabled ? "" : "取消后这些成员的编排提示词将不再声明对应 Skill。",
    confirmLabel: enabled ? "全部声明" : "全部取消",
    danger: !enabled,
  });
  if (!proceed) return;
  const failures = [];
  const queue = [...targets];
  const states = state.capabilitiesData?.skills?.agentSkillStates ?? {};
  await Promise.all(Array.from({ length: Math.min(4, queue.length) }, async () => {
    while (queue.length) {
      const target = queue.shift();
      try {
        await request("/api/capabilities/agent-skill", { method: "PUT", body: { agentId: target.agentId, skill: target.skill, enabled } });
        const entry = states[target.agentId];
        if (entry) {
          const list = new Set(entry.disabledSkills ?? []);
          if (enabled) list.delete(target.skill);
          else list.add(target.skill);
          entry.disabledSkills = [...list];
        }
      } catch (error) {
        failures.push(`${agentLabel(target.agentId)} / ${target.skill}：${error.message}`);
      }
    }
  }));
  renderCapabilities();
  if (failures.length) {
    toast(`${targets.length - failures.length} 条已应用，${failures.length} 条失败`, "error", 8000);
    appendDiagnostic(`Skill 批量声明部分失败：\n${failures.slice(0, 8).join("\n")}${failures.length > 8 ? `\n…另有 ${failures.length - 8} 条` : ""}`, "error");
  } else {
    toast(`${targets.length} 条 Skill 声明已${enabled ? "应用" : "取消"}`, "success", 3000);
  }
}

async function toggleAgentSkill(checkbox) {
  const [agentId, skill] = String(checkbox.dataset.skillToggle).split("::");
  const enabled = checkbox.checked;
  checkbox.disabled = true;
  try {
    await request("/api/capabilities/agent-skill", { method: "PUT", body: { agentId, skill, enabled } });
    const states = state.capabilitiesData?.skills?.agentSkillStates;
    if (states?.[agentId]) {
      const list = new Set(states[agentId].disabledSkills ?? []);
      if (enabled) list.delete(skill);
      else list.add(skill);
      states[agentId].disabledSkills = [...list];
    }
    toast(`${agentLabel(agentId)} ${enabled ? "启用" : "禁用"} ${skill}`, "success", 2000);
  } catch (error) {
    checkbox.checked = !enabled; // 失败回滚勾选态
    toast(`保存失败：${error.message}`, "error", 5000);
  }
  checkbox.disabled = false;
}

function renderOverview() {
  if (state.view !== "overview") return;
  const okCount = state.components.filter((item) => normalizeStatus(item.status) === "ok").length;
  const errorCount = state.components.filter((item) => normalizeStatus(item.status) === "error").length;
  const activeRuns = state.runs.filter((run) => ACTIVE_RUN_STATES.has(run.status));
  const driftSources = state.sources.filter((source) => ["drift", "warning", "stale"].includes(source.status));

  elements["metric-services"].textContent = state.components.length ? `${okCount}/${state.components.length}` : "--";
  elements["metric-services-detail"].textContent = errorCount ? `${errorCount} 个组件异常` : okCount ? "已响应组件 / 已登记组件" : "等待健康检查";
  elements["metric-runs"].textContent = String(activeRuns.length);
  elements["metric-runs-detail"].textContent = state.runs.length ? `${state.runs.length} 个任务已登记` : "暂无运行数据";
  elements["metric-sources"].textContent = state.sources.length ? String(state.sources.length) : "--";
  elements["metric-sources-detail"].textContent = driftSources.length ? `${driftSources.length} 项存在漂移` : state.sources.length ? "配置索引已加载" : "等待配置索引";
  setEventState(state.eventState);

  elements["health-updated"].textContent = state.health?.checked_at
    ? `检查于 ${formatDate(state.health.checked_at)}`
    : state.health
      ? `更新于 ${formatDate(new Date())}`
      : "尚未完成检查";
  const healthClass = errorCount ? "error" : okCount === state.components.length ? "ok" : "warning";
  elements["health-summary"].className = `status-label is-${healthClass}`;
  elements["health-summary"].textContent = errorCount ? "存在异常" : okCount === state.components.length ? "全部正常" : "状态不完整";

  if (elements["overview-health-pills"]) {
    elements["overview-health-pills"].innerHTML = state.components.length
      ? state.components.map((item) => {
        const status = normalizeStatus(item.status);
        const label = statusText(item.rawStatus ?? item.status);
        return `<span class="health-pill is-${status}"><span>${escapeHtml(item.name)}</span><strong>${escapeHtml(label)}</strong></span>`;
      }).join("")
      : "";
  }
  elements["health-list"].innerHTML = state.components.length
    ? state.components
        .map((item) => {
          const status = normalizeStatus(item.status);
          const label = statusText(item.rawStatus ?? item.status); // 原始态专属文案（待命/未安装/未配置）
          return `
            <div class="health-row">
              <div class="health-main">
                <span class="status-dot is-${status}" aria-hidden="true"></span>
                <div>
                  <strong>${escapeHtml(item.name)}</strong>
                  <span>${escapeHtml(item.detail || label)}</span>
                </div>
              </div>
              <span class="health-latency">${escapeHtml(label)}${item.latency == null ? "" : ` · ${formatDuration(item.latency)}`}</span>
            </div>`;
        })
        .join("")
    : emptyMarkup("尚无组件数据", "健康端点未返回组件清单");
  renderOverviewUsage();

  const recentRuns = [...state.runs]
    .sort((a, b) => new Date(b.updatedAt ?? b.createdAt ?? 0) - new Date(a.updatedAt ?? a.createdAt ?? 0))
    .slice(0, 6);
  elements["overview-run-list"].innerHTML = recentRuns.length
    ? recentRuns.map((run) => runRowMarkup(run, true)).join("")
    : emptyMarkup("尚无任务", "从协作台发起第一项受控任务");

  const overviewEvents = state.events.slice(0, 8);
  elements["overview-event-body"].innerHTML = overviewEvents.length
    ? overviewEvents
        .map(
          (event) => `
          <tr>
            <td class="mono">${escapeHtml(formatTime(event.timestamp))}</td>
            <td>${escapeHtml(event.type)}</td>
            <td>${escapeHtml(event.agentId || event.sessionId || "control")}</td>
            <td title="${escapeHtml(event.summary)}">${escapeHtml(event.summary)}</td>
          </tr>`,
        )
        .join("")
    : `<tr><td colspan="4" class="subtle">等待标准化事件。</td></tr>`;
  elements["event-sequence"].textContent = `seq ${state.events[0]?.seq ?? "--"}`;
}

function emptyMarkup(title, detail = "", streamKey = "") {
  const keyAttribute = streamKey ? ` data-stream-key="${escapeHtml(streamKey)}"` : "";
  return `<div class="empty-state"${keyAttribute}><strong>${escapeHtml(title)}</strong><span>${escapeHtml(detail)}</span></div>`;
}

function catalogMember(id) {
  const catalogs = [
    state.memberCatalog,
    state.bootstrap?.memberCatalog,
    state.bootstrap?.teamCatalog,
  ];
  for (const catalog of catalogs) {
    if (!Array.isArray(catalog)) continue;
    const found = catalog.find((item) => item.id === id);
    if (found) return found;
  }
  return null;
}

function agentFaceMarkup(id, {
  className = "avatar-photo",
  iconClass = "cli-logo",
  initialsClass = "agent-pick-fallback",
} = {}) {
  const cli = agentCli(id);
  const member = catalogMember(id) || { id, avatar: "", provider: cli, label: agentLabel(id) };
  return memberFaceMarkup(
    {
      ...member,
      label: member.label || agentLabel(id),
      shortLabel: member.shortLabel || AGENT_SHORT[id] || "",
    },
    {
      className,
      iconClass,
      fallback: cli ? cliIconMarkup(cli, iconClass) : "",
      initialsClass,
    },
  );
}

// agent 徽标选择器：项目内新建会话后，只允许选择真实 CLI 成员。
// 卡片副行接成员真实职责（BOT_MEMBER_ROLE_LABELS 归一化角色键 → 中文；自由文本原样透出），
// 让「发送给谁」一屏可比对谁做什么，而不是四张卡都写「直达成员 CLI」；主脑保留发送语义。
function agentPickRoleLine(id, coordinatorId) {
  const storedRole = String(catalogMember(id)?.role || "").trim();
  const roleLabel = BOT_MEMBER_ROLE_LABELS[storedRole] || storedRole;
  if (id === coordinatorId) return roleLabel ? `${roleLabel} · 直接发送` : "团队主脑 · 直接发送";
  return roleLabel ? `${roleLabel} · 直达 CLI` : "直达成员 CLI";
}

function agentPickerMarkup() {
  const { team, members, coordinator, name } = currentTeamMembers();
  // 数字键直达提示只在 1-9 可容纳时展示（键盘监听同门槛，见 bindEvents 的 picker 快捷键段）
  const keyHint = (index) => index < 9 ? `<kbd class="agent-pick-key" aria-hidden="true">${index + 1}</kbd>` : "";
  const cards = members
    .map((id, index) => {
      return `<button class="agent-pick-card is-agent-${agentSlug(id)}" type="button" data-pick-agent="${escapeHtml(id)}" title="直接发送给 ${escapeHtml(agentLabel(id))}">
        ${keyHint(index)}<span class="agent-pick-logo" aria-hidden="true">${agentFaceMarkup(id)}</span>
        <strong>${escapeHtml(agentLabel(id))}</strong>
        <span>${escapeHtml(agentPickRoleLine(id, coordinator))}</span>
      </button>`;
    })
    .join("");
  return `
    <div class="empty-state welcome-state" data-stream-key="empty:agent-picker">
      <h2 class="welcome-hero is-picker">发送给谁？</h2>
      <span class="welcome-sub">选择成员即直达其 CLI，并使用该成员专属的模型、Effort、权限与命令</span>
      <span class="picker-team-meta">团队 ${escapeHtml(name)} · ${members.length} 席${team?.coordinator ? "" : " · 未设主脑"} · 按数字键直达</span>
      <div class="agent-pick-grid">${cards}</div>
    </div>`;
}
